class DiscordForbiddenError(Exception):
    """Raised on a 403 from Discord's REST API (missing permissions)."""
    pass


class DiscordAPIError(Exception):
    """Raised on any other non-2xx response from Discord's REST API."""
    pass


DISCORD_EPOCH_MS = 1420070400000

# How long to sleep (seconds) when a rate-limit is hit before retrying once.
_RATE_LIMIT_RETRY_CAP = 30.0


def _time_snowflake(dt, high: bool = False) -> int:
    """Reimplementation of discord.utils.time_snowflake (no REST/gateway
    equivalent exists) - converts a datetime into the snowflake that would
    have been minted at that moment, for use as a `before=` cursor anchor."""
    ms = int(dt.timestamp() * 1000) - DISCORD_EPOCH_MS
    if high:
        return (ms << 22) | 0x3FFFFF
    return ms << 22


def _format_discord_user(author: dict) -> str:
    """Reimplementation of str(discord.User) from a REST author dict.
    Discord's new username system has discriminator '0' (no #tag); the
    legacy system has a real 4-digit discriminator."""
    username = author.get('username', 'unknown')
    discriminator = author.get('discriminator')
    if discriminator and discriminator != '0':
        return f"{username}#{discriminator}"
    return username


class _RestMessage:
    """Thin adapter so _aggregate_history_page's logic can stay nearly
    identical to the discord.py-object version, instead of rewriting every
    attribute access as dict lookups inline. Wraps one raw message dict
    from Discord's REST API."""

    def __init__(self, data: dict):
        self._data = data
        self.id = int(data['id'])
        self.webhook_id = data.get('webhook_id')
        author = data.get('author')
        self.author = _RestUser(author) if author else None
        self.created_at = datetime.fromisoformat(
            data['timestamp'].replace('Z', '+00:00'))
        self.content = data.get('content', '')
        self.attachments = data.get('attachments', [])
        self.embeds = data.get('embeds', [])
        self.mentions = [_RestUser(m) for m in data.get('mentions', [])]


class _RestUser:
    """Thin adapter for a REST author/mention dict."""

    def __init__(self, data: dict):
        self.id = int(data['id'])
        self.bot = bool(data.get('bot', False))
        self._data = data

    def __str__(self):
        return _format_discord_user(self._data)


class GrowthForecaster:
    """
    Advanced growth forecasting system using:
    - 7-day moving average smoothing
    - Linear regression on smoothed data
    - Spike/anomaly detection
    """

    def __init__(self, days_data: List[Dict]):
        self.raw_data = self._extract_counts(days_data)
        self.dates = [d['date'] for d in days_data]
        self.n = len(self.raw_data)
        self.rate_limiter = get_rate_limiter()

    def _extract_counts(self, days_data: List[Dict]) -> List[float]:
        return [float(d.get('count', 0)) for d in days_data]

    def calculate_moving_average(self, window: int = 7) -> List[float]:
        if self.n < 2:
            return self.raw_data.copy()
        window = min(window, self.n)
        moving_avg = []
        for i in range(self.n):
            if i < window - 1:
                avg = sum(self.raw_data[:i+1]) / (i + 1)
            else:
                start_idx = i - window + 1
                avg = sum(self.raw_data[start_idx:i+1]) / window
            moving_avg.append(avg)
        return moving_avg

    def linear_regression(self, y_values: List[float]) -> Dict[str, float]:
        n = len(y_values)
        if n == 0:
            return {'slope': 0, 'intercept': 0, 'r2': 0, 'prediction': 0}
        if n == 1:
            return {'slope': 0, 'intercept': y_values[0], 'r2': 1.0, 'prediction': y_values[0]}

        x_values = list(range(n))
        x_mean = sum(x_values) / n
        y_mean = sum(y_values) / n

        numerator = sum((x - x_mean) * (y - y_mean)
                        for x, y in zip(x_values, y_values))
        denominator = sum((x - x_mean) ** 2 for x in x_values)
        slope = numerator / denominator if denominator != 0 else 0
        intercept = y_mean - slope * x_mean

        y_pred = [slope * x + intercept for x in x_values]
        ss_res = sum((y - yp) ** 2 for y, yp in zip(y_values, y_pred))
        ss_tot = sum((y - y_mean) ** 2 for y in y_values)
        r2 = 1 - (ss_res / ss_tot) if ss_tot != 0 else 0

        next_prediction = slope * n + intercept

        return {
            'slope': slope,
            'intercept': intercept,
            'r2': max(0, min(1, r2)),
            'prediction': max(0, next_prediction)
        }

    def detect_spikes(self, lookback_days: int = 14, threshold: float = 2.0) -> Dict[str, Any]:
        if self.n < 3:
            return {'status': 'normal', 'deviation_percent': 0, 'is_spike': False,
                    'direction': 'none', 'z_score': 0, 'expected': 0, 'actual': 0}

        lookback = min(lookback_days, self.n - 1)
        recent_data = self.raw_data[-lookback-1:-
                                    1] if lookback > 0 else self.raw_data[:-1]

        if len(recent_data) < 2:
            return {'status': 'normal', 'deviation_percent': 0, 'is_spike': False,
                    'direction': 'none', 'z_score': 0, 'expected': 0, 'actual': 0}

        baseline_mean = sum(recent_data) / len(recent_data)
        if len(recent_data) > 1:
            variance = sum((x - baseline_mean) **
                           2 for x in recent_data) / (len(recent_data) - 1)
            baseline_std = math.sqrt(variance) if variance > 0 else 0
        else:
            baseline_std = 0

        latest_value = self.raw_data[-1]

        if baseline_std == 0:
            if latest_value > baseline_mean * 1.5:
                status = 'positive_spike'
                direction = 'up'
                is_spike = True
            elif latest_value < baseline_mean * 0.5:
                status = 'negative_spike'
                direction = 'down'
                is_spike = True
            else:
                status = 'normal'
                direction = 'none'
                is_spike = False
            z_score = (latest_value - baseline_mean) / (baseline_mean + 1)
        else:
            z_score = (latest_value - baseline_mean) / baseline_std
            if z_score > threshold:
                status = 'positive_spike'
                is_spike = True
                direction = 'up'
            elif z_score < -threshold:
                status = 'negative_spike'
                is_spike = True
                direction = 'down'
            else:
                status = 'normal'
                is_spike = False
                direction = 'none'

        percent_deviation = (
            (latest_value - baseline_mean) / (baseline_mean + 1)) * 100

        return {
            'status': status,
            'deviation_percent': round(percent_deviation, 2),
            'is_spike': is_spike,
            'direction': direction,
            'z_score': round(z_score, 2),
            'expected': round(baseline_mean, 2),
            'actual': latest_value
        }

    def calculate_volatility(self, window: int = 14) -> float:
        if self.n < 3:
            return 0.0
        window = min(window, self.n)
        recent_data = self.raw_data[-window:]
        data_mean = sum(recent_data) / len(recent_data)
        if data_mean == 0:
            return 0.0
        if len(recent_data) > 1:
            variance = sum((x - data_mean) **
                           2 for x in recent_data) / (len(recent_data) - 1)
            data_std = math.sqrt(variance) if variance > 0 else 0
        else:
            data_std = 0
        return round(data_std / data_mean, 3)

    def forecast(self, days_ahead: int = 30) -> Dict[str, Any]:
        if self.n == 0:
            return {
                'baseline_prediction': 0,
                'trend_slope': 0,
                'daily_growth_rate': 0,
                'growth_rate_percent': 0,
                'r2_confidence': 0,
                'volatility': 0,
                'spike_status': 'normal',
                'spike_details': {'status': 'normal', 'deviation_percent': 0, 'is_spike': False},
                'percent_deviation_from_expected': 0,
                'future_predictions': [0] * min(days_ahead, 30),
                'trend_direction': 'stable',
                'data_points_analyzed': 0,
                'smoothed_data': []
            }

        smoothed_data = self.calculate_moving_average(7)
        regression = self.linear_regression(smoothed_data)
        spike_info = self.detect_spikes()
        volatility = self.calculate_volatility()

        # FIX: Allow projections up to 5 years (1825 days) but cap based on available data
        # If we have less than 30 days of historical data, limit projections to 2x historical days
        max_allowed_days = 1825  # 5 years max

        if self.n < 30:
            # If we have very little historical data, limit projections
            max_allowed_days = min(days_ahead, self.n * 2, 365)
        else:
            max_allowed_days = min(days_ahead, 1825)

        future_predictions = []
        n = len(smoothed_data)

        # For very long projections, we need to use the slope and intercept to generate predictions
        # Don't cap at 90 days anymore
        for i in range(1, max_allowed_days + 1):
            pred = regression['slope'] * (n + i - 1) + regression['intercept']
            future_predictions.append(max(0, round(pred, 2)))

        # If the user requested more days than we can reasonably predict, fill the rest with zeros
        # or extrapolate using the last predicted value
        if len(future_predictions) < days_ahead:
            # Extrapolate using the last predicted value plus trend
            last_pred = future_predictions[-1] if future_predictions else 0
            remaining = days_ahead - len(future_predictions)
            for i in range(1, remaining + 1):
                pred = last_pred + (regression['slope'] * i)
                future_predictions.append(max(0, round(pred, 2)))

        daily_growth_rate = regression['slope']
        growth_rate_percent = (
            daily_growth_rate / regression['intercept']) * 100 if regression['intercept'] > 0 else 0

        slope_threshold = 0.01 * \
            (sum(smoothed_data) / len(smoothed_data)) if smoothed_data else 0.01
        if regression['slope'] > slope_threshold:
            trend_direction = 'up'
        elif regression['slope'] < -slope_threshold:
            trend_direction = 'down'
        else:
            trend_direction = 'stable'

        return {
            'baseline_prediction': round(regression['prediction'], 2),
            'trend_slope': round(regression['slope'], 4),
            'daily_growth_rate': round(daily_growth_rate, 4),
            'growth_rate_percent': round(growth_rate_percent, 2),
            'r2_confidence': round(regression['r2'], 3),
            'volatility': volatility,
            'spike_status': spike_info['status'],
            'spike_details': spike_info,
            'percent_deviation_from_expected': spike_info['deviation_percent'],
            'future_predictions': future_predictions[:days_ahead],
            'trend_direction': trend_direction,
            'data_points_analyzed': self.n,
            'smoothed_data': [round(x, 2) for x in smoothed_data]
        }


# ============================================
# AUTH DATABASE MANAGER (unchanged)
# ============================================


class AuthDatabaseManager:
    def __init__(self):
        self.pool = None
        self.rate_limiter = get_rate_limiter()

    async def initialize(self):
        """Initialize database connection pool and create auth tables"""
        try:
            self.pool = await asyncpg.create_pool(
                host=DB_HOST,
                port=DB_PORT,
                database=DB_NAME,
                user=DB_USER,
                password=DB_PASSWORD,
                min_size=10,
                max_size=50,
                command_timeout=10,  # ← Changed from 60 to 10
                max_queries=50000,
                max_inactive_connection_lifetime=300,
                server_settings={
                    'statement_timeout': '10000',  # 10 seconds for any statement
                    'idle_in_transaction_session_timeout': '30000',  # 30 seconds idle
                }
            )
            await self.create_or_update_auth_tables()
        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Failed to initialize auth database connection",
                context={'host': DB_HOST,
                         'port': DB_PORT, 'database': DB_NAME},
                original=e
            )
        except Exception as e:
            raise DatabaseError(
                "Unexpected error initializing auth database",
                context={'host': DB_HOST,
                         'port': DB_PORT, 'database': DB_NAME},
                original=e
            )

    async def close(self):
        """Close database connection pool"""
        if self.pool:
            try:
                await self.pool.close()
            except Exception as e:
                logger.error(f"Error closing auth database pool: {e}")

    async def create_or_update_auth_tables(self):
        """Create or update auth-related tables"""
        try:
            async with self.pool.acquire() as conn:
                async with conn.transaction():
                    # Check if users table exists
                    users_exists = await conn.fetchval("""
                        SELECT EXISTS (
                            SELECT FROM information_schema.tables
                            WHERE table_name = 'users'
                        )
                    """)

                    if not users_exists:
                        await conn.execute("""
                            CREATE TABLE users (
                                id SERIAL PRIMARY KEY,
                                discord_id VARCHAR(50) UNIQUE NOT NULL,
                                username VARCHAR(100) NOT NULL,
                                global_name VARCHAR(100),
                                discriminator VARCHAR(10),
                                avatar VARCHAR(255),
                                email VARCHAR(255),
                                access_token TEXT,
                                refresh_token TEXT,
                                token_expiry TIMESTAMP,
                                selected_server VARCHAR(50),
                                last_login TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                            )
                        """)
                        print("✅ Created users table")
                    else:
                        await self._ensure_users_table_columns(conn)

                    # Check if user_sessions table exists
                    sessions_exists = await conn.fetchval("""
                        SELECT EXISTS (
                            SELECT FROM information_schema.tables
                            WHERE table_name = 'user_sessions'
                        )
                    """)

                    if not sessions_exists:
                        await conn.execute("""
                            CREATE TABLE user_sessions (
                                id SERIAL PRIMARY KEY,
                                session_id VARCHAR(255) UNIQUE NOT NULL,
                                discord_id VARCHAR(50) NOT NULL,
                                ip_address VARCHAR(45),
                                user_agent TEXT,
                                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                expires_at TIMESTAMP NOT NULL,
                                FOREIGN KEY (discord_id) REFERENCES users(discord_id) ON DELETE CASCADE
                            )
                        """)
                        print("✅ Created user_sessions table")
                    else:
                        await self._ensure_sessions_table_columns(conn)

                    # Check if user_servers table exists
                    servers_exists = await conn.fetchval("""
                        SELECT EXISTS (
                            SELECT FROM information_schema.tables
                            WHERE table_name = 'user_servers'
                        )
                    """)

                    if not servers_exists:
                        await conn.execute("""
                            CREATE TABLE user_servers (
                                id SERIAL PRIMARY KEY,
                                discord_id VARCHAR(50) NOT NULL,
                                guild_id VARCHAR(50) NOT NULL,
                                guild_name VARCHAR(100) NOT NULL,
                                guild_icon VARCHAR(255),
                                member_count INTEGER,
                                permissions TEXT DEFAULT '0',
                                last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                UNIQUE(discord_id, guild_id),
                                FOREIGN KEY (discord_id) REFERENCES users(discord_id) ON DELETE CASCADE
                            )
                        """)
                        print("✅ Created user_servers table")

                        # Create indexes
                        await conn.execute("""
                            CREATE INDEX IF NOT EXISTS idx_user_servers_discord_id ON user_servers(discord_id);
                            CREATE INDEX IF NOT EXISTS idx_user_servers_guild_id ON user_servers(guild_id);
                        """)
                    else:
                        # Check if permissions column exists
                        try:
                            permissions_exists = await conn.fetchval("""
                                SELECT EXISTS (
                                    SELECT FROM information_schema.columns
                                    WHERE table_name = 'user_servers' AND column_name = 'permissions'
                                )
                            """)

                            if permissions_exists:
                                # Check column type
                                column_type = await conn.fetchval("""
                                    SELECT data_type 
                                    FROM information_schema.columns 
                                    WHERE table_name = 'user_servers' AND column_name = 'permissions'
                                """)

                                if column_type == 'bigint':
                                    # Convert to TEXT
                                    await conn.execute("""
                                        ALTER TABLE user_servers ALTER COLUMN permissions TYPE TEXT USING permissions::TEXT
                                    """)

                            else:
                                await conn.execute("""
                                    ALTER TABLE user_servers ADD COLUMN permissions TEXT DEFAULT '0'
                                """)

                        except asyncpg.PostgresError as e:
                            logger.error(
                                f"Failed to update permissions column: {e}")
                            raise

                    # ✅ NEW: Check if guilds table exists (GLOBAL TABLE)
                    guilds_exists = await conn.fetchval("""
                        SELECT EXISTS (
                            SELECT FROM information_schema.tables
                            WHERE table_name = 'guilds'
                        )
                    """)

                    if not guilds_exists:
                        await conn.execute("""
                            CREATE TABLE guilds (
                                guild_id VARCHAR(50) PRIMARY KEY,
                                guild_name VARCHAR(100) NOT NULL,
                                guild_icon VARCHAR(255),
                                member_count INTEGER,
                                last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                            )
                        """)
                        print("✅ Created guilds table")

                        # Index for fast lookups
                        await conn.execute("""
                            CREATE INDEX IF NOT EXISTS idx_guilds_guild_id ON guilds(guild_id);
                        """)
                    else:
                        # Optional: ensure columns exist (future-proofing)
                        try:
                            await conn.execute("""
                                ALTER TABLE guilds 
                                ADD COLUMN IF NOT EXISTS guild_name VARCHAR(100)
                            """)
                            await conn.execute("""
                                ALTER TABLE guilds 
                                ADD COLUMN IF NOT EXISTS guild_icon VARCHAR(255)
                            """)
                            await conn.execute("""
                                ALTER TABLE guilds 
                                ADD COLUMN IF NOT EXISTS member_count INTEGER
                            """)
                            await conn.execute("""
                                ALTER TABLE guilds 
                                ADD COLUMN IF NOT EXISTS last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                            """)
                        except asyncpg.PostgresError as e:
                            logger.error(f"Failed to update guilds table: {e}")
                            raise

                    # Create indexes
                    await conn.execute("""
                        CREATE INDEX IF NOT EXISTS idx_users_discord_id ON users(discord_id);
                        CREATE INDEX IF NOT EXISTS idx_sessions_session_id ON user_sessions(session_id);
                        CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON user_sessions(expires_at);
                    """)

                    print("✅ Auth tables created/updated successfully")

        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to create/update auth tables",
                context={'operation': 'create_or_update_auth_tables'},
                original=e
            )
        except Exception as e:
            raise DatabaseError(
                "Unexpected error in auth table creation",
                context={'operation': 'create_or_update_auth_tables'},
                original=e
            )

    async def _ensure_users_table_columns(self, conn):
        """Ensure users table has all required columns"""
        try:
            columns_to_check = [
                ('selected_server', 'VARCHAR(50)'),
                ('access_token', 'TEXT'),
                ('refresh_token', 'TEXT'),
                ('token_expiry', 'TIMESTAMP')
            ]

            for column_name, column_type in columns_to_check:
                exists = await conn.fetchval("""
                    SELECT EXISTS (
                        SELECT FROM information_schema.columns
                        WHERE table_name = 'users' AND column_name = $1
                    )
                """, column_name)

                if not exists:
                    await conn.execute(f"ALTER TABLE users ADD COLUMN {column_name} {column_type}")

        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to update users table columns",
                context={'operation': '_ensure_users_table_columns'},
                original=e
            )

    async def _ensure_sessions_table_columns(self, conn):
        """Ensure user_sessions table has all required columns"""
        try:
            # Check if session_id column exists
            session_id_exists = await conn.fetchval("""
                SELECT EXISTS (
                    SELECT FROM information_schema.columns
                    WHERE table_name = 'user_sessions' AND column_name = 'session_id'
                )
            """)

            if not session_id_exists:
                # Get existing columns for logging
                columns = await conn.fetch("""
                    SELECT column_name FROM information_schema.columns
                    WHERE table_name = 'user_sessions'
                """)
                column_names = [col['column_name'] for col in columns]

                # Backup old table
                await conn.execute("ALTER TABLE user_sessions RENAME TO user_sessions_old")

                # Create new table
                await conn.execute("""
                    CREATE TABLE user_sessions (
                        id SERIAL PRIMARY KEY,
                        session_id VARCHAR(255) UNIQUE NOT NULL,
                        discord_id VARCHAR(50) NOT NULL,
                        ip_address VARCHAR(45),
                        user_agent TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        expires_at TIMESTAMP NOT NULL,
                        FOREIGN KEY (discord_id) REFERENCES users(discord_id) ON DELETE CASCADE
                    )
                """)

                # Try to migrate data
                try:
                    old_columns = await conn.fetch("""
                        SELECT column_name FROM information_schema.columns
                        WHERE table_name = 'user_sessions_old'
                    """)
                    old_column_names = [col['column_name']
                                        for col in old_columns]

                    if 'session_token' in old_column_names:
                        await conn.execute("""
                            INSERT INTO user_sessions (session_id, discord_id, ip_address, user_agent, expires_at)
                            SELECT session_token, discord_id, ip_address, user_agent, expires_at
                            FROM user_sessions_old
                        """)

                except Exception as migrate_error:
                    logger.warning(
                        f"Could not migrate old session data: {migrate_error}")

        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to update sessions table",
                context={'operation': '_ensure_sessions_table_columns'},
                original=e
            )

    # User methods
    async def get_user_by_discord_id(self, discord_id: str) -> Optional[Dict]:
        """Get user by Discord ID"""
        try:
            async with self.pool.acquire() as conn:
                row = await conn.fetchrow(
                    "SELECT * FROM users WHERE discord_id = $1",
                    discord_id
                )
                return dict(row) if row else None
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to fetch user by Discord ID",
                context={'discord_id': discord_id},
                original=e
            )

    async def create_or_update_user(self, user_data: Dict) -> Dict:
        """Create or update user from Discord OAuth data"""
        try:
            async with self.pool.acquire() as conn:
                async with conn.transaction():
                    # Check if user exists
                    existing = await conn.fetchrow(
                        "SELECT * FROM users WHERE discord_id = $1",
                        user_data['discord_id']
                    )

                    if existing:
                        # Update existing user
                        query = """
                            UPDATE users SET
                                username = $2,
                                global_name = $3,
                                discriminator = $4,
                                avatar = $5,
                                email = $6,
                                access_token = $7,
                                refresh_token = $8,
                                token_expiry = $9,
                                last_login = CURRENT_TIMESTAMP
                            WHERE discord_id = $1
                            RETURNING *
                        """
                        row = await conn.fetchrow(
                            query,
                            user_data['discord_id'],
                            user_data['username'],
                            user_data.get('global_name'),
                            user_data.get('discriminator'),
                            user_data.get('avatar'),
                            user_data.get('email'),
                            user_data.get('access_token'),
                            user_data.get('refresh_token'),
                            user_data.get('token_expiry')
                        )
                        return dict(row)
                    else:
                        # Create new user
                        query = """
                            INSERT INTO users (
                                discord_id, username, global_name, discriminator,
                                avatar, email, access_token, refresh_token, token_expiry
                            ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
                            RETURNING *
                        """
                        row = await conn.fetchrow(
                            query,
                            user_data['discord_id'],
                            user_data['username'],
                            user_data.get('global_name'),
                            user_data.get('discriminator'),
                            user_data.get('avatar'),
                            user_data.get('email'),
                            user_data.get('access_token'),
                            user_data.get('refresh_token'),
                            user_data.get('token_expiry')
                        )
                        return dict(row)
        except asyncpg.IntegrityConstraintViolationError as e:
            raise DatabaseIntegrityError(
                "Failed to create/update user - integrity violation",
                context={'discord_id': user_data['discord_id']},
                original=e
            )
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to create/update user",
                context={'discord_id': user_data['discord_id']},
                original=e
            )

    async def update_user_selected_server(self, discord_id: str, guild_id: Optional[str]) -> bool:
        """Update user's selected server preference"""
        try:
            async with self.pool.acquire() as conn:
                result = await conn.execute(
                    "UPDATE users SET selected_server = $2 WHERE discord_id = $1",
                    discord_id, guild_id
                )
                return result == "UPDATE 1"
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to update user selected server",
                context={'discord_id': discord_id, 'guild_id': guild_id},
                original=e
            )

    # Session methods
    async def create_session(self, discord_id: str, ip_address: Optional[str], user_agent: Optional[str]) -> str:
        """Create a new session for user"""
        try:
            session_id = secrets.token_urlsafe(32)
            expires_at = datetime.utcnow() + timedelta(days=30)

            async with self.pool.acquire() as conn:
                await conn.execute(
                    """
                    INSERT INTO user_sessions (session_id, discord_id, ip_address, user_agent, expires_at)
                    VALUES ($1, $2, $3, $4, $5)
                    """,
                    session_id, discord_id, ip_address, user_agent, expires_at
                )

            return session_id
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to create user session",
                context={'discord_id': discord_id},
                original=e
            )

    async def get_session(self, session_id: str) -> Optional[Dict]:
        """Get session by ID"""
        try:
            async with self.pool.acquire() as conn:
                # Clean up expired sessions first
                await conn.execute(
                    "DELETE FROM user_sessions WHERE expires_at < CURRENT_TIMESTAMP"
                )

                row = await conn.fetchrow(
                    "SELECT * FROM user_sessions WHERE session_id = $1 AND expires_at > CURRENT_TIMESTAMP",
                    session_id
                )
                return dict(row) if row else None
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to fetch session",
                context={'session_id': session_id},
                original=e
            )

    async def delete_session(self, session_id: str) -> bool:
        """Delete a session"""
        try:
            async with self.pool.acquire() as conn:
                result = await conn.execute(
                    "DELETE FROM user_sessions WHERE session_id = $1",
                    session_id
                )
                return result == "DELETE 1"
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to delete session",
                context={'session_id': session_id},
                original=e
            )

    async def delete_all_user_sessions(self, discord_id: str) -> int:
        """Delete all sessions for a user"""
        try:
            async with self.pool.acquire() as conn:
                result = await conn.execute(
                    "DELETE FROM user_sessions WHERE discord_id = $1",
                    discord_id
                )
                return int(result.split()[-1]) if "DELETE" in result else 0
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to delete user sessions",
                context={'discord_id': discord_id},
                original=e
            )

    # Server cache methods
    async def update_user_servers(self, discord_id: str, servers: List[Dict]) -> int:
        try:
            async with self.pool.acquire() as conn:
                async with conn.transaction():
                    count = 0
                    for server in servers:
                        # CRITICAL FIX: Force to string and never convert to int
                        permissions = server.get('permissions')

                        # If it's None, use '0'
                        if permissions is None:
                            permissions = '0'
                        # If it's an int (or any number), convert to string
                        elif not isinstance(permissions, str):
                            permissions = str(permissions)

                        # Also ensure guild_id and other IDs are strings where needed
                        await conn.execute("""
                            INSERT INTO user_servers (discord_id, guild_id, guild_name, guild_icon, member_count, permissions)
                            VALUES ($1, $2, $3, $4, $5, $6)
                            ON CONFLICT (discord_id, guild_id) DO UPDATE SET
                                guild_name = EXCLUDED.guild_name,
                                guild_icon = EXCLUDED.guild_icon,
                                member_count = EXCLUDED.member_count,
                                permissions = EXCLUDED.permissions,
                                last_updated = CURRENT_TIMESTAMP
                        """,
                                           discord_id,
                                           # Ensure string
                                           str(server['guild_id']),
                                           server['guild_name'],
                                           server.get('guild_icon'),
                                           server.get('member_count'),
                                           permissions  # Already string
                                           )
                        count += 1
                    return count
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to update user servers",
                context={'discord_id': discord_id},
                original=e
            )

    async def get_user_servers(self, discord_id: str) -> List[Dict]:
        """Get user's cached servers with permissions"""
        try:
            async with self.pool.acquire() as conn:
                rows = await conn.fetch("""
                    SELECT * FROM user_servers
                    WHERE discord_id = $1
                    ORDER BY member_count DESC
                """, discord_id)
                return [dict(row) for row in rows]
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to get user servers",
                context={'discord_id': discord_id},
                original=e
            )

    async def get_all_users(self) -> List[str]:
        """Get all user Discord IDs"""
        try:
            async with self.pool.acquire() as conn:
                rows = await conn.fetch("SELECT discord_id FROM users")
                return [row['discord_id'] for row in rows]
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to get all users",
                original=e
            )

    async def get_user_access_token(self, discord_id: str) -> Optional[str]:
        """Get user's access token (if still valid)"""
        try:
            async with self.pool.acquire() as conn:
                row = await conn.fetchrow("""
                    SELECT access_token, token_expiry
                    FROM users
                    WHERE discord_id = $1
                """, discord_id)

                if row and row['token_expiry']:
                    # Make sure token_expiry is timezone-aware for comparison
                    token_expiry = row['token_expiry']
                    if token_expiry.tzinfo is None:
                        token_expiry = token_expiry.replace(
                            tzinfo=timezone.utc)

                    if token_expiry > datetime.now(timezone.utc):
                        return row['access_token']
                return None
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to get user access token",
                context={'discord_id': discord_id},
                original=e
            )

    async def get_user_permissions_from_db(self, discord_id: str, guild_id: str) -> Optional[int]:
        """
        Get user's permissions for a specific guild from user_servers table.
        Returns None if user is not in the guild.
        """
        try:
            async with auth_db.pool.acquire() as conn:
                row = await conn.fetchrow("""
                    SELECT permissions 
                    FROM user_servers 
                    WHERE discord_id = $1 AND guild_id = $2
                """, discord_id, guild_id)

                if row:
                    # Convert permissions to int if it's stored as string
                    permissions = row['permissions']
                    if isinstance(permissions, str):
                        return int(permissions) if permissions else 0
                    return permissions or 0
                return None
        except Exception as e:
            logger.error(f"Error getting permissions from DB: {e}")
            return None


# ============================================
# DISCORD API HELPER
# ============================================


class DiscordAPI:
    def __init__(self):
        self.session = None
        self.rate_limiter = get_rate_limiter()

    async def get_session(self):
        """Get or create aiohttp session"""
        if not self.session:
            self.session = aiohttp.ClientSession()
        return self.session

    async def close(self):
        """Close aiohttp session"""
        if self.session:
            await self.session.close()

    @fastapi_rate_limited(RateLimitType.API, timeout=30.0)
    async def exchange_code(self, code: str) -> Dict:
        """Exchange OAuth code for access token"""
        session = await self.get_session()

        data = {
            'client_id': CLIENT_ID,
            'client_secret': CLIENT_SECRET,
            'grant_type': 'authorization_code',
            'code': code,
            'redirect_uri': DISCORD_REDIRECT_URI
        }

        headers = {'Content-Type': 'application/x-www-form-urlencoded'}

        try:
            async with session.post(DISCORD_TOKEN_URL, data=data, headers=headers) as resp:
                if resp.status != 200:
                    error_text = await resp.text()
                    logger.error(
                        f"Token exchange failed: {resp.status} - {error_text}")
                    raise ExternalAPIError(
                        "Failed to exchange Discord OAuth code",
                        context={
                            'status_code': resp.status,
                            'response': error_text[:200]
                        }
                    )
                return await resp.json()
        except aiohttp.ClientTimeout as e:
            raise ExternalAPITimeoutError(
                "Discord token exchange timed out",
                context={'endpoint': DISCORD_TOKEN_URL},
                original=e
            )
        except aiohttp.ClientError as e:
            raise ExternalAPIError(
                "Discord API request failed during token exchange",
                context={'endpoint': DISCORD_TOKEN_URL},
                original=e
            )

    @fastapi_rate_limited(RateLimitType.API, timeout=30.0)
    async def refresh_token(self, refresh_token: str) -> Dict:
        """Refresh access token"""
        session = await self.get_session()

        data = {
            'client_id': CLIENT_ID,
            'client_secret': CLIENT_SECRET,
            'grant_type': 'refresh_token',
            'refresh_token': refresh_token
        }

        headers = {'Content-Type': 'application/x-www-form-urlencoded'}

        try:
            async with session.post(DISCORD_TOKEN_URL, data=data, headers=headers) as resp:
                if resp.status != 200:
                    raise ExternalAPIError(
                        "Failed to refresh Discord token",
                        context={'status_code': resp.status}
                    )
                return await resp.json()
        except aiohttp.ClientTimeout as e:
            raise ExternalAPITimeoutError(
                "Discord token refresh timed out",
                original=e
            )
        except aiohttp.ClientError as e:
            raise ExternalAPIError(
                "Discord API request failed during token refresh",
                original=e
            )

    @fastapi_rate_limited(RateLimitType.API, timeout=30.0)
    async def get_user_info(self, access_token: str) -> Dict:
        """Get user info from Discord"""
        session = await self.get_session()

        headers = {'Authorization': f'Bearer {access_token}'}

        try:
            async with session.get(DISCORD_USER_URL, headers=headers) as resp:
                if resp.status != 200:
                    raise ExternalAPIError(
                        "Failed to get Discord user info",
                        context={'status_code': resp.status}
                    )
                return await resp.json()
        except aiohttp.ClientTimeout as e:
            raise ExternalAPITimeoutError(
                "Discord user info request timed out",
                original=e
            )
        except aiohttp.ClientError as e:
            raise ExternalAPIError(
                "Discord API request failed during user info fetch",
                original=e
            )

    @fastapi_rate_limited(RateLimitType.API, timeout=30.0)
    async def get_user_guilds(self, access_token: str) -> List[Dict]:
        """Get user's guilds from Discord"""
        session = await self.get_session()

        headers = {'Authorization': f'Bearer {access_token}'}

        try:
            async with session.get(DISCORD_GUILDS_URL, headers=headers) as resp:
                if resp.status != 200:
                    raise ExternalAPIError(
                        "Failed to get Discord user guilds",
                        context={'status_code': resp.status}
                    )
                return await resp.json()
        except aiohttp.ClientTimeout as e:
            raise ExternalAPITimeoutError(
                "Discord user guilds request timed out",
                original=e
            )
        except aiohttp.ClientError as e:
            raise ExternalAPIError(
                "Discord API request failed during user guilds fetch",
                original=e
            )

    @fastapi_rate_limited(RateLimitType.API, timeout=30.0)
    async def check_bot_in_guild(self, guild_id: str) -> Optional[int]:
        """Check if bot is in guild and return member count"""
        session = await self.get_session()

        headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
        url = f"{DISCORD_API_BASE}/guilds/{guild_id}?with_counts=true"

        try:
            async with session.get(url, headers=headers, timeout=5) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    return data.get('approximate_member_count')
                return None
        except aiohttp.ClientTimeout as e:

            return None
        except aiohttp.ClientError as e:

            return None

    async def check_bot_in_guild_bulk(self, guild_ids: List[str]) -> Dict[str, Optional[int]]:
        """Check bot presence in multiple guilds at once with internal rate limiting."""
        session = await self.get_session()
        headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

        result = {}
        rate_limiter = get_rate_limiter()

        for idx, guild_id in enumerate(guild_ids):
            # ✅ Rate limit BEFORE each API call
            if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                print(f"⚠️ Rate limited for guild {guild_id}, waiting...")
                await asyncio.sleep(5)
                # Try one more time
                if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                    print(f"❌ Still rate limited, skipping guild {guild_id}")
                    result[guild_id] = None
                    continue

            try:
                url = f"{DISCORD_API_BASE}/guilds/{guild_id}?with_counts=true"
                async with session.get(url, headers=headers, timeout=5) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        member_count = data.get('approximate_member_count')
                        result[guild_id] = member_count
                    else:
                        result[guild_id] = None
            except aiohttp.ClientError as e:
                result[guild_id] = None

            # Small delay between requests to be gentle
            await asyncio.sleep(0.05)

        present_count = sum(1 for v in result.values() if v is not None)
        print(
            f"✅ Guild Bulk check complete: Bot present in {present_count}/{len(guild_ids)} guilds")

        return result

    async def get_role_members(self, guild_id: str, role_id: str) -> List[int]:
        """
        Get all user IDs that have a specific role from current_role_members table.
        """
        try:
            async with db_stats.pool.acquire() as conn:
                rows = await conn.fetch("""
                    SELECT DISTINCT user_id
                    FROM current_role_members
                    WHERE guild_id = $1 AND role_id = $2
                """, int(guild_id), int(role_id))
                return [row['user_id'] for row in rows]
        except Exception as e:
            logger.error(f"Error fetching role members from table: {e}")
            return []

    async def verify_entities_exist(self, guild_id: str, entity_type: str, entity_ids: List[str]) -> Dict[str, bool]:
        """
        Verify which entities still exist in Discord using BATCH requests.
        Returns dict mapping entity_id -> exists (True/False)
        """
        if not entity_ids:
            return {}

        rate_limiter = get_rate_limiter()

        try:
            session = await self.get_session()
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

            # Handle different entity types with batch operations
            if entity_type == 'user':
                # First, try to get all guild members in one go (much faster)
                if guild_id:
                    try:
                        # Get all members from the guild (paginated, but still fewer calls)
                        members_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/members?limit=1000"
                        member_ids = set()

                        while members_url:
                            # ✅ Rate limit before each paginated request
                            if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                                print(
                                    f"⚠️ Rate limited for guild members fetch, waiting...")
                                await asyncio.sleep(5)
                                continue

                            async with session.get(members_url, headers=headers, timeout=10) as resp:
                                if resp.status == 200:
                                    members = await resp.json()
                                    for member in members:
                                        member_ids.add(
                                            str(member['user']['id']))

                                    # Check for next page
                                    if 'link' in resp.headers:
                                        links = resp.headers['link'].split(',')
                                        next_url = None
                                        for link in links:
                                            if 'rel="next"' in link:
                                                next_url = link[link.find(
                                                    '<')+1:link.find('>')]
                                                break
                                        members_url = next_url
                                    else:
                                        members_url = None
                                else:
                                    members_url = None

                        result = {
                            entity_id: entity_id in member_ids for entity_id in entity_ids}
                        deleted_count = sum(
                            1 for exists in result.values() if not exists)
                        return result

                    except asyncio.TimeoutError:
                        logger.warning(
                            f"Timeout fetching guild members for {guild_id}, falling back to individual requests")
                    except Exception as e:
                        logger.warning(
                            f"Failed to fetch guild members, falling back to individual requests: {e}")

                # Fallback: Process users in batches with concurrency control
                batch_size = 10
                results = {}

                for i in range(0, len(entity_ids), batch_size):
                    batch = entity_ids[i:i+batch_size]
                    tasks = []

                    for entity_id in batch:
                        url = f"{DISCORD_API_BASE}/users/{entity_id}"
                        tasks.append(self._fetch_entity(
                            session, url, entity_id))

                    # Wait for batch to complete
                    batch_results = await asyncio.gather(*tasks, return_exceptions=True)

                    for result_item in batch_results:
                        if isinstance(result_item, Exception):
                            logger.debug(
                                f"Error in batch request: {result_item}")
                            continue
                        entity_id, exists = result_item
                        results[entity_id] = exists

                    # Small delay between batches to avoid rate limits
                    if i + batch_size < len(entity_ids):
                        await asyncio.sleep(0.1)

                deleted_count = sum(
                    1 for exists in results.values() if not exists)

                return results

            elif entity_type in ['channel', 'category']:
                # Fetch ALL channels in ONE request
                url = f"{DISCORD_API_BASE}/guilds/{guild_id}/channels"

                # ✅ Rate limit before the bulk request
                if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                    print(f"⚠️ Rate limited for channel fetch, waiting...")
                    await asyncio.sleep(5)
                    if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                        return {entity_id: True for entity_id in entity_ids}

                async with session.get(url, headers=headers, timeout=10) as resp:
                    if resp.status == 200:
                        channels = await resp.json()

                        if entity_type == 'category':
                            existing_ids = {str(ch['id'])
                                            for ch in channels if ch['type'] == 4}
                        else:  # channel
                            existing_ids = {str(ch['id'])
                                            for ch in channels if ch['type'] != 4}

                        result = {
                            entity_id: entity_id in existing_ids for entity_id in entity_ids}
                        deleted_count = sum(
                            1 for exists in result.values() if not exists)
                        return result
                    else:
                        logger.warning(
                            f"Failed to fetch channels for guild {guild_id}: {resp.status}")
                        return {entity_id: True for entity_id in entity_ids}

            elif entity_type == 'role':
                # Fetch ALL roles in ONE request
                url = f"{DISCORD_API_BASE}/guilds/{guild_id}/roles"

                # ✅ Rate limit before the bulk request
                if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                    print(f"⚠️ Rate limited for role fetch, waiting...")
                    await asyncio.sleep(5)
                    if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                        return {entity_id: True for entity_id in entity_ids}

                async with session.get(url, headers=headers, timeout=10) as resp:
                    if resp.status == 200:
                        roles = await resp.json()
                        existing_ids = {str(r['id']) for r in roles}

                        result = {
                            entity_id: entity_id in existing_ids for entity_id in entity_ids}
                        deleted_count = sum(
                            1 for exists in result.values() if not exists)
                        return result
                    else:
                        logger.warning(
                            f"Failed to fetch roles for guild {guild_id}: {resp.status}")
                        return {entity_id: True for entity_id in entity_ids}

            elif entity_type == 'guild':
                # Check guilds in batches
                results = {}
                batch_size = 10

                for i in range(0, len(entity_ids), batch_size):
                    batch = entity_ids[i:i+batch_size]
                    tasks = []

                    for entity_id in batch:
                        # ✅ Rate limit before each guild check
                        if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                            print(
                                f"⚠️ Rate limited for guild {entity_id}, waiting...")
                            await asyncio.sleep(5)
                            if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                                # Assume exists if rate limited
                                results[entity_id] = True
                                continue

                        url = f"{DISCORD_API_BASE}/guilds/{entity_id}"
                        tasks.append(self._fetch_entity(
                            session, url, entity_id))

                    batch_results = await asyncio.gather(*tasks, return_exceptions=True)

                    for result_item in batch_results:
                        if isinstance(result_item, Exception):
                            logger.debug(
                                f"Error checking guild: {result_item}")
                            continue
                        entity_id, exists = result_item
                        results[entity_id] = exists

                    if i + batch_size < len(entity_ids):
                        await asyncio.sleep(0.1)

                return results

            else:
                return {entity_id: True for entity_id in entity_ids}

        except Exception as e:
            logger.error(f"Error verifying entities: {e}")
            return {entity_id: True for entity_id in entity_ids}

    async def _fetch_entity(self, session, url: str, entity_id: str) -> tuple:
        """
        Helper method to fetch a single entity with error handling.
        Returns (entity_id, exists)
        """
        rate_limiter = get_rate_limiter()

        # ✅ Rate limit before the API call
        if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
            print(f"⚠️ Rate limited for entity {entity_id}, waiting...")
            await asyncio.sleep(5)
            if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                return (entity_id, True)  # Assume exists if rate limited

        try:
            async with session.get(url, headers={'Authorization': f'Bot {DISCORD_TOKEN}'}, timeout=5) as resp:
                return (entity_id, resp.status == 200)
        except asyncio.TimeoutError:
            logger.debug(f"Timeout checking entity {entity_id}")
            return (entity_id, False)
        except Exception as e:
            logger.debug(f"Error checking entity {entity_id}: {e}")
            return (entity_id, False)

    async def filter_deleted_entities(self, guild_id: str, entity_type: str, items: List[Dict], id_field: str = 'id') -> List[Dict]:
        """
        Filter out entities that have been deleted from Discord.

        Args:
            guild_id: The guild ID
            entity_type: Type of entity ('user', 'channel', 'category', 'role', 'guild')
            items: List of items to filter
            id_field: The field name containing the entity ID in each item

        Returns:
            Filtered list with only existing entities
        """
        if not items:
            return items

        entity_ids = [str(item[id_field])
                      for item in items if id_field in item]

        if not entity_ids:
            return items

        existence_map = await self.verify_entities_exist(guild_id, entity_type, entity_ids)

        filtered_items = []
        deleted_count = 0

        for item in items:
            entity_id = str(item[id_field])
            if existence_map.get(entity_id, True):  # Default to True if not in map
                filtered_items.append(item)
            else:
                deleted_count += 1

        return filtered_items

    async def get_text_channels_from_db(self, guild_id: int) -> list:
        """Fetch text channels from local discord_channels table instead of Discord API."""
        async with self.pool.acquire() as conn:
            rows = await conn.fetch('''
                SELECT channel_id, channel_name, category_id
                FROM discord_channels
                WHERE guild_id = $1
                AND channel_type = 'text'
                AND is_deleted = FALSE
                ORDER BY channel_id
            ''', guild_id)
        return [
            {
                'id': str(row['channel_id']),
                'name': row['channel_name'],
                'parent_id': str(row['category_id']) if row['category_id'] else None,
            }
            for row in rows
        ]

    async def get_channel_history(self, channel_id, before=None, limit: int = 100) -> list:
        session = await self.get_session()
        headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
        url = f"{DISCORD_API_BASE}/channels/{channel_id}/messages"
        params = {"limit": limit}
        if before is not None:
            params["before"] = str(before)
        async with session.get(url, headers=headers, params=params) as resp:
            if resp.status == 429:
                retry_after = float(resp.headers.get('Retry-After', 1.0))
                raise ExternalAPIRateLimitError(
                    f"Rate limited reading history for channel {channel_id}",
                    context={'api': 'discord', 'endpoint': 'channels/{channel_id}/messages',
                             'channel_id': channel_id, 'retry_after': retry_after}
                )
            if resp.status != 200:
                body = await resp.text()
                raise ExternalAPIError(
                    f"Failed to fetch history for channel {channel_id}",
                    context={'api': 'discord', 'endpoint': 'channels/{channel_id}/messages',
                             'channel_id': channel_id, 'status_code': resp.status, 'body': body}
                )
            return await resp.json()

    async def get_bot_user_id(self) -> int:
        if getattr(self, '_bot_user_id', None) is not None:
            return self._bot_user_id
        session = await self.get_session()
        headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
        url = f"{DISCORD_API_BASE}/users/@me"
        async with session.get(url, headers=headers) as resp:
            if resp.status == 429:
                retry_after = float(resp.headers.get('Retry-After', 1.0))
                raise ExternalAPIRateLimitError(
                    "Rate limited fetching bot user",
                    context={'api': 'discord', 'endpoint': 'users/@me',
                             'retry_after': retry_after}
                )
            if resp.status != 200:
                body = await resp.text()
                raise ExternalAPIError(
                    "Failed to fetch bot user",
                    context={'api': 'discord', 'endpoint': 'users/@me',
                             'status_code': resp.status, 'body': body}
                )
            data = await resp.json()
        self._bot_user_id = int(data['id'])
        return self._bot_user_id

    async def get_bot_joined_at(self, guild_id):
        bot_user_id = await self.get_bot_user_id()
        session = await self.get_session()
        headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
        url = f"{DISCORD_API_BASE}/guilds/{guild_id}/members/{bot_user_id}"
        async with session.get(url, headers=headers) as resp:
            if resp.status == 429:
                retry_after = float(resp.headers.get('Retry-After', 1.0))
                raise ExternalAPIRateLimitError(
                    f"Rate limited fetching bot member for guild {guild_id}",
                    context={'api': 'discord', 'endpoint': 'guilds/{guild_id}/members/{user_id}',
                             'guild_id': guild_id, 'retry_after': retry_after}
                )
            if resp.status != 200:
                return None
            data = await resp.json()
        joined_at_str = data.get('joined_at')
        if not joined_at_str:
            return None
        return datetime.fromisoformat(joined_at_str)


