def ensure_aware(dt: Optional[datetime]) -> Optional[datetime]:
    """Convert naive datetime to aware UTC datetime."""
    if dt is None:
        return None
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)
