# ============================================


class DatabaseStatsAPI:
    def __init__(self):
        self.pool = None
        self.redis = None
        self.db_connected = False
        self.redis_connected = False
        self.blacklist_cache = {}
        self.cache_ttl = 300  # 5 minutes
        self.voice_state_bits = Constants.VOICE_STATE_BITS
        self.role_members_cache = {}
        self.role_cache_ttl = 300  # 5 minutes
        self.entity_cache = {}  # {cache_key: (timestamp, exists_dict)}
        self.entity_cache_ttl = 3600  # 1 hour cache for entity existence
        self._stat_toggle_cache: Dict[int, Dict[str, bool]] = {}
        self._stat_toggle_cache_time: Dict[int, float] = {}
        self._module_access_cache: Dict[int, Dict[str, Dict[str, Any]]] = {}
        self._module_access_cache_time: Dict[int, float] = {}
        self.rate_limiter = get_rate_limiter()
        self.fernet = fernet
        print(
            f"✅ Fernet initialized successfully, self.fernet = {self.fernet is not None}")

    async def verify_entities_exist_with_cache(self, guild_id: str, entity_type: str, entity_ids: List[str]) -> Dict[str, bool]:
        """Cached version of verify_entities_exist"""
        if not entity_ids:
            return {}

        # Create cache key
        cache_key = f"{guild_id}:{entity_type}:{','.join(sorted(entity_ids))}"

        # Check cache
        if cache_key in self.entity_cache:
            timestamp, cached_result = self.entity_cache[cache_key]
            if (datetime.now() - timestamp).total_seconds() < self.entity_cache_ttl:
                # Cache hit - return only requested entities
                return {entity_id: cached_result.get(entity_id, True) for entity_id in entity_ids}

        # Cache miss - fetch fresh
        result = await self.verify_entities_exist(guild_id, entity_type, entity_ids)

        # Store in cache
        self.entity_cache[cache_key] = (datetime.now(), result)

        # Clean old cache entries periodically
        if len(self.entity_cache) > 100:
            now = datetime.now()
            self.entity_cache = {
                k: v for k, v in self.entity_cache.items()
                if (now - v[0]).total_seconds() < self.entity_cache_ttl
            }

        return result

    def classify_channel_type(self, channel_type: int) -> str:
        """
        Classify Discord channel types into our categories:
        - "text": 0 (text), 5 (announcement_thread), 10 (news_thread),
                  11 (public_thread), 12 (
                      private_thread), 15 (forum), 16 (media)
        - "voice": 2 (voice), 13 (stage)
        - "category": 4 (category)
        """
        text_types = {0, 5, 10, 11, 12, 15, 16}
        voice_types = {2, 13}

        if channel_type in text_types:
            return "text"
        elif channel_type in voice_types:
            return "voice"
        elif channel_type == 4:
            return "category"
        else:
            # Log unknown channel types for debugging
            logger.warning(f"Unknown Discord channel type: {channel_type}")
            return "unknown"

    async def cache_user_server(self, discord_id: str, guild_id: str):
        """Cache user's selected server in Redis for faster access"""
        if not self.redis or not self.redis_connected:
            return

        try:
            cache_key = f"user_server:{discord_id}"
            # Cache for 1 hour
            await self.redis.setex(cache_key, 3600, guild_id)

        except Exception as e:
            logger.warning(f"Failed to cache user server: {e}")

    async def get_cached_user_server(self, discord_id: str) -> Optional[str]:
        """Get cached user server from Redis"""
        if not self.redis or not self.redis_connected:
            return None

        try:
            cache_key = f"user_server:{discord_id}"
            guild_id = await self.redis.get(cache_key)
            return guild_id
        except Exception as e:
            logger.warning(f"Failed to get cached user server: {e}")
            return None

    async def invalidate_user_server_cache(self, discord_id: str):
        """Invalidate user server cache"""
        if not self.redis or not self.redis_connected:
            return

        try:
            cache_key = f"user_server:{discord_id}"
            await self.redis.delete(cache_key)

        except Exception as e:
            logger.warning(f"Failed to invalidate user server cache: {e}")

    async def initialize(self):
        """Initialize database connection"""
        try:
            # Updated pool settings
            self.pool = await asyncpg.create_pool(
                host=DB_HOST,
                port=DB_PORT,
                database=DB_NAME,
                user=DB_USER,
                password=DB_PASSWORD,
                min_size=10,                      # Keep as is
                max_size=50,                      # Keep as is
                command_timeout=10,               # ✅ 10 seconds max for any query
                max_queries=50000,                # Keep as is
                max_inactive_connection_lifetime=300,  # Keep as is
                # ADD THESE:
                # Connection acquisition timeout (30 seconds)
                timeout=30,
                server_settings={
                    # Postgres statement timeout (10 seconds)
                    'statement_timeout': '10000',
                    'idle_in_transaction_session_timeout': '30000'  # 30 seconds
                }
            )
            self.db_connected = True

            # Initialize Redis connection with connection pool
            try:
                self.redis = await redis.from_url(
                    f"redis://{REDIS_HOST}:{REDIS_PORT}/{REDIS_DB}",
                    password=REDIS_PASSWORD,
                    decode_responses=True,
                    max_connections=20  # Add connection pool for Redis
                )

                await self.redis.ping()
                self.redis_connected = True

            except Exception as e:
                logger.warning(
                    f"Redis connection failed (caching disabled): {e}")
                self.redis_connected = False
                self.redis = None

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Failed to connect to stats database",
                context={'host': DB_HOST,
                         'port': DB_PORT, 'database': DB_NAME},
                original=e
            )
        except Exception as e:
            raise DatabaseError(
                "Unexpected error initializing stats database",
                context={'host': DB_HOST,
                         'port': DB_PORT, 'database': DB_NAME},
                original=e
            )

    async def close(self):
        """Close database connection"""
        if self.pool:
            try:
                await self.pool.close()
                self.db_connected = False

            except Exception as e:
                logger.error(f"Error closing stats database pool: {e}")

        if self.redis:
            try:
                await self.redis.aclose()  # Note: aclose() not close()
                self.redis_connected = False

            except Exception as e:
                logger.error(f"Error closing Redis connection: {e}")

    async def ensure_indexes(self):
        """Ensure all necessary indexes exist for performance"""
        try:
            conn = await self.get_connection()
            try:
                # User server indexes
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_users_discord_id_selected_server
                    ON users(discord_id, selected_server)
                """)
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_user_servers_discord_id_guild_id
                    ON user_servers(discord_id, guild_id)
                """)
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_user_servers_guild_id
                    ON user_servers(guild_id)
                """)
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_user_servers_last_updated
                    ON user_servers(last_updated)
                """)

                # Voice session history indexes for faster queries
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_voice_session_history_hourly_guild_user
                    ON voice_session_history_hourly(guild_id, user_id)
                """)
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_voice_session_history_hourly_guild_channel
                    ON voice_session_history_hourly(guild_id, channel_id)
                """)
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_voice_session_history_hourly_guild_category
                    ON voice_session_history_hourly(guild_id, category_id)
                """)
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_voice_session_history_hourly_hour
                    ON voice_session_history_hourly(hour)
                """)
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_voice_session_history_hourly_composite
                    ON voice_session_history_hourly(guild_id, user_id, hour)
                """)

                # Message tracking indexes
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_message_tracking_hourly_guild_user
                    ON message_tracking_hourly(guild_id, user_id)
                """)
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_message_tracking_hourly_guild_channel
                    ON message_tracking_hourly(guild_id, channel_id)
                """)
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_message_tracking_hourly_hour
                    ON message_tracking_hourly(hour)
                """)

                # Emoji usage indexes
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_emoji_usage_hourly_guild_user
                    ON emoji_usage_hourly(guild_id, user_id)
                """)

                # User mentions indexes
                await conn.execute("""
                    CREATE INDEX IF NOT EXISTS idx_user_mentions_hourly_guild_mentioned
                    ON user_mentions_hourly(guild_id, mentioned_user_id)
                """)

            finally:
                await self.release_connection(conn)
        except Exception as e:
            logger.error(f"Failed to ensure indexes: {e}")

    async def get_connection(self):
        """Get a database connection from the pool"""
        if not self.pool or not self.db_connected:
            await self.initialize()
        try:
            return await self.pool.acquire()
        except asyncpg.PostgresError as e:
            raise DatabaseConnectionError(
                "Failed to acquire database connection",
                original=e
            )

    async def release_connection(self, conn):
        """Release a database connection back to the pool"""
        await self.pool.release(conn)

