    async def _get_users_with_roles(self, guild_id: str, role_ids: List[str]) -> List[int]:
        """
        Get all user IDs that have at least one of the specified roles from current_role_members table.
        """
        if not role_ids:
            return []

        try:
            role_ids_int = [int(rid) for rid in role_ids]

            async with db_stats.pool.acquire() as conn:
                placeholders = ','.join(
                    [f'${i+2}' for i in range(len(role_ids_int))])
                query = f"""
                    SELECT DISTINCT user_id
                    FROM current_role_members
                    WHERE guild_id = $1
                    AND role_id IN ({placeholders})
                """
                rows = await conn.fetch(query, int(guild_id), *role_ids_int)
                return [row['user_id'] for row in rows]
        except Exception as e:
            logger.error(f"Error fetching users with roles from table: {e}")
            return []

