    async def _get_cached_leaderboard(self, cache_key: str) -> Optional[list]:
        """Get cached leaderboard if available and not expired."""
        if not self.redis or not self.redis_connected:
            return None

        try:
            cached = await self.redis.get(cache_key)
            if cached:
                data = json.loads(cached)
                # Check if cache is still valid (30 min)
                if time.time() - data['timestamp'] < 1800:  # 30 minutes

                    return data['data']
        except Exception as e:
            logger.warning(f"Cache read failed for {cache_key}: {e}")

        return None

    async def _set_cached_leaderboard(self, cache_key: str, data: list):
        """Cache leaderboard data for 30 minutes."""
        if not self.redis or not self.redis_connected:
            return

        try:
            cache_data = {
                'timestamp': datetime.now().timestamp(),
                'data': data
            }
            # Use custom encoder for Decimal and time values
            await self.redis.setex(cache_key, 1800, json.dumps(cache_data, cls=DecimalEncoder))
        except Exception as e:
            logger.warning(f"Cache write failed for {cache_key}: {e}")

    async def _invalidate_leaderboard_cache(self, guild_id: str, cache_type: str):
        """Invalidate cache when data changes (messages sent, roles changed, etc.)"""
        if not self.redis or not self.redis_connected:
            return

        try:
            # Pattern match to delete all related caches
            pattern = f"leaderboard:{cache_type}:{guild_id}:*"
            keys = await self.redis.keys(pattern)
            if keys:
                await self.redis.delete(*keys)

        except Exception as e:
            logger.warning(f"Cache invalidation failed: {e}")

