    async def record_recent_server(self, discord_id: str, guild_id: str) -> bool:
        """Upsert a server as recently selected, pruning to the 3 most recent per user."""
        if not self.pool:
            return False
        try:
            async with self.pool.acquire() as conn:
                await conn.execute("""
                    INSERT INTO user_recent_servers (discord_id, guild_id, last_selected_at)
                    VALUES ($1, $2, NOW())
                    ON CONFLICT (discord_id, guild_id) DO UPDATE SET
                        last_selected_at = NOW()
                """, discord_id, int(guild_id))
                await conn.execute("""
                    DELETE FROM user_recent_servers
                    WHERE discord_id = $1
                    AND guild_id NOT IN (
                        SELECT guild_id FROM user_recent_servers
                        WHERE discord_id = $1
                        ORDER BY last_selected_at DESC
                        LIMIT 3
                    )
                """, discord_id)
            return True
        except asyncpg.exceptions.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to record recent server",
                context={'discord_id': discord_id, 'guild_id': guild_id},
                original=e
            )

    async def get_recent_servers(self, discord_id: str, limit: int = 3) -> List[Dict]:
        """Get user's most recently selected servers, joined with user_servers for display info."""
        if not self.pool:
            return []
        try:
            async with self.pool.acquire() as conn:
                rows = await conn.fetch("""
                    SELECT urs.guild_id::text AS guild_id, urs.last_selected_at,
                        us.guild_name, us.guild_icon, us.member_count, us.permissions
                    FROM user_recent_servers urs
                    LEFT JOIN user_servers us
                        ON us.discord_id = urs.discord_id AND us.guild_id = urs.guild_id::text
                    WHERE urs.discord_id = $1
                    ORDER BY urs.last_selected_at DESC
                    LIMIT $2
                """, discord_id, limit)
                return [dict(row) for row in rows]
        except asyncpg.exceptions.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to fetch recent servers",
                context={'discord_id': discord_id},
                original=e
            )

    # ============================================
    # ROLE FILTERING HELPER METHODS
    # ============================================

    async def _apply_role_filter_to_query(self, query: str, params: List, guild_id: str,
                                          role_filter_ids: Optional[List[str]],
                                          user_id_column: str = 'user_id') -> tuple:
        """
        Apply role filtering to a query by restricting to users with specified roles.
        Returns modified query and params.
        """
        if not role_filter_ids:
            return query, params

        user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)

        if not user_ids:
            # No users have these roles, return empty result
            # Add impossible condition
            if 'WHERE' in query.upper():
                query += " AND 1=0"
            else:
                query += " WHERE 1=0"
            return query, params

        # Add user_id filter
        placeholders = []
        for i in range(len(user_ids)):
            placeholders.append(f"${len(params) + i + 1}")

        role_condition = f"{user_id_column} IN ({', '.join(placeholders)})"

        if 'WHERE' in query.upper():
            query += f" AND {role_condition}"
        else:
            query += f" WHERE {role_condition}"

        params.extend(user_ids)
        return query, params

    async def _filter_results_by_role(self, guild_id: str, results: List[Dict],
                                      role_filter_ids: Optional[List[str]],
                                      user_id_field: str = 'user_id') -> List[Dict]:
        """
        Filter a list of results to only include users with specified roles.
        """
        if not role_filter_ids or not results:
            return results

        user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)

        if not user_ids:
            return []

        user_id_set = set(user_ids)

        filtered_results = []
        for item in results:
            user_id = item.get(user_id_field)
            if user_id and int(user_id) in user_id_set:
                filtered_results.append(item)

        return filtered_results

    # ============================================
    # FILTER FUNCTIONS
    # ============================================

    async def _apply_bot_filter(self, query: str, params: List, guild_id: str, table_name: str = None) -> tuple:
        """Apply bot filter to query based on guild settings."""
        if not table_name:
            return query, params

        try:
            settings = await self.get_guild_settings(guild_id)
            bot_filter = settings.get('bot_filter', False)

            if not bot_filter:
                return query, params

            tables_with_bot_column = [
                'message_tracking_hourly', 'voice_session_history_hourly', 'emoji_usage_hourly',
                'user_mentions_hourly', 'slash_commands_daily', 'invite_tracking',
                'role_growth_hourly', 'member_joins_hourly', 'member_leaves_hourly',
                'activity_sessions_hourly'
            ]

            if table_name in tables_with_bot_column:
                # IMPORTANT: Use a parameter placeholder, not hardcoded FALSE
                condition = "is_bot = FALSE"

                query_upper = query.upper()
                insert_position = len(query)

                where_pos = query_upper.find("WHERE")
                if where_pos != -1:
                    insert_position = where_pos + 5
                    query = query[:insert_position] + " " + \
                        condition + " AND" + query[insert_position:]
                else:
                    group_by_pos = query_upper.find("GROUP BY")
                    if group_by_pos != -1:
                        insert_position = group_by_pos
                    else:
                        order_by_pos = query_upper.find("ORDER BY")
                        if order_by_pos != -1:
                            insert_position = order_by_pos

                    query = query[:insert_position].rstrip(
                    ) + " WHERE " + condition + " " + query[insert_position:].lstrip()

        except Exception as e:
            logger.warning(
                f"Error applying bot filter for guild {guild_id}: {e}")

        return query, params

    async def _apply_voice_state_filter(self, query: str, params: List, guild_id: str, state_flags_column: str = 'state_flags') -> tuple:
        """Apply voice state filter to query using BITWISE AND."""
        try:
            settings = await self.get_guild_settings(guild_id)
            voice_states = settings.get('voice_states', [])

            if not voice_states:
                return query, params

            state_bits = {
                'afk': self.voice_state_bits['afk_channel'],
                'self_mute': self.voice_state_bits['self_mute'],
                'self_deafen': self.voice_state_bits['self_deaf'],
                'server_mute': self.voice_state_bits['server_mute'],
                'server_deafen': self.voice_state_bits['server_deaf'],
                'streaming': self.voice_state_bits['streaming'],
                'video': self.voice_state_bits['video'],
                'suppressed': self.voice_state_bits['suppressed']
            }

            allowed_mask = 0
            for state in voice_states:
                if state in state_bits:
                    allowed_mask |= state_bits[state]

            if allowed_mask == 0:
                return query, params

            # CORRECT BITWISE LOGIC
            condition = f"({state_flags_column} = 0 OR ({state_flags_column} & ${len(params) + 1}) != 0)"

            query_upper = query.upper()
            insert_position = len(query)

            group_by_pos = query_upper.find("GROUP BY")
            if group_by_pos != -1 and group_by_pos < insert_position:
                insert_position = group_by_pos

            order_by_pos = query_upper.find("ORDER BY")
            if order_by_pos != -1 and order_by_pos < insert_position:
                insert_position = order_by_pos

            if 'WHERE' in query_upper[:insert_position]:
                insert_string = f" AND {condition}"
            else:
                insert_string = f" WHERE {condition}"

            query = query[:insert_position].rstrip(
            ) + insert_string + " " + query[insert_position:].lstrip()
            params.append(allowed_mask)

            return query, params

        except Exception as e:
            logger.error(f"ERROR in _apply_voice_state_filter: {e}")
            return query, params

    async def _get_cached_blacklists(self, guild_id: int) -> Dict[str, set]:
        """Get blacklists for a guild (cached) - ALWAYS returns dict with sets, never None."""
        # Start with empty sets
        blacklists = {
            'users': set(),
            'channels': set(),
            'categories': set(),
            'roles': set()
        }

        # If no database connection, return empty sets
        if not self.pool or not self.db_connected:
            return blacklists

        # Check cache - but validate the cached data format
        cache_key = str(guild_id)
        if cache_key in self.blacklist_cache:
            cache_time, data = self.blacklist_cache[cache_key]
            if (datetime.now() - cache_time).total_seconds() < self.cache_ttl:
                # CRITICAL: Validate and convert cached data to sets if needed
                if isinstance(data, dict):
                    # Ensure all values are sets
                    for key in ['users', 'channels', 'categories', 'roles']:
                        if key in data:
                            if not isinstance(data[key], set):
                                data[key] = set(
                                    data[key]) if data[key] else set()
                        else:
                            data[key] = set()
                return data

        try:
            conn = await self.get_connection()
            try:
                # Get users - store as integers for faster comparison
                users = await conn.fetch(
                    "SELECT user_id FROM blacklisted_users WHERE guild_id = $1",
                    guild_id
                )
                blacklists['users'] = {user['user_id'] for user in users}

                # Get channels
                channels = await conn.fetch(
                    "SELECT channel_id FROM blacklisted_channels WHERE guild_id = $1",
                    guild_id
                )
                blacklists['channels'] = {
                    channel['channel_id'] for channel in channels}

                # Get categories
                categories = await conn.fetch(
                    "SELECT category_id FROM blacklisted_categories WHERE guild_id = $1",
                    guild_id
                )
                blacklists['categories'] = {
                    category['category_id'] for category in categories}

                # Get roles
                roles = await conn.fetch(
                    "SELECT role_id FROM blacklisted_roles WHERE guild_id = $1",
                    guild_id
                )
                blacklists['roles'] = {role['role_id'] for role in roles}

            finally:
                await self.release_connection(conn)
        except Exception as e:
            logger.error(f"Error getting blacklists for guild {guild_id}: {e}")
            # Return empty sets on error
            return blacklists

        # Cache the result - store as sets
        self.blacklist_cache[str(guild_id)] = (datetime.now(), blacklists)
        return blacklists

    async def _apply_comprehensive_blacklist_filters(self, guild_id: str, query: str, params: list,
                                                     table_name: str, include_users: bool = True,
                                                     include_channels: bool = True,
                                                     specific_channel_id: Optional[str] = None,
                                                     specific_category_id: Optional[str] = None) -> tuple:
        """Apply comprehensive blacklist filters to query."""
        try:
            guild_id_int = int(guild_id)
            blacklists = await self._get_cached_blacklists(guild_id_int)

            # Safety check - if blacklists is somehow None, return original query
            if not blacklists:
                return query, params

            new_params = list(params)  # Create a copy
            conditions = []

            # 1. APPLY USER BLACKLIST
            if include_users and blacklists.get('users'):
                user_ids = list(blacklists['users'])  # Convert set to list
                if user_ids:
                    # Create placeholders for NOT IN clause
                    placeholders = [
                        f"${len(new_params) + i + 1}" for i in range(len(user_ids))]
                    conditions.append(
                        f"user_id NOT IN ({', '.join(placeholders)})")
                    new_params.extend(user_ids)

            # 2. APPLY CHANNEL BLACKLIST
            if include_channels and blacklists.get('channels') and table_name != 'invite_tracking':
                channel_ids = list(blacklists['channels'])
                if channel_ids:
                    placeholders = [
                        f"${len(new_params) + i + 1}" for i in range(len(channel_ids))]
                    conditions.append(
                        f"channel_id NOT IN ({', '.join(placeholders)})")
                    new_params.extend(channel_ids)

            # 3. APPLY CATEGORY BLACKLIST
            if include_channels and blacklists.get('categories') and table_name != 'invite_tracking':
                category_ids = list(blacklists['categories'])
                if category_ids:
                    placeholders = [
                        f"${len(new_params) + i + 1}" for i in range(len(category_ids))]
                    conditions.append(
                        f"category_id NOT IN ({', '.join(placeholders)})")
                    new_params.extend(category_ids)

            # 4. APPLY SPECIFIC CHANNEL FILTER
            if specific_channel_id:
                conditions.append(f"channel_id = ${len(new_params) + 1}")
                new_params.append(int(specific_channel_id))

            # 5. APPLY SPECIFIC CATEGORY FILTER
            if specific_category_id:
                conditions.append(f"category_id = ${len(new_params) + 1}")
                new_params.append(int(specific_category_id))

            # 6. MODIFY THE QUERY WITH CONDITIONS
            if conditions:
                where_clause = " AND ".join(conditions)
                query_upper = query.upper()

                # Check if there's already a WHERE clause
                if 'WHERE' in query_upper and 'GROUP BY' not in query_upper[:query_upper.find('WHERE')]:
                    # Add to existing WHERE
                    where_pos = query_upper.find('WHERE')
                    # Find the position to insert (after WHERE)
                    insert_pos = where_pos + 5
                    # Insert the new conditions
                    query = query[:insert_pos] + " " + \
                        where_clause + " AND" + query[insert_pos:]
                else:
                    # No WHERE clause, add one before GROUP BY/ORDER BY/LIMIT
                    insert_pos = len(query)
                    for keyword in ['GROUP BY', 'ORDER BY', 'LIMIT']:
                        pos = query_upper.find(keyword)
                        if pos != -1 and pos < insert_pos:
                            insert_pos = pos
                    query = query[:insert_pos] + " WHERE " + \
                        where_clause + " " + query[insert_pos:]

            return query, new_params

        except Exception as e:
            logger.error(
                f"Error in _apply_comprehensive_blacklist_filters: {e}")
            # On error, return original query to avoid breaking everything
            return query, params

    async def _get_voice_state_filter_value(self, guild_id: str) -> Optional[int]:
        """
        Get voice state filter value as bitmask.
        Returns the mask of allowed voice states, or None if no filter.

        The mask is used in bitwise operations like: (state_flags & mask) != 0
        This returns True if the session has ANY of the allowed states.
        """
        try:
            settings = await self.get_guild_settings(guild_id)
            voice_states = settings.get('voice_states', [])

            if not voice_states:
                return None

            state_bits = {
                'afk': self.voice_state_bits['afk_channel'],
                'self_mute': self.voice_state_bits['self_mute'],
                'self_deafen': self.voice_state_bits['self_deaf'],
                'server_mute': self.voice_state_bits['server_mute'],
                'server_deafen': self.voice_state_bits['server_deaf'],
                'streaming': self.voice_state_bits['streaming'],
                'video': self.voice_state_bits['video'],
                'suppressed': self.voice_state_bits['suppressed']
            }

            allowed_mask = 0
            for state in voice_states:
                if state in state_bits:
                    allowed_mask |= state_bits[state]
                else:
                    logger.warning(f"Unknown voice state: {state}")

            # Return None if no valid states were found
            return allowed_mask if allowed_mask > 0 else None

        except Exception as e:
            logger.error(
                f"Error getting voice state filter for guild {guild_id}: {e}")
            return None

    # ============================================
    # VOICE SESSION HELPER FUNCTIONS
    # ============================================

    async def _get_voice_session_cte(self, base_where: str = "1=1", params: List = None) -> tuple:
        """
        Returns CTE SQL for identifying continuous voice sessions from hourly aggregated table.
        """
        cte = f'''
        WITH hourly_sessions AS (
            SELECT
                vshh.*,
                LAG(vshh.hour) OVER (
                    PARTITION BY vshh.guild_id, vshh.user_id
                    ORDER BY vshh.hour
                ) as prev_hour
            FROM voice_session_history_hourly vshh
            WHERE {base_where}
        ),
        session_groups AS (
            SELECT
                *,
                CASE
                    WHEN prev_hour IS NULL
                        OR EXTRACT(EPOCH FROM (hour - prev_hour)) > 7200  -- 2 hour gap threshold
                    THEN 1  -- New session
                    ELSE 0  -- Continuation of same session
                END as is_new_session
            FROM hourly_sessions
        ),
        session_ids AS (
            SELECT
                *,
                SUM(is_new_session) OVER (
                    PARTITION BY guild_id, user_id
                    ORDER BY hour
                ) as session_number
            FROM session_groups
        ),
        continuous_sessions AS (
            SELECT
                guild_id,
                user_id,
                channel_id,
                category_id,
                session_number,
                MIN(hour) as session_start,
                MAX(hour) + interval '1 hour' as session_end,  -- Approximate end
                SUM(total_seconds) as session_duration,
                SUM(session_count) as chunk_count
            FROM session_ids
            GROUP BY guild_id, user_id, channel_id, category_id, session_number
        )
        '''
        return cte, params

    async def _build_voice_session_query(self, guild_id: str, filters: Dict = None,
                                         group_by_user: bool = False,
                                         group_by_channel: bool = False,
                                         group_by_category: bool = False,
                                         limit: Optional[int] = None,
                                         include_min_max: bool = False,
                                         after_value: Optional[int] = None,
                                         after_id: Optional[int] = None) -> tuple:
        """
        Builds a complete query for voice sessions with proper session identification
        and keyset pagination support, using hourly aggregated table.
        """
        filters = filters or {}

        where_clauses = ["guild_id = $1"]
        params = [int(guild_id)]

        param_index = 2

        filter_mapping = [
            ('user_id', 'user_id'),
            ('channel_id', 'channel_id'),
            ('category_id', 'category_id'),
            ('state_flags', 'state_flags'),
            ('start_time', 'hour >=', True),
            ('end_time', 'hour <=', True)
        ]

        for filter_key, sql_key, *extra in filter_mapping:
            if filter_key in filters and filters[filter_key] is not None:
                if extra and extra[0]:
                    where_clauses.append(f"{sql_key} ${param_index}")
                else:
                    where_clauses.append(f"{sql_key} = ${param_index}")
                params.append(filters[filter_key])
                param_index += 1

        # Add user_ids filter if provided (for role filtering)
        if 'user_ids' in filters and filters['user_ids']:
            placeholders = [
                f"${param_index + i}" for i in range(len(filters['user_ids']))]
            where_clauses.append(f"user_id IN ({', '.join(placeholders)})")
            params.extend(filters['user_ids'])
            param_index += len(filters['user_ids'])

        base_where = " AND ".join(where_clauses)

        cte, _ = await self._get_voice_session_cte(base_where, params)

        select_clauses = [
            "SUM(session_duration) as total_seconds",
            "COUNT(*) as session_count",
            "AVG(session_duration) as avg_session_duration"
        ]

        if include_min_max:
            select_clauses.append("MIN(session_start) as first_session")
            select_clauses.append("MAX(session_end) as last_session")

        group_by_clauses = []
        if group_by_user:
            select_clauses.insert(0, "user_id")
            group_by_clauses.append("user_id")

        if group_by_channel:
            select_clauses.insert(0, "channel_id")
            group_by_clauses.append("channel_id")

        if group_by_category:
            select_clauses.insert(0, "category_id")
            group_by_clauses.append("category_id")

        query = cte + '''
        SELECT
            ''' + ', '.join(select_clauses) + '''
        FROM continuous_sessions
        WHERE 1=1
        '''

        # Add keyset pagination if provided
        if after_value is not None and group_by_user:
            params.append(after_value)
            if after_id:
                params.append(after_id)
                query += f" AND (total_seconds < ${param_index} OR (total_seconds = ${param_index} AND user_id < ${param_index+1}))"
                param_index += 2
            else:
                query += f" AND total_seconds < ${param_index}"
                param_index += 1

        if group_by_clauses:
            query += " GROUP BY " + ", ".join(group_by_clauses)

        query += " HAVING SUM(session_duration) > 0"

        if group_by_user or group_by_channel or group_by_category:
            query += " ORDER BY total_seconds DESC, user_id DESC"

        if limit:
            query += f" LIMIT {limit}"

        return query, params

    # ============================================
    # BLACKLIST FUNCTIONS
    # ============================================

    async def add_to_blacklist(self, guild_id, type_val, entity_id, added_by=0) -> str:
        """Add entity to blacklist - handles both string and int inputs"""
        try:
            # Convert to integers if they're strings
            if isinstance(guild_id, str):
                guild_id = int(guild_id)
            if isinstance(entity_id, str):
                entity_id = int(entity_id)
            if isinstance(added_by, str):
                added_by = int(added_by) if added_by and added_by != "0" else 0

            async with self.pool.acquire() as conn:
                table_name = f"blacklisted_{type_val}s" if type_val != 'category' else "blacklisted_categories"

                column_mapping = {
                    'user': 'user_id',
                    'channel': 'channel_id',
                    'category': 'category_id',
                    'role': 'role_id'
                }
                column_name = column_mapping[type_val]

                # Check if entry exists
                exists = await conn.fetchval(
                    f"SELECT 1 FROM {table_name} WHERE guild_id = $1 AND {column_name} = $2",
                    guild_id, entity_id
                )

                if exists:
                    return "already_exists"

                # Insert with added_by and added_at
                await conn.execute(
                    f"INSERT INTO {table_name} (guild_id, {column_name}, added_by, added_at) VALUES ($1, $2, $3, NOW())",
                    guild_id, entity_id, added_by
                )

                # Invalidate cache
                cache_key = str(guild_id)
                if cache_key in self.blacklist_cache:
                    del self.blacklist_cache[cache_key]

                return "added"

        except asyncpg.PostgresError as e:
            logger.error(f"Database error in add_to_blacklist: {e}")
            raise DatabaseQueryError(
                "Failed to add to blacklist",
                context={'guild_id': guild_id,
                         'type': type_val, 'entity_id': entity_id},
                original=e
            )
        except ValueError as e:
            logger.error(f"Value error in add_to_blacklist: {e}")
            return "error"

    async def remove_from_blacklist(self, guild_id, type_val, entity_id) -> str:
        """Remove entity from blacklist - handles both string and int inputs"""
        try:
            # Convert to integers if they're strings
            if isinstance(guild_id, str):
                guild_id = int(guild_id)
            if isinstance(entity_id, str):
                entity_id = int(entity_id)

            async with self.pool.acquire() as conn:
                table_name = f"blacklisted_{type_val}s" if type_val != 'category' else "blacklisted_categories"

                if type_val == 'user':
                    column_name = 'user_id'
                elif type_val == 'channel':
                    column_name = 'channel_id'
                elif type_val == 'category':
                    column_name = 'category_id'
                elif type_val == 'role':
                    column_name = 'role_id'
                else:
                    return "error"

                result = await conn.execute(
                    f"DELETE FROM {table_name} WHERE guild_id = $1 AND {column_name} = $2",
                    guild_id, entity_id
                )

                # Invalidate cache
                cache_key = str(guild_id)
                if cache_key in self.blacklist_cache:
                    del self.blacklist_cache[cache_key]

                if "DELETE 1" in result:
                    return "removed"
                else:
                    return "not_found"

        except asyncpg.PostgresError as e:
            logger.error(f"Database error in remove_from_blacklist: {e}")
            raise DatabaseQueryError(
                "Failed to remove from blacklist",
                context={'guild_id': guild_id,
                         'type': type_val, 'entity_id': entity_id},
                original=e
            )
        except ValueError as e:
            logger.error(f"Value error in remove_from_blacklist: {e}")
            return "error"

    async def is_blacklisted(self, guild_id: str, type_val: str, entity_id: str) -> bool:
        """Check if entity is blacklisted"""
        try:
            conn = await self.get_connection()
            try:
                table_name = f"blacklisted_{type_val}s" if type_val != 'category' else "blacklisted_categories"

                column_mapping = {
                    'user': 'user_id',
                    'channel': 'channel_id',
                    'category': 'category_id',
                    'role': 'role_id'
                }
                column_name = column_mapping[type_val]

                exists = await conn.fetchval(
                    f"SELECT 1 FROM {table_name} WHERE guild_id = $1 AND {column_name} = $2",
                    guild_id, int(entity_id)
                )
                return exists is not None
            finally:
                await self.release_connection(conn)
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to check blacklist",
                context={'guild_id': guild_id,
                         'type': type_val, 'entity_id': entity_id},
                original=e
            )

    async def get_blacklist(self, guild_id: str, entity_type: Optional[str] = None) -> list:
        """Get blacklist for guild, optionally filtered by type"""
        try:
            conn = await self.get_connection()
            try:
                all_items = []

                if not entity_type or entity_type == 'user':
                    users = await conn.fetch(
                        "SELECT user_id as entity_id, added_by, added_at FROM blacklisted_users WHERE guild_id = $1",
                        guild_id
                    )
                    for user in users:
                        all_items.append({
                            'type': 'user',
                            'entity_id': str(user['entity_id']),
                            'added_by': str(user['added_by']),
                            'added_at': user['added_at']
                        })

                if not entity_type or entity_type == 'channel':
                    channels = await conn.fetch(
                        "SELECT channel_id as entity_id, added_by, added_at FROM blacklisted_channels WHERE guild_id = $1",
                        guild_id
                    )
                    for channel in channels:
                        all_items.append({
                            'type': 'channel',
                            'entity_id': str(channel['entity_id']),
                            'added_by': str(channel['added_by']),
                            'added_at': channel['added_at']
                        })

                if not entity_type or entity_type == 'category':
                    categories = await conn.fetch(
                        "SELECT category_id as entity_id, added_by, added_at FROM blacklisted_categories WHERE guild_id = $1",
                        guild_id
                    )
                    for category in categories:
                        all_items.append({
                            'type': 'category',
                            'entity_id': str(category['entity_id']),
                            'added_by': str(category['added_by']),
                            'added_at': category['added_at']
                        })

                if not entity_type or entity_type == 'role':
                    roles = await conn.fetch(
                        "SELECT role_id as entity_id, added_by, added_at FROM blacklisted_roles WHERE guild_id = $1",
                        guild_id
                    )
                    for role in roles:
                        all_items.append({
                            'type': 'role',
                            'entity_id': str(role['entity_id']),
                            'added_by': str(role['added_by']),
                            'added_at': role['added_at']
                        })

                all_items.sort(key=lambda x: x['added_at'], reverse=True)
                return all_items
            finally:
                await self.release_connection(conn)
        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to get blacklist",
                context={'guild_id': guild_id, 'entity_type': entity_type},
                original=e
            )

    # ============================================
    # RESET FUNCTIONS
