    async def get_decrypted_username_from_messages(self, guild_id: int, user_id: int) -> Optional[str]:
        """Get decrypted username from message_tracking_hourly table."""
        if not self.pool:
            return None

        try:
            async with self.pool.acquire() as conn:
                # Convert to int if they're strings
                guild_id_int = int(guild_id) if not isinstance(
                    guild_id, int) else guild_id
                user_id_int = int(user_id) if not isinstance(
                    user_id, int) else user_id

                row = await conn.fetchrow("""
                    SELECT encrypted_username
                    FROM message_tracking_hourly
                    WHERE guild_id = $1 AND user_id = $2
                    AND encrypted_username IS NOT NULL
                    AND encrypted_username != ''
                    ORDER BY hour DESC
                    LIMIT 1
                """, guild_id_int, user_id_int)

                if row and row['encrypted_username']:
                    decrypted = self.decrypt_username(
                        row['encrypted_username'])
                    if decrypted:
                        return decrypted
                return None
        except Exception as e:
            print(f"Error getting username from messages for {user_id}: {e}")
            return None

