    async def get_decrypted_username_any_table(self, guild_id: int, user_id: int, priority_tables: List[str] = None) -> Optional[str]:
        """
        Get decrypted username from any table that has it, in priority order.
        For mentions, we prioritize the mentions table since we're in the mentions dashboard.
        """
        # Convert IDs to int at the start
        guild_id_int = int(guild_id) if not isinstance(
            guild_id, int) else guild_id
        user_id_int = int(user_id) if not isinstance(user_id, int) else user_id

        if priority_tables is None:
            # Prioritize mentions table first for the mentions dashboard
            priority_tables = [
                'mentions',   # First try mentions table
                'messages',
                'voice',
                'emojis',
                'invites',
                'activity',
                'member_joins',
                'member_leaves',
                'role_growth'
            ]

        print(
            f"DEBUG: Looking for username for user {user_id_int} in guild {guild_id_int}")

        for table in priority_tables:
            username = None
            if table == 'messages':
                username = await self.get_decrypted_username_from_messages(guild_id_int, user_id_int)
            elif table == 'voice':
                username = await self.get_decrypted_username_from_voice(guild_id_int, user_id_int)
            elif table == 'emojis':
                username = await self.get_decrypted_username_from_emojis(guild_id_int, user_id_int)
            elif table == 'mentions':
                username = await self.get_decrypted_username_from_mentions(guild_id_int, user_id_int)
            elif table == 'invites':
                username = await self.get_decrypted_username_from_invites(guild_id_int, user_id_int)
            elif table == 'activity':
                username = await self.get_decrypted_username_from_activity(guild_id_int, user_id_int)
            elif table == 'member_joins':
                username = await self.get_decrypted_username_from_member_joins(guild_id_int, user_id_int)
            elif table == 'member_leaves':
                username = await self.get_decrypted_username_from_member_leaves(guild_id_int, user_id_int)
            elif table == 'role_growth':
                username = await self.get_decrypted_username_from_role_growth(guild_id_int, user_id_int)

            if username:
                print(f"DEBUG: Found username in {table} table: {username}")
                return username

        print(f"DEBUG: No username found for user {user_id_int} in any table")
        return None

    async def batch_get_decrypted_usernames_from_messages(self, guild_id: int, user_ids: List[int]) -> Dict[int, str]:
        if not self.pool or not user_ids:
            return {int(uid): f"User {uid}" for uid in user_ids}

        try:
            async with self.pool.acquire() as conn:
                # 1. Normalize IDs to integers
                guild_id_int = int(guild_id)
                user_ids_int = [int(uid) for uid in user_ids]

                # 2. Fix SQL: ORDER BY must start with the DISTINCT ON column
                query = """
                    SELECT DISTINCT ON (user_id) user_id, encrypted_username
                    FROM message_tracking_hourly
                    WHERE guild_id = $1 
                    AND user_id = ANY($2::bigint[])
                    AND encrypted_username IS NOT NULL
                    AND encrypted_username != ''
                    ORDER BY user_id, hour DESC
                """

                rows = await conn.fetch(query, guild_id_int, user_ids_int)

                result = {}
                for row in rows:
                    uid = row['user_id']
                    encrypted = row['encrypted_username']
                    decrypted = self.decrypt_username(encrypted)

                    # Only map if decryption actually worked
                    result[uid] = decrypted if decrypted else f"User {uid}"

                # 3. Fill missing users who weren't in the DB results
                for uid in user_ids_int:
                    if uid not in result:
                        result[uid] = f"User {uid}"

                return result

        except Exception as e:
            # Crucial: Log the actual error to see if it's a Fernet or SQL issue
            print(f"BATCH ERROR in messages: {e}")
            return {int(uid): f"User {uid}" for uid in user_ids}

    async def batch_get_decrypted_usernames_any_table(self, guild_id: int, user_ids: List[int], table_name: str = 'messages') -> Dict[int, str]:
        """
        Batch get decrypted usernames from a specific table.

        Args:
            guild_id: The guild ID
            user_ids: List of user IDs
            table_name: Which table to query ('messages', 'voice', 'emojis', 'mentions', 
                    'invites', 'activity', 'member_joins', 'member_leaves', 'role_growth')

        Returns:
            Dictionary mapping user_id to username
        """
        if not self.pool or not user_ids:
            return {uid: f"User {uid}" for uid in user_ids}

        # Define table-specific queries with proper type casting
        queries = {
            'messages': """
                SELECT DISTINCT ON (user_id) user_id, encrypted_username
                FROM message_tracking_hourly
                WHERE guild_id = $1 AND user_id = ANY($2::bigint[])
                AND encrypted_username IS NOT NULL
                ORDER BY user_id, hour DESC
            """,
            'voice': """
                SELECT DISTINCT ON (user_id) user_id, encrypted_username
                FROM voice_session_history_hourly
                WHERE guild_id = $1 AND user_id = ANY($2::bigint[])
                AND encrypted_username IS NOT NULL
                ORDER BY user_id, hour DESC
            """,
            'emojis': """
                SELECT DISTINCT ON (user_id) user_id, encrypted_username
                FROM emoji_usage_hourly
                WHERE guild_id = $1 AND user_id = ANY($2::bigint[])
                AND encrypted_username IS NOT NULL
                ORDER BY user_id, hour DESC
            """,
            'mentions': """
                SELECT DISTINCT ON (mentioner_user_id) mentioner_user_id as user_id, encrypted_username
                FROM user_mentions_hourly
                WHERE guild_id = $1 AND mentioner_user_id = ANY($2::bigint[])
                AND encrypted_username IS NOT NULL
                ORDER BY mentioner_user_id, hour DESC
            """,
            'invites': """
                SELECT DISTINCT ON (inviter_id) inviter_id as user_id, encrypted_username
                FROM invite_tracking
                WHERE guild_id = $1 AND inviter_id = ANY($2::bigint[])
                AND encrypted_username IS NOT NULL
                ORDER BY inviter_id, created_at DESC
            """,
            'activity': """
                SELECT DISTINCT ON (user_id) user_id, encrypted_username
                FROM activity_sessions_hourly
                WHERE guild_id = $1 AND user_id = ANY($2::bigint[])
                AND encrypted_username IS NOT NULL
                ORDER BY user_id, hour DESC
            """,
            'member_joins': """
                SELECT DISTINCT ON (user_id) user_id, encrypted_username
                FROM member_joins_hourly
                WHERE guild_id = $1 AND user_id = ANY($2::bigint[])
                AND encrypted_username IS NOT NULL
                ORDER BY user_id, hour DESC
            """,
            'member_leaves': """
                SELECT DISTINCT ON (user_id) user_id, encrypted_username
                FROM member_leaves_hourly
                WHERE guild_id = $1 AND user_id = ANY($2::bigint[])
                AND encrypted_username IS NOT NULL
                ORDER BY user_id, hour DESC
            """,
            'role_growth': """
                SELECT DISTINCT ON (user_id) user_id, encrypted_username
                FROM role_growth_hourly
                WHERE guild_id = $1 AND user_id = ANY($2::bigint[])
                AND encrypted_username IS NOT NULL
                ORDER BY user_id, hour DESC
            """
        }

        if table_name not in queries:
            return {uid: f"User {uid}" for uid in user_ids}

        try:
            async with self.pool.acquire() as conn:
                # Convert guild_id to int
                guild_id_int = int(guild_id) if not isinstance(
                    guild_id, int) else guild_id

                # Convert all user_ids to integers
                user_ids_int = [int(uid) if not isinstance(
                    uid, int) else uid for uid in user_ids]

                rows = await conn.fetch(queries[table_name], guild_id_int, user_ids_int)

                result = {}
                for row in rows:
                    user_id_val = row['user_id']
                    encrypted = row['encrypted_username']
                    if encrypted:
                        decrypted = self.decrypt_username(encrypted)
                        if decrypted:
                            result[user_id_val] = decrypted
                        else:
                            result[user_id_val] = f"User {user_id_val}"
                    else:
                        result[user_id_val] = f"User {user_id_val}"

                # Fill in any missing user_ids
                for user_id_val in user_ids_int:
                    if user_id_val not in result:
                        result[user_id_val] = f"User {user_id_val}"

                return result
        except Exception as e:
            print(f"Error in batch get usernames from {table_name}: {e}")
            return {uid: f"User {uid}" for uid in user_ids}

    async def get_username_from_cache(self, guild_id: str, user_id: int) -> Optional[str]:
        """
        ENDPOINT 1: Get username from local member cache.
        NO rate limiting - this is a local database lookup.
        Returns username if found, None otherwise.
        """
        try:
            # First try to get from current_role_members table (most reliable for active members)
            async with self.pool.acquire() as conn:
                row = await conn.fetchrow("""
                    SELECT encrypted_username
                    FROM current_role_members
                    WHERE guild_id = $1 AND user_id = $2
                    AND encrypted_username IS NOT NULL
                    LIMIT 1
                """, int(guild_id), user_id)

                if row and row['encrypted_username']:
                    decrypted = self.decrypt_username(
                        row['encrypted_username'])
                    if decrypted:
                        return decrypted

            # Fallback to checking message tracking table
            username = await self.get_decrypted_username_from_messages(int(guild_id), user_id)
            if username:
                return username

            # Fallback to voice table
            username = await self.get_decrypted_username_from_voice(int(guild_id), user_id)
            if username:
                return username

            return None

        except Exception as e:
            logger.error(f"Error getting username from cache: {e}")
            return None

    @fastapi_rate_limited(RateLimitType.API, timeout=30.0)
    async def get_username_from_api(self, user_id: int) -> Optional[str]:
        """
        ENDPOINT 2: Get username from Discord API with rate limiting.
        Uses the SAME rate limiting as your existing Discord API calls.
        Will wait 30 seconds between API calls if rate limited.
        """
        try:
            async with aiohttp.ClientSession() as session:
                headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
                url = f"{DISCORD_API_BASE}/users/{user_id}"

                async with session.get(url, headers=headers, timeout=10) as resp:
                    if resp.status == 200:
                        user_data = await resp.json()
                        username = user_data.get(
                            'global_name') or user_data.get('username')
                        if username:
                            # Store in database cache for future use
                            await self._cache_username(user_id, username)
                            return username
                        return None
                    elif resp.status == 404:
                        logger.warning(f"User {user_id} not found on Discord")
                        return None
                    else:
                        logger.warning(
                            f"Failed to fetch user {user_id}: HTTP {resp.status}")
                        return None

        except asyncio.TimeoutError:
            logger.error(f"Timeout fetching user {user_id} from Discord API")
            return None
        except aiohttp.ClientError as e:
            logger.error(f"HTTP error fetching user {user_id}: {e}")
            return None
        except Exception as e:
            logger.error(f"Unexpected error fetching user {user_id}: {e}")
            return None

    async def _cache_username(self, user_id: int, username: str) -> None:
        """Helper method to cache username in current_role_members table"""
        try:
            async with self.pool.acquire() as conn:
                # This is a simplified cache - you may want a dedicated user cache table
                await conn.execute("""
                    INSERT INTO current_role_members (guild_id, user_id, role_id, role_name, encrypted_username, updated_at)
                    VALUES (0, $1, 0, 'cached_user', $2, NOW())
                    ON CONFLICT (guild_id, user_id, role_id) DO UPDATE SET
                        encrypted_username = EXCLUDED.encrypted_username,
                        updated_at = NOW()
                """, user_id, username)
        except Exception as e:
            logger.warning(f"Failed to cache username for {user_id}: {e}")

    async def get_username_smart(self, guild_id: str, user_id: int) -> str:
        """
        Smart endpoint: Try local cache first, fall back to API with rate limiting.
        This is the recommended method for most use cases.
        """
        # First try local cache (fast, no rate limit)
        username = await self.get_username_from_cache(guild_id, user_id)

        if username:
            return username

        # Fall back to API with rate limiting
        username = await self.get_username_from_api(user_id)

        if username:
            return username

        # Ultimate fallback if everything fails
        return f"User {user_id}"

    async def get_usernames_bulk(self, guild_id: str, user_ids: List[int]) -> Dict[int, str]:
        """
        Get multiple usernames efficiently.
        - First gets all from local cache (instant)
        - Then rate-limited API calls for missing ones
        """
        result = {}
        missing_ids = []

        # Step 1: Get all from local cache first
        for user_id in user_ids:
            username = await self.get_username_from_cache(guild_id, user_id)
            if username:
                result[user_id] = username
            else:
                missing_ids.append(user_id)

        # Step 2: Fetch missing ones from API with rate limiting
        for user_id in missing_ids:
            username = await self.get_username_from_api(user_id)
            if username:
                result[user_id] = username
            else:
                result[user_id] = f"User {user_id}"

            # Small delay to be extra safe (rate limiter already handles this)
            await asyncio.sleep(0.1)

        return result

    async def q_user_rank_messages(self, guild_id: str, user_id: str,
                                   role_filter_ids: Optional[List[str]] = None,
                                   start_time: Optional[datetime] = None,
                                   end_time: Optional[datetime] = None) -> Dict[str, Any]:
        """Get user's message rank with role filtering using hourly aggregated table."""
        if not self.pool:
            logger.warning(
                f"Database pool not available for user {user_id} rank query")
            return {'rank': 0, 'total_users': 0, 'message_count': 0}

        try:
            async with self.pool.acquire() as conn:
                query = '''
                    SELECT
                        user_id,
                        SUM(message_count) as message_count,
                        RANK() OVER (ORDER BY SUM(message_count) DESC) as rank
                    FROM message_tracking_hourly
                    WHERE guild_id = $1
                '''
                params = [int(guild_id)]

                query, params = await self._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')

                if start_time:
                    query += " AND hour >= $2"
                    params.append(start_time)
                    if end_time:
                        query += " AND hour <= $3"
                        params.append(end_time)
                elif end_time:
                    query += " AND hour <= $2"
                    params.append(end_time)

                # Apply role filtering if needed
                if role_filter_ids:
                    # First get users with these roles
                    user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                    if user_ids:
                        placeholders = [
                            f"${len(params) + i + 1}" for i in range(len(user_ids))]
                        query += f" AND user_id IN ({', '.join(placeholders)})"
                        params.extend(user_ids)
                    else:
                        # No users have these roles
                        return {'rank': 0, 'total_users': 0, 'message_count': 0}

                query += " GROUP BY user_id ORDER BY message_count DESC"

                try:
                    rows = await conn.fetch(query, *params)
                except asyncpg.PostgresError as e:
                    if "timeout" in str(e).lower():
                        raise DatabaseTimeoutError(
                            "Database operation timed out while fetching user message rank",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e
                    else:
                        raise DatabaseQueryError(
                            "Failed to fetch user message rank",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e

                user_rank = 0
                user_count = 0
                total_users = len(rows)

                for idx, row in enumerate(rows, 1):
                    if str(row['user_id']) == user_id:
                        user_rank = idx
                        user_count = row['message_count']
                        break

                return {
                    'rank': user_rank,
                    'total_users': total_users,
                    'message_count': user_count
                }

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching user message rank",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except DatabaseError:
            raise
        except Exception as e:
            raise DatabaseQueryError(
                "Unexpected error fetching user message rank",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )

    async def q_user_rank_voice(self, guild_id: str, user_id: str,
                                role_filter_ids: Optional[List[str]] = None,
                                start_time: Optional[datetime] = None,
                                end_time: Optional[datetime] = None) -> Dict[str, Any]:
        """Get user's voice rank with role filtering using hourly aggregated table."""
        if not self.pool:
            logger.warning(
                f"Database pool not available for user {user_id} voice rank query")
            return {'rank': 0, 'total_users': 0, 'voice_seconds': 0, 'voice_hours': 0.0}

        try:
            state_flags_filter = await self._get_voice_state_filter_value(guild_id)

            async with self.pool.acquire() as conn:
                base_where = ["guild_id = $1"]
                params = [int(guild_id)]

                if state_flags_filter is not None:
                    base_where.append(f"state_flags = ${len(params) + 1}")
                    params.append(state_flags_filter)

                if start_time:
                    base_where.append(f"hour >= ${len(params) + 1}")
                    params.append(start_time)
                if end_time:
                    base_where.append(f"hour <= ${len(params) + 1}")
                    params.append(end_time)

                # Apply role filtering if needed
                if role_filter_ids:
                    # First get users with these roles
                    user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                    if user_ids:
                        placeholders = [
                            f"${len(params) + i + 1}" for i in range(len(user_ids))]
                        base_where.append(
                            f"user_id IN ({', '.join(placeholders)})")
                        params.extend(user_ids)
                    else:
                        # No users have these roles
                        return {'rank': 0, 'total_users': 0, 'voice_seconds': 0, 'voice_hours': 0.0}

                query = '''
                    SELECT
                        user_id,
                        SUM(total_seconds) as total_seconds,
                        RANK() OVER (ORDER BY SUM(total_seconds) DESC) as rank
                    FROM voice_session_history_hourly
                    WHERE ''' + " AND ".join(base_where) + '''
                    GROUP BY user_id
                    HAVING SUM(total_seconds) > 0
                    ORDER BY total_seconds DESC
                '''

                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'voice_session_history_hourly',
                    include_users=True, include_channels=True
                )

                query, params = await self._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')

                try:
                    rows = await conn.fetch(query, *params)
                except asyncpg.PostgresError as e:
                    if "timeout" in str(e).lower():
                        raise DatabaseTimeoutError(
                            "Database operation timed out while fetching user voice rank",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e
                    else:
                        raise DatabaseQueryError(
                            "Failed to fetch user voice rank",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e

                user_rank = 0
                user_seconds = 0
                total_users = len(rows)

                for idx, row in enumerate(rows, 1):
                    if str(row['user_id']) == user_id:
                        user_rank = idx
                        user_seconds = row['total_seconds']
                        break

                return {
                    'rank': user_rank,
                    'total_users': total_users,
                    'voice_seconds': user_seconds,
                    'voice_hours': round(user_seconds / 3600, 2) if user_seconds > 0 else 0.0
                }

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching user voice rank",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except DatabaseError:
            raise
        except Exception as e:
            raise DatabaseQueryError(
                "Unexpected error fetching user voice rank",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )

    async def q_user_timeseries_messages_1d_5d_10d_20d_30d(self, guild_id: str, user_id: str,
                                                           role_filter_ids: Optional[List[str]] = None,
                                                           start_time: Optional[datetime] = None,
                                                           end_time: Optional[datetime] = None) -> Dict[str, Any]:
        """Get user message counts for different time periods with role filtering using hourly aggregated table."""
        if not self.pool:
            logger.warning(
                f"Database pool not available for user {user_id} message timeseries")
            return {'1d': 0, '5d': 0, '10d': 0, '20d': 0, '30d': 0}

        try:
            async with self.pool.acquire() as conn:
                periods = [1, 5, 10, 20, 30]
                result = {}

                # Get the absolute time bounds if provided
                absolute_end = end_time if end_time else datetime.utcnow()
                absolute_start = start_time if start_time else (
                    absolute_end - timedelta(days=30))

                # If role filtering is needed, verify user has the role
                if role_filter_ids:
                    user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                    if not user_ids or int(user_id) not in user_ids:
                        # User doesn't have the required role
                        return {f'{days}d': 0 for days in periods}

                for days in periods:
                    # Calculate window relative to the absolute end time
                    window_end = absolute_end
                    window_start = absolute_end - timedelta(days=days)

                    # Ensure we don't go before the absolute start
                    if window_start < absolute_start:
                        window_start = absolute_start

                    # Skip if window is invalid (start after end)
                    if window_start >= window_end:
                        result[f'{days}d'] = 0
                        continue

                    query = '''
                        SELECT COALESCE(SUM(message_count), 0) as message_count
                        FROM message_tracking_hourly
                        WHERE guild_id = $1
                        AND user_id = $2
                        AND hour >= $3
                        AND hour <= $4
                    '''
                    params = [int(guild_id), int(user_id),
                              window_start, window_end]

                    query, params = await self._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')

                    query, params = await self._apply_comprehensive_blacklist_filters(
                        guild_id, query, params, 'message_tracking_hourly',
                        include_users=True, include_channels=True
                    )

                    try:
                        row = await conn.fetchrow(query, *params)
                    except asyncpg.PostgresError as e:
                        if "timeout" in str(e).lower():
                            raise DatabaseTimeoutError(
                                "Database operation timed out while fetching user message timeseries",
                                context={'guild_id': guild_id,
                                         'user_id': user_id, 'days': days},
                                original=e
                            ) from e
                        else:
                            raise DatabaseQueryError(
                                "Failed to fetch user message timeseries",
                                context={'guild_id': guild_id,
                                         'user_id': user_id, 'days': days},
                                original=e
                            ) from e

                    result[f'{days}d'] = row['message_count'] or 0

                return result

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching user message timeseries",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except DatabaseError:
            raise
        except Exception as e:
            raise DatabaseQueryError(
                "Unexpected error fetching user message timeseries",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )

