    async def q_user_timeseries_voice_daily(self, guild_id: str, user_id: str,
                                            role_filter_ids: Optional[List[str]] = None,
                                            start_time: Optional[datetime] = None,
                                            end_time: Optional[datetime] = None,
                                            max_points: int = 90) -> List[Dict[str, Any]]:
        """Get user's daily voice timeseries."""
        if not self.pool:
            raise DatabaseConnectionError(
                "Database pool not available",
                context={'guild_id': guild_id, 'user_id': user_id}
            )

        try:
            guild_id_int = int(guild_id)
            user_id_int = int(user_id)

            if role_filter_ids:
                user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                if not user_ids or user_id_int not in user_ids:
                    return []

            if not end_time:
                end_time = datetime.utcnow()
            if not start_time:
                start_time = end_time - timedelta(days=max_points)

            days_in_range = (end_time - start_time).days
            if days_in_range > max_points:
                start_time = end_time - timedelta(days=max_points)

            async with self.pool.acquire() as conn:
                query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(total_seconds), 0) as total_seconds
                    FROM voice_session_history_hourly
                    WHERE guild_id = $1 
                    AND user_id = $2
                    AND hour >= $3 
                    AND hour <= $4
                    GROUP BY DATE(hour)
                    ORDER BY date ASC
                """
                params = [guild_id_int, user_id_int, start_time, end_time]

                query, params = await self._apply_voice_state_filter(query, params, guild_id, 'state_flags')
                query, params = await self._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')

                rows = await conn.fetch(query, *params)

                data_map = {}
                for row in rows:
                    date_str = row['date'].isoformat()
                    data_map[date_str] = row['total_seconds']

                result = []
                current_date = start_time.date()
                end_date_obj = end_time.date()

                while current_date <= end_date_obj:
                    date_str = current_date.isoformat()
                    result.append({
                        "date": date_str,
                        "seconds": data_map.get(date_str, 0)
                    })
                    current_date += timedelta(days=1)

                return result

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching user voice timeseries",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except asyncpg.exceptions.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to fetch user voice timeseries",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except Exception as e:
            raise DatabaseError(
                "Unexpected error fetching user voice timeseries",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )

    async def get_current_member_count(self, guild_id: str) -> int:
        """Get current member count for a guild from the latest snapshot."""
        if not self.pool:
            return 0

        try:
            async with self.pool.acquire() as conn:
                # Get the most recent snapshot from the existing table
                row = await conn.fetchrow("""
                    SELECT member_count
                    FROM server_member_counts
                    WHERE guild_id = $1
                    ORDER BY recorded_at DESC
                    LIMIT 1
                """, int(guild_id))

                if row:
                    return row['member_count']

                # If no snapshots exist yet (brand new guild), fallback to Discord API
                return await self._get_current_member_count_from_discord(guild_id)

        except Exception as e:
            logger.error(
                f"Error getting current member count for {guild_id}: {e}")
            return 0

    @fastapi_rate_limited(RateLimitType.API, timeout=30.0)
    async def _get_current_member_count_from_discord(self, guild_id: str) -> int:
        """Get current member count from Discord API as fallback (only for new guilds with no snapshots)."""
        try:
            async with aiohttp.ClientSession() as session:
                headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
                url = f"{DISCORD_API_BASE}/guilds/{guild_id}?with_counts=true"

                async with session.get(url, headers=headers, timeout=5) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        return data.get('approximate_member_count', 0)
                    return 0
        except asyncio.TimeoutError:
            logger.error(
                f"Timeout fetching member count for guild {guild_id} from Discord")
            return 0
        except Exception as e:
            logger.error(f"Error fetching member count from Discord: {e}")
            return 0

    async def get_server_member_timeseries(self, guild_id: str,
                                           days: Optional[int] = None,
                                           start_time: Optional[datetime] = None,
                                           end_time: Optional[datetime] = None) -> List[Dict[str, Any]]:
        """Get member count timeseries for a server."""
        if not self.pool:
            return []

        try:
            async with self.pool.acquire() as conn:
                query = """
                    SELECT 
                        recorded_at as date,
                        member_count as count
                    FROM server_member_counts
                    WHERE guild_id = $1
                """
                params = [int(guild_id)]
                param_index = 2

                # Handle time filters correctly
                if start_time and end_time:
                    query += f" AND recorded_at >= ${param_index} AND recorded_at <= ${param_index + 1}"
                    params.append(start_time)
                    params.append(end_time)
                elif start_time:
                    query += f" AND recorded_at >= ${param_index}"
                    params.append(start_time)
                elif end_time:
                    query += f" AND recorded_at <= ${param_index}"
                    params.append(end_time)
                elif days is not None and days > 0:
                    # Only add days filter if days is provided and > 0
                    query += f" AND recorded_at >= NOW() - INTERVAL '1 day' * ${param_index}"
                    params.append(days)
                # If days is None, get ALL data (no date filter)

                query += " ORDER BY recorded_at ASC"

                rows = await conn.fetch(query, *params)

                result = []
                for row in rows:
                    result.append({
                        'date': row['date'].isoformat(),
                        'count': row['count']
                    })

                return result

        except Exception as e:
            logger.error(f"Error getting member timeseries: {e}")
            return []

    async def get_server_joins_leaves(self, guild_id: str,
                                      days: Optional[int] = None,
                                      role_filter_ids: Optional[List[str]] = None,
                                      start_time: Optional[datetime] = None,
                                      end_time: Optional[datetime] = None) -> Dict[str, Any]:
        """Get joins and leaves timeseries for a server."""
        if not self.pool:
            return {'joins': [], 'leaves': [], 'total_joins': 0, 'total_leaves': 0, 'net_growth': 0}

        try:
            guild_id_int = int(guild_id)

            # Apply role filtering if needed
            user_ids = None
            if role_filter_ids:
                user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)

            async with self.pool.acquire() as conn:
                # FIX: For "all time", we should NOT use any date filter
                start_filter = None
                end_filter = None

                if start_time and end_time:
                    start_filter = start_time
                    end_filter = end_time
                elif days is not None and days > 0:
                    # Only apply days filter if days is provided and > 0
                    end_filter = datetime.utcnow()
                    start_filter = end_filter - timedelta(days=days)
                # If days is None and no start_time/end_time, get ALL data (leave filters as None)

                # Build joins query
                joins_query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(join_count), 0) as count
                    FROM member_joins_hourly
                    WHERE guild_id = $1
                """
                joins_params = [guild_id_int]
                param_index = 2

                # Add role filtering
                if user_ids:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(user_ids))]
                    joins_query += f" AND user_id IN ({', '.join(placeholders)})"
                    joins_params.extend(user_ids)
                    param_index += len(user_ids)

                # Add time filters ONLY if they exist
                if start_filter and end_filter:
                    joins_query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                    joins_params.append(start_filter)
                    joins_params.append(end_filter)
                elif start_filter:
                    joins_query += f" AND hour >= ${param_index}"
                    joins_params.append(start_filter)
                elif end_filter:
                    joins_query += f" AND hour <= ${param_index}"
                    joins_params.append(end_filter)
                # If no filters, get ALL data

                # Apply bot filter
                joins_query, joins_params = await self._apply_bot_filter(
                    joins_query, joins_params, guild_id, 'member_joins_hourly'
                )

                joins_query += " GROUP BY DATE(hour) ORDER BY date ASC"

                joins_rows = await conn.fetch(joins_query, *joins_params)

                # Build leaves query
                leaves_query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(leave_count), 0) as count
                    FROM member_leaves_hourly
                    WHERE guild_id = $1
                """
                leaves_params = [guild_id_int]
                param_index = 2

                # Add role filtering
                if user_ids:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(user_ids))]
                    leaves_query += f" AND user_id IN ({', '.join(placeholders)})"
                    leaves_params.extend(user_ids)
                    param_index += len(user_ids)

                # Add time filters ONLY if they exist
                if start_filter and end_filter:
                    leaves_query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                    leaves_params.append(start_filter)
                    leaves_params.append(end_filter)
                elif start_filter:
                    leaves_query += f" AND hour >= ${param_index}"
                    leaves_params.append(start_filter)
                elif end_filter:
                    leaves_query += f" AND hour <= ${param_index}"
                    leaves_params.append(end_filter)
                # If no filters, get ALL data

                # Apply bot filter
                leaves_query, leaves_params = await self._apply_bot_filter(
                    leaves_query, leaves_params, guild_id, 'member_leaves_hourly'
                )

                leaves_query += " GROUP BY DATE(hour) ORDER BY date ASC"

                leaves_rows = await conn.fetch(leaves_query, *leaves_params)

                # Convert to dictionaries with proper date formatting
                joins = [{'date': row['date'].isoformat(), 'count': row['count']}
                         for row in joins_rows]
                leaves = [{'date': row['date'].isoformat(), 'count': row['count']}
                          for row in leaves_rows]

                total_joins = sum(j['count'] for j in joins)
                total_leaves = sum(l['count'] for l in leaves)
                net_growth = total_joins - total_leaves

                return {
                    'joins': joins,
                    'leaves': leaves,
                    'total_joins': total_joins,
                    'total_leaves': total_leaves,
                    'net_growth': net_growth
                }

        except Exception as e:
            logger.error(f"Error getting joins/leaves for {guild_id}: {e}")
            return {'joins': [], 'leaves': [], 'total_joins': 0, 'total_leaves': 0, 'net_growth': 0}

    async def get_projected_joins_leaves(self, guild_id: str, days: int = 30) -> Dict[str, Any]:
        """Get projected joins and leaves using forecasting with future dates."""
        if not self.pool:
            return {
                'joins_forecast': [],
                'leaves_forecast': [],
                'joins_smoothed': [],
                'leaves_smoothed': [],
                'volatility': 0,
                'trend_direction': 'stable'
            }

        try:
            # For "all time", use 5 years (1825 days) for historical data
            historical_days = min(days * 2, 1825) if days <= 365 else 1825

            # Get historical joins data
            joins_points = []
            leaves_points = []

            # Get daily joins for the last historical_days days
            async with self.pool.acquire() as conn:
                query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(join_count), 0) as count
                    FROM member_joins_hourly
                    WHERE guild_id = $1
                    AND hour >= NOW() - INTERVAL '%s days'
                    GROUP BY DATE(hour)
                    ORDER BY date ASC
                """ % historical_days
                rows = await conn.fetch(query, int(guild_id))
                joins_points = [{'date': row['date'],
                                 'count': row['count']} for row in rows]

                query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(leave_count), 0) as count
                    FROM member_leaves_hourly
                    WHERE guild_id = $1
                    AND hour >= NOW() - INTERVAL '%s days'
                    GROUP BY DATE(hour)
                    ORDER BY date ASC
                """ % historical_days
                rows = await conn.fetch(query, int(guild_id))
                leaves_points = [{'date': row['date'],
                                  'count': row['count']} for row in rows]

            # Create forecasters
            forecaster_joins = GrowthForecaster(joins_points)
            forecaster_leaves = GrowthForecaster(leaves_points)

            # Get forecasts - for "all time", project up to 5 years (1825 days)
            forecast_days = min(days, 1825) if days else 1825
            joins_forecast_numeric = forecaster_joins.forecast(
                days_ahead=forecast_days)
            leaves_forecast_numeric = forecaster_leaves.forecast(
                days_ahead=forecast_days)

            # Generate future dates
            future_dates = []
            current_date = datetime.utcnow().date()
            for i in range(1, forecast_days + 1):
                future_date = current_date + timedelta(days=i)
                future_dates.append(future_date.isoformat())

            return {
                'joins_forecast': joins_forecast_numeric.get('future_predictions', []),
                'leaves_forecast': leaves_forecast_numeric.get('future_predictions', []),
                'joins_smoothed': joins_forecast_numeric.get('smoothed_data', []),
                'leaves_smoothed': leaves_forecast_numeric.get('smoothed_data', []),
                'future_dates': future_dates,  # Add this
                'volatility': max(joins_forecast_numeric.get('volatility', 0), leaves_forecast_numeric.get('volatility', 0)),
                'trend_direction': joins_forecast_numeric.get('trend_direction', 'stable'),
                'joins_analysis': {
                    'trend_slope': joins_forecast_numeric.get('trend_slope', 0),
                    'daily_growth_rate': joins_forecast_numeric.get('daily_growth_rate', 0),
                    'growth_rate_percent': joins_forecast_numeric.get('growth_rate_percent', 0),
                    'r2_confidence': joins_forecast_numeric.get('r2_confidence', 0),
                    'volatility': joins_forecast_numeric.get('volatility', 0),
                    'spike_status': joins_forecast_numeric.get('spike_status', 'normal')
                },
                'leaves_analysis': {
                    'trend_slope': leaves_forecast_numeric.get('trend_slope', 0),
                    'daily_growth_rate': leaves_forecast_numeric.get('daily_growth_rate', 0),
                    'growth_rate_percent': leaves_forecast_numeric.get('growth_rate_percent', 0),
                    'r2_confidence': leaves_forecast_numeric.get('r2_confidence', 0),
                    'volatility': leaves_forecast_numeric.get('volatility', 0),
                    'spike_status': leaves_forecast_numeric.get('spike_status', 'normal')
                }
            }

        except Exception as e:
            logger.error(
                f"Error getting projected joins/leaves for {guild_id}: {e}")
            return {
                'joins_forecast': [],
                'leaves_forecast': [],
                'joins_smoothed': [],
                'leaves_smoothed': [],
                'future_dates': [],
                'volatility': 0,
                'trend_direction': 'stable'
            }

    async def get_role_additions_removals(self, guild_id: str, role_id: str,
                                          days: Optional[int] = None,
                                          start_time: Optional[datetime] = None,
                                          end_time: Optional[datetime] = None) -> Dict[str, Any]:
        """Get role additions and removals timeseries."""
        if not self.pool:
            return {'added': [], 'removed': [], 'total_added': 0, 'total_removed': 0, 'net_growth': 0}

        try:
            guild_id_int = int(guild_id)
            role_id_int = int(role_id)

            async with self.pool.acquire() as conn:
                # FIX: For "all time", we should NOT use any date filter
                start_filter = None
                end_filter = None

                if start_time and end_time:
                    start_filter = start_time
                    end_filter = end_time
                elif days is not None and days > 0:
                    # Only apply days filter if days is provided and > 0
                    end_filter = datetime.utcnow()
                    start_filter = end_filter - timedelta(days=days)
                # If days is None and no start_time/end_time, get ALL data (leave filters as None)

                # Build added query
                added_query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(added_count), 0) as count
                    FROM role_growth_hourly
                    WHERE guild_id = $1
                    AND role_id = $2
                """
                added_params = [guild_id_int, role_id_int]
                param_index = 3

                # Add time filters ONLY if they exist
                if start_filter and end_filter:
                    added_query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                    added_params.append(start_filter)
                    added_params.append(end_filter)
                elif start_filter:
                    added_query += f" AND hour >= ${param_index}"
                    added_params.append(start_filter)
                elif end_filter:
                    added_query += f" AND hour <= ${param_index}"
                    added_params.append(end_filter)
                # If no filters, get ALL data

                # Apply bot filter
                added_query, added_params = await self._apply_bot_filter(
                    added_query, added_params, guild_id, 'role_growth_hourly'
                )

                added_query += " GROUP BY DATE(hour) ORDER BY date ASC"

                added_rows = await conn.fetch(added_query, *added_params)

                # Build removed query
                removed_query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(removed_count), 0) as count
                    FROM role_growth_hourly
                    WHERE guild_id = $1
                    AND role_id = $2
                """
                removed_params = [guild_id_int, role_id_int]
                param_index = 3

                # Add time filters ONLY if they exist
                if start_filter and end_filter:
                    removed_query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                    removed_params.append(start_filter)
                    removed_params.append(end_filter)
                elif start_filter:
                    removed_query += f" AND hour >= ${param_index}"
                    removed_params.append(start_filter)
                elif end_filter:
                    removed_query += f" AND hour <= ${param_index}"
                    removed_params.append(end_filter)
                # If no filters, get ALL data

                # Apply bot filter
                removed_query, removed_params = await self._apply_bot_filter(
                    removed_query, removed_params, guild_id, 'role_growth_hourly'
                )

                removed_query += " GROUP BY DATE(hour) ORDER BY date ASC"

                removed_rows = await conn.fetch(removed_query, *removed_params)

                # Convert to dictionaries
                added = [{'date': row['date'].isoformat(), 'count': row['count']}
                         for row in added_rows]
                removed = [{'date': row['date'].isoformat(), 'count': row['count']}
                           for row in removed_rows]

                total_added = sum(a['count'] for a in added)
                total_removed = sum(r['count'] for r in removed)
                net_growth = total_added - total_removed

                return {
                    'added': added,
                    'removed': removed,
                    'total_added': total_added,
                    'total_removed': total_removed,
                    'net_growth': net_growth
                }

        except Exception as e:
            logger.error(
                f"Error getting role additions/removals for {guild_id}/{role_id}: {e}")
            return {'added': [], 'removed': [], 'total_added': 0, 'total_removed': 0, 'net_growth': 0}

    async def get_projected_role_growth(self, guild_id: str, role_id: str, days: int = 30) -> Dict[str, Any]:
        """Get projected role additions and removals using forecasting."""
        if not self.pool:
            return {
                'added_forecast': [],
                'removed_forecast': [],
                'added_smoothed': [],
                'removed_smoothed': [],
                'future_dates': [],
                'volatility': 0,
                'trend_direction': 'stable',
                'warning': 'No data available'
            }

        try:
            # For "all time", use up to 5 years (1825 days) for historical data, but respect available data
            historical_days = min(days * 2, 1825) if days <= 365 else 1825

            # Get historical role data
            async with self.pool.acquire() as conn:
                # Get daily added counts
                added_query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(added_count), 0) as count
                    FROM role_growth_hourly
                    WHERE guild_id = $1
                    AND role_id = $2
                    AND hour >= NOW() - INTERVAL '%s days'
                    GROUP BY DATE(hour)
                    ORDER BY date ASC
                """ % historical_days
                added_rows = await conn.fetch(added_query, int(guild_id), int(role_id))
                added_points = [{'date': row['date'],
                                 'count': row['count']} for row in added_rows]

                # Get daily removed counts
                removed_query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(removed_count), 0) as count
                    FROM role_growth_hourly
                    WHERE guild_id = $1
                    AND role_id = $2
                    AND hour >= NOW() - INTERVAL '%s days'
                    GROUP BY DATE(hour)
                    ORDER BY date ASC
                """ % historical_days
                removed_rows = await conn.fetch(removed_query, int(guild_id), int(role_id))
                removed_points = [
                    {'date': row['date'], 'count': row['count']} for row in removed_rows]

            # Check if we have enough historical data
            warning = None
            if len(added_points) < 7:
                warning = f"Limited historical data ({len(added_points)} days). Projections may be inaccurate."
                logger.warning(
                    f"Role {role_id} has only {len(added_points)} days of historical data")

            # If we have no data at all, return empty
            if len(added_points) == 0 and len(removed_points) == 0:
                return {
                    'added_forecast': [],
                    'removed_forecast': [],
                    'added_smoothed': [],
                    'removed_smoothed': [],
                    'future_dates': [],
                    'volatility': 0,
                    'trend_direction': 'stable',
                    'warning': 'No historical data available for this role'
                }

            # Create forecasters
            forecaster_added = GrowthForecaster(added_points)
            forecaster_removed = GrowthForecaster(removed_points)

            # Get forecasts - use the actual days requested
            forecast_days = min(days, 1825) if days else 1825

            # Get the forecasts (this will now use the updated GrowthForecaster that doesn't cap at 90)
            added_forecast_result = forecaster_added.forecast(
                days_ahead=forecast_days)
            removed_forecast_result = forecaster_removed.forecast(
                days_ahead=forecast_days)

            added_forecast = added_forecast_result.get(
                'future_predictions', [])
            removed_forecast = removed_forecast_result.get(
                'future_predictions', [])

            # If we have very little historical data, pad the forecasts with zeros or use linear extrapolation
            if len(added_points) < 14 and len(added_forecast) < forecast_days:
                # Calculate average daily change if we have at least 2 data points
                if len(added_points) >= 2:
                    # Calculate average daily growth from historical data
                    historical_values = [p['count'] for p in added_points]
                    if len(historical_values) > 1:
                        avg_daily_change = (
                            historical_values[-1] - historical_values[0]) / len(historical_values)
                    else:
                        avg_daily_change = 0

                    # Extrapolate using the average daily change
                    last_value = historical_values[-1] if historical_values else 0
                    for i in range(len(added_forecast), forecast_days):
                        next_value = max(
                            0, last_value + (avg_daily_change * (i + 1)))
                        added_forecast.append(round(next_value, 2))
                        last_value = next_value
                else:
                    # If only 1 data point, use that value for all future predictions
                    last_value = added_points[0]['count'] if added_points else 0
                    while len(added_forecast) < forecast_days:
                        added_forecast.append(round(last_value, 2))

            # Do the same for removed forecasts
            if len(removed_points) < 14 and len(removed_forecast) < forecast_days:
                if len(removed_points) >= 2:
                    historical_values = [p['count'] for p in removed_points]
                    if len(historical_values) > 1:
                        avg_daily_change = (
                            historical_values[-1] - historical_values[0]) / len(historical_values)
                    else:
                        avg_daily_change = 0

                    last_value = historical_values[-1] if historical_values else 0
                    for i in range(len(removed_forecast), forecast_days):
                        next_value = max(
                            0, last_value + (avg_daily_change * (i + 1)))
                        removed_forecast.append(round(next_value, 2))
                        last_value = next_value
                else:
                    last_value = removed_points[0]['count'] if removed_points else 0
                    while len(removed_forecast) < forecast_days:
                        removed_forecast.append(round(last_value, 2))

            # Generate future dates
            future_dates = []
            current_date = datetime.utcnow().date()
            for i in range(1, forecast_days + 1):
                future_date = current_date + timedelta(days=i)
                future_dates.append(future_date.isoformat())

            # Trim to requested days
            added_forecast = added_forecast[:forecast_days]
            removed_forecast = removed_forecast[:forecast_days]
            future_dates = future_dates[:forecast_days]

            # Create projected data array with dates
            projected_data = []
            for i in range(len(future_dates)):
                projected_data.append({
                    'date': future_dates[i],
                    'added': added_forecast[i] if i < len(added_forecast) else 0,
                    'removed': removed_forecast[i] if i < len(removed_forecast) else 0
                })

            return {
                'added_forecast': added_forecast,
                'removed_forecast': removed_forecast,
                'added_smoothed': added_forecast_result.get('smoothed_data', []),
                'removed_smoothed': removed_forecast_result.get('smoothed_data', []),
                'future_dates': future_dates,
                'projected_data': projected_data,
                'volatility': max(added_forecast_result.get('volatility', 0), removed_forecast_result.get('volatility', 0)),
                'trend_direction': added_forecast_result.get('trend_direction', 'stable'),
                'warning': warning,
                'added_analysis': {
                    'trend_slope': added_forecast_result.get('trend_slope', 0),
                    'daily_growth_rate': added_forecast_result.get('daily_growth_rate', 0),
                    'growth_rate_percent': added_forecast_result.get('growth_rate_percent', 0),
                    'r2_confidence': added_forecast_result.get('r2_confidence', 0),
                    'volatility': added_forecast_result.get('volatility', 0),
                    'spike_status': added_forecast_result.get('spike_status', 'normal')
                },
                'removed_analysis': {
                    'trend_slope': removed_forecast_result.get('trend_slope', 0),
                    'daily_growth_rate': removed_forecast_result.get('daily_growth_rate', 0),
                    'growth_rate_percent': removed_forecast_result.get('growth_rate_percent', 0),
                    'r2_confidence': removed_forecast_result.get('r2_confidence', 0),
                    'volatility': removed_forecast_result.get('volatility', 0),
                    'spike_status': removed_forecast_result.get('spike_status', 'normal')
                }
            }

        except Exception as e:
            logger.error(
                f"Error getting projected role growth for {guild_id}/{role_id}: {e}")
            return {
                'added_forecast': [],
                'removed_forecast': [],
                'added_smoothed': [],
                'removed_smoothed': [],
                'future_dates': [],
                'projected_data': [],
                'volatility': 0,
                'trend_direction': 'stable',
                'warning': f'Error: {str(e)}'
            }

    async def q_user_timeseries_messages_daily(self, guild_id: str, user_id: str,
                                               role_filter_ids: Optional[List[str]] = None,
                                               start_time: Optional[datetime] = None,
                                               end_time: Optional[datetime] = None,
                                               max_points: int = 90) -> List[Dict[str, Any]]:
        """
        Get user message counts aggregated by day for the entire date range.
        Returns an array of {date: YYYY-MM-DD, messages: number} for each day in the range.
        """
        if not self.pool:
            return []

        try:
            # Convert IDs to integers FIRST
            guild_id_int = int(guild_id)
            user_id_int = int(user_id)

            async with self.pool.acquire() as conn:
                # If role filtering is needed, verify user has the role
                if role_filter_ids:
                    user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                    if not user_ids or user_id_int not in user_ids:
                        return []

                # Determine date range
                if not start_time:
                    end_time = end_time or datetime.utcnow()
                    start_time = end_time - timedelta(days=max_points)
                if not end_time:
                    end_time = datetime.utcnow()

                # Ensure we don't exceed max_points
                days_in_range = (end_time - start_time).days
                if days_in_range > max_points:
                    start_time = end_time - timedelta(days=max_points)

                # Build query for daily aggregation
                query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(message_count), 0) as message_count
                    FROM message_tracking_hourly
                    WHERE guild_id = $1
                    AND user_id = $2
                    AND hour >= $3
                    AND hour <= $4
                """
                params = [guild_id_int, user_id_int, start_time, end_time]

                # Apply bot filter
                query, params = await self._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')

                # Apply blacklist filters
                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'message_tracking_hourly',
                    include_users=True, include_channels=True
                )

                # Group by date and order
                query += " GROUP BY DATE(hour) ORDER BY date ASC"

                rows = await conn.fetch(query, *params)

                # Convert rows to dictionary for easy lookup
                data_by_date = {}
                for row in rows:
                    date_str = row['date'].isoformat()
                    data_by_date[date_str] = row['message_count'] or 0

                # Generate all dates in the range to ensure no gaps
                result = []
                current_date = start_time.date()
                end_date_obj = end_time.date()

                while current_date <= end_date_obj:
                    date_str = current_date.isoformat()
                    result.append({
                        'date': date_str,
                        'messages': data_by_date.get(date_str, 0)
                    })
                    current_date += timedelta(days=1)

                return result

        except ValueError as e:
            logger.error(
                f"Invalid ID format in q_user_timeseries_messages_daily: {e}")
            return []
        except Exception as e:
            logger.error(f"Error in q_user_timeseries_messages_daily: {e}")
            logger.error(traceback.format_exc())
            return []

