    async def q_channel_timeseries_voice_daily(self, guild_id: str, channel_id: str,
                                               role_filter_ids: Optional[List[str]] = None,
                                               start_time: Optional[datetime] = None,
                                               end_time: Optional[datetime] = None,
                                               max_points: int = 90) -> List[Dict[str, Any]]:
        """Get channel's daily voice timeseries."""
        if not self.pool:
            raise DatabaseConnectionError(
                "Database pool not available",
                context={'guild_id': guild_id, 'channel_id': channel_id}
            )

        try:
            guild_id_int = int(guild_id)
            channel_id_int = int(channel_id)

            if not end_time:
                end_time = datetime.utcnow()
            if not start_time:
                start_time = end_time - timedelta(days=max_points)

            days_in_range = (end_time - start_time).days
            if days_in_range > max_points:
                start_time = end_time - timedelta(days=max_points)

            user_ids = None
            if role_filter_ids:
                user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                if not user_ids:
                    result = []
                    current_date = start_time.date()
                    end_date_obj = end_time.date()
                    while current_date <= end_date_obj:
                        result.append({
                            "date": current_date.isoformat(),
                            "seconds": 0
                        })
                        current_date += timedelta(days=1)
                    return result

            async with self.pool.acquire() as conn:
                query = """
                    SELECT 
                        DATE(hour) as date,
                        COALESCE(SUM(total_seconds), 0) as total_seconds
                    FROM voice_session_history_hourly
                    WHERE guild_id = $1 
                    AND channel_id = $2
                    AND hour >= $3 
                    AND hour <= $4
                """
                params = [guild_id_int, channel_id_int, start_time, end_time]
                param_counter = 5

                if user_ids:
                    placeholders = [
                        f"${param_counter + i}" for i in range(len(user_ids))]
                    query += f" AND user_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                    param_counter += len(user_ids)

                query, params = await self._apply_voice_state_filter(query, params, guild_id, 'state_flags')
                query, params = await self._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')
                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'voice_session_history_hourly',
                    include_users=True, include_channels=False,
                    specific_channel_id=channel_id
                )

                query += " GROUP BY DATE(hour) ORDER BY date ASC"

                rows = await conn.fetch(query, *params)

                data_by_date = {}
                for row in rows:
                    date_str = row['date'].isoformat()
                    data_by_date[date_str] = row['total_seconds'] or 0

                result = []
                current_date = start_time.date()
                end_date_obj = end_time.date()

                while current_date <= end_date_obj:
                    date_str = current_date.isoformat()
                    result.append({
                        "date": date_str,
                        "seconds": data_by_date.get(date_str, 0)
                    })
                    current_date += timedelta(days=1)

                return result

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching channel voice timeseries",
                context={'guild_id': guild_id, 'channel_id': channel_id},
                original=e
            )
        except asyncpg.exceptions.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to fetch channel voice timeseries",
                context={'guild_id': guild_id, 'channel_id': channel_id},
                original=e
            )
        except Exception as e:
            raise DatabaseError(
                "Unexpected error fetching channel voice timeseries",
                context={'guild_id': guild_id, 'channel_id': channel_id},
                original=e
            )

