    async def q_user_total_voice(self, guild_id: str, user_id: str,
                                 role_filter_ids: Optional[List[str]] = None,
                                 start_time: Optional[datetime] = None,
                                 end_time: Optional[datetime] = None) -> Dict[str, Any]:
        """Get total voice stats for a user with role filtering."""
        if not self.pool:
            raise DatabaseConnectionError(
                "Database pool not available",
                context={'guild_id': guild_id, 'user_id': user_id}
            )

        try:
            guild_id_int = int(guild_id)
            user_id_int = int(user_id)

            if role_filter_ids:
                user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                if not user_ids or user_id_int not in user_ids:
                    return Constants.EMPTY_VOICE_RESULT

            async with self.pool.acquire() as conn:
                query = """
                    SELECT
                        COALESCE(SUM(total_seconds), 0) as total_seconds,
                        COALESCE(SUM(session_count), 0) as session_count,
                        MIN(hour) as first_session,
                        MAX(hour) + interval '1 hour' as last_session
                    FROM voice_session_history_hourly
                    WHERE guild_id = $1 AND user_id = $2
                """
                params = [guild_id_int, user_id_int]
                param_counter = 3

                query, params = await self._apply_voice_state_filter(query, params, guild_id, 'state_flags')
                param_counter = len(params) + 1

                if start_time:
                    query += f" AND hour >= ${param_counter}"
                    params.append(start_time)
                    param_counter += 1
                if end_time:
                    query += f" AND hour <= ${param_counter}"
                    params.append(end_time)
                    param_counter += 1

                query, params = await self._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')
                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'voice_session_history_hourly',
                    include_users=True, include_channels=True
                )

                row = await conn.fetchrow(query, *params)

                if not row:
                    return Constants.EMPTY_VOICE_RESULT

                total_seconds = row['total_seconds'] or 0

                return {
                    'total_seconds': total_seconds,
                    'total_hours': round(total_seconds / 3600, 2),
                    'session_count': row['session_count'] or 0,
                    'avg_session': 0.0,
                    'first_session': row['first_session'].isoformat() if row['first_session'] else None,
                    'last_session': row['last_session'].isoformat() if row['last_session'] else None
                }

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching user total voice",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except asyncpg.exceptions.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to fetch user total voice stats",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except Exception as e:
            raise DatabaseError(
                "Unexpected error fetching user total voice stats",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )

    async def q_user_messages_per_hour_distribution(self, guild_id: str, user_id: str,
                                                    role_filter_ids: Optional[List[str]] = None,
                                                    start_time: Optional[datetime] = None,
                                                    end_time: Optional[datetime] = None,
                                                    timezone_str: str = 'UTC') -> Dict[str, Any]:
        """Get message distribution by hour for a user with role filtering using hourly aggregated table."""
        if not self.pool:
            result = {f'hour_{i}': 0 for i in range(24)}
            result.update({'total': 0, 'peak_hour': -1})
            return result

        try:
            async with self.pool.acquire() as conn:
                # If role filtering is needed, verify user has the role
                if role_filter_ids:
                    user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                    if not user_ids or int(user_id) not in user_ids:
                        # User doesn't have the required role
                        result = {f'hour_{i}': 0 for i in range(24)}
                        result.update({'total': 0, 'peak_hour': -1})
                        return result

                query = f'''
                    SELECT
                        EXTRACT(HOUR FROM hour AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}') as hour,
                        SUM(message_count) as message_count
                    FROM message_tracking_hourly
                    WHERE guild_id = $1 AND user_id = $2
                '''
                params = [int(guild_id), int(user_id)]

                query, params = await self._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')

                if start_time:
                    query += f" AND hour >= ${len(params) + 1}"
                    params.append(start_time)
                if end_time:
                    query += f" AND hour <= ${len(params) + 1}"
                    params.append(end_time)

                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'message_tracking_hourly',
                    include_users=True, include_channels=True
                )

                query += '''
                    GROUP BY hour
                    ORDER BY hour
                '''

                try:
                    rows = await conn.fetch(query, *params)
                except asyncpg.PostgresError as e:
                    if "timeout" in str(e).lower():
                        raise DatabaseTimeoutError(
                            "Database operation timed out while fetching user message hour distribution",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e
                    else:
                        raise DatabaseQueryError(
                            "Failed to fetch user message hour distribution",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e

                result = {f'hour_{i}': 0 for i in range(24)}
                total = 0
                peak_hour = -1
                peak_count = 0

                for row in rows:
                    hour = int(row['hour'])
                    count = row['message_count'] or 0
                    result[f'hour_{hour}'] = count
                    total += count

                    if count > peak_count:
                        peak_count = count
                        peak_hour = hour

                result['total'] = total
                result['peak_hour'] = peak_hour

                return result

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching user message hour distribution",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except DatabaseError:
            raise
        except Exception as e:
            raise DatabaseQueryError(
                "Unexpected error fetching user message hour distribution",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )

