    # ============================================
    # USER TOP VOICE CHANNELS (with keyset pagination) - UPDATED FOR AGGREGATED TABLES
    # ============================================

    async def q_user_top_voice_channels(self, guild_id: str, user_id: str,
                                        role_filter_ids: Optional[List[str]] = None,
                                        start_time: Optional[datetime] = None,
                                        end_time: Optional[datetime] = None,
                                        limit: int = 100000000000,
                                        after_value: Optional[int] = None,
                                        after_id: Optional[str] = None,
                                        use_cache: bool = True) -> List[Dict[str, Any]]:
        """Get user's top voice channels with keyset pagination."""
        if not self.pool:
            raise DatabaseConnectionError(
                "Database pool not available",
                context={'guild_id': guild_id, 'user_id': user_id}
            )

        try:
            guild_id_int = int(guild_id)
            user_id_int = int(user_id)

            if role_filter_ids:
                user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                if not user_ids or user_id_int not in user_ids:
                    return []

            async with self.pool.acquire() as conn:
                query = """
                    SELECT
                        channel_id,
                        SUM(total_seconds) as total_seconds,
                        SUM(session_count) as session_count
                    FROM voice_session_history_hourly
                    WHERE guild_id = $1 AND user_id = $2
                """
                params = [guild_id_int, user_id_int]
                param_counter = 3

                query, params = await self._apply_voice_state_filter(query, params, guild_id, 'state_flags')
                param_counter = len(params) + 1

                if start_time:
                    query += f" AND hour >= ${param_counter}"
                    params.append(start_time)
                    param_counter += 1
                if end_time:
                    query += f" AND hour <= ${param_counter}"
                    params.append(end_time)
                    param_counter += 1

                query, params = await self._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')
                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'voice_session_history_hourly',
                    include_users=True, include_channels=True
                )

                query += " GROUP BY channel_id HAVING SUM(total_seconds) > 0"

                if after_value is not None:
                    params.append(after_value)
                    if after_id:
                        params.append(int(after_id))
                        query += f" AND (SUM(total_seconds) < ${len(params)-1} OR (SUM(total_seconds) = ${len(params)-1} AND channel_id < ${len(params)}))"
                    else:
                        query += f" AND SUM(total_seconds) < ${len(params)}"

                query += f" ORDER BY total_seconds DESC, channel_id DESC LIMIT {limit}"

                rows = await conn.fetch(query, *params)

                result = []
                for row in rows:
                    result.append({
                        'channel_id': str(row['channel_id']),
                        'total_seconds': row['total_seconds'] or 0,
                        'total_hours': round((row['total_seconds'] or 0) / 3600, 2),
                        'session_count': row['session_count'] or 0
                    })

                return result

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching user top voice channels",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except asyncpg.exceptions.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to fetch user top voice channels",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except Exception as e:
            raise DatabaseError(
                "Unexpected error fetching user top voice channels",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )

    # ============================================
    # USER TOP TEXT CHANNELS (with keyset pagination) - UPDATED FOR AGGREGATED TABLES
    # ============================================

    async def q_user_top_text_channels(self, guild_id: str, user_id: str,
                                       role_filter_ids: Optional[List[str]] = None,
                                       start_time: Optional[datetime] = None,
                                       end_time: Optional[datetime] = None,
                                       limit: int = 100000000000,
                                       after_value: Optional[int] = None,
                                       after_id: Optional[str] = None,
                                       use_cache: bool = True) -> List[Dict[str, Any]]:
        """Get user's top text channels with keyset pagination using hourly aggregated table."""
        if not self.pool:
            return []

        try:
            # If role filtering is needed, verify user has the role
            if role_filter_ids:
                user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                if not user_ids or int(user_id) not in user_ids:
                    return []

            # Generate cache key
            cache_key = None
            if use_cache and after_value is None:
                cache_key = f"leaderboard:user_text:{guild_id}:{user_id}:{role_filter_ids}"
                cached = await self._get_cached_leaderboard(cache_key)
                if cached:
                    if after_value is not None:
                        start_idx = 0
                        for i, item in enumerate(cached):
                            if item['message_count'] < after_value:
                                start_idx = i
                                break
                            elif item['message_count'] == after_value and after_id and int(item['channel_id']) < int(after_id):
                                start_idx = i
                                break
                        return cached[start_idx:start_idx + limit]
                    else:
                        return cached[:limit]

            async with self.pool.acquire() as conn:
                total_query = '''
                    SELECT COALESCE(SUM(message_count), 0) as total_messages
                    FROM message_tracking_hourly
                    WHERE guild_id = $1 AND user_id = $2
                '''
                total_params = [int(guild_id), int(user_id)]

                total_query, total_params = await self._apply_bot_filter(total_query, total_params, guild_id, 'message_tracking_hourly')

                if start_time:
                    total_params.append(start_time)
                    total_query += f" AND hour >= ${len(total_params)}"
                if end_time:
                    total_params.append(end_time)
                    total_query += f" AND hour <= ${len(total_params)}"

                total_query, total_params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, total_query, total_params, 'message_tracking_hourly',
                    include_users=True, include_channels=True
                )

                try:
                    total_row = await conn.fetchrow(total_query, *total_params)
                except asyncpg.PostgresError as e:
                    if "timeout" in str(e).lower():
                        raise DatabaseTimeoutError(
                            "Database operation timed out while fetching user total messages for top channels",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e
                    else:
                        raise DatabaseQueryError(
                            "Failed to fetch user total messages for top channels",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e

                total_messages = total_row['total_messages'] or 0

                if total_messages == 0:
                    return []

                query = '''
                    SELECT
                        channel_id,
                        SUM(message_count) as message_count,
                        COALESCE(SUM(total_chars), 0) as total_chars,
                        COALESCE(SUM(total_chars) / NULLIF(SUM(message_count), 0), 0) as avg_chars
                    FROM message_tracking_hourly
                    WHERE guild_id = $1 AND user_id = $2
                '''
                params = [int(guild_id), int(user_id)]

                query, params = await self._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')

                if start_time:
                    params.append(start_time)
                    query += f" AND hour >= ${len(params)}"
                if end_time:
                    params.append(end_time)
                    query += f" AND hour <= ${len(params)}"

                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'message_tracking_hourly',
                    include_users=True, include_channels=True
                )

                # Add GROUP BY first
                query += " GROUP BY channel_id"

                # Add keyset pagination with HAVING
                if after_value is not None:
                    params.append(after_value)
                    if after_id:
                        params.append(int(after_id))
                        query += f" HAVING (SUM(message_count) < ${len(params)-1}) OR (SUM(message_count) = ${len(params)-1} AND channel_id < ${len(params)})"
                    else:
                        query += f" HAVING SUM(message_count) < ${len(params)}"
                else:
                    query += " HAVING SUM(message_count) > 0"

                query += f" ORDER BY message_count DESC, channel_id DESC LIMIT {limit}"

                try:
                    rows = await conn.fetch(query, *params)
                except asyncpg.PostgresError as e:
                    if "timeout" in str(e).lower():
                        raise DatabaseTimeoutError(
                            "Database operation timed out while fetching user top text channels",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e
                    else:
                        raise DatabaseQueryError(
                            "Failed to fetch user top text channels",
                            context={'guild_id': guild_id, 'user_id': user_id},
                            original=e
                        ) from e

                result = []
                for row in rows:
                    channel_messages = row['message_count'] or 0
                    percentage = (channel_messages / total_messages *
                                  100) if total_messages > 0 else 0

                    result.append({
                        'channel_id': str(row['channel_id']),
                        'message_count': channel_messages,
                        'total_chars': row['total_chars'] or 0,
                        'avg_chars': round(row['avg_chars'] or 0, 2),
                        'percentage': round(percentage, 1)
                    })

                # Cache the full first page
                if cache_key and after_value is None and result:
                    full_first_page = result[:100]  # Cache up to 100 items
                    await self._set_cached_leaderboard(cache_key, full_first_page)

                return result

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching user top text channels",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )
        except DatabaseError:
            raise
        except Exception as e:
            raise DatabaseQueryError(
                "Unexpected error fetching user top text channels",
                context={'guild_id': guild_id, 'user_id': user_id},
                original=e
            )

