        try:
            guild_id_int = int(guild_id)

            state_flags_filter = await self._get_voice_state_filter_value(guild_id)

            # Apply role filtering if needed
            user_ids = None
            if role_filter_ids:
                user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                if not user_ids:
                    return []

            async with self.pool.acquire() as conn:
                # Build query with time filters
                query = """
                    SELECT
                        channel_id,
                        SUM(total_seconds) as total_seconds,
                        SUM(session_count) as session_count
                    FROM voice_session_history_hourly
                    WHERE guild_id = $1
                """
                params = [guild_id_int]
                param_counter = 2

                # Add user filter if needed
                if user_ids:
                    placeholders = [
                        f"${param_counter + i}" for i in range(len(user_ids))]
                    query += f" AND user_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                    param_counter += len(user_ids)

                # CRITICAL FIX: Use BITWISE AND for voice state filter
                if state_flags_filter is not None:
                    query += f" AND (state_flags = 0 OR (state_flags & ${param_counter}) != 0)"
                    params.append(state_flags_filter)
                    param_counter += 1

                # Add time filters
                if start_time:
                    query += f" AND hour >= ${param_counter}"
                    params.append(start_time)
                    param_counter += 1
                if end_time:
                    query += f" AND hour <= ${param_counter}"
                    params.append(end_time)
                    param_counter += 1

                # Add blacklist filters
                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'voice_session_history_hourly',
                    include_users=True, include_channels=True
                )

                # Apply bot filter
                query, params = await self._apply_bot_filter(
                    query, params, guild_id, 'voice_session_history_hourly'
                )

                # Add GROUP BY
                query += " GROUP BY channel_id"

                # Add HAVING clause for pagination
                if after_value is not None:
                    params.append(after_value)
                    if after_id:
                        params.append(int(after_id))
                        query += f" HAVING (SUM(total_seconds) < ${len(params)-1} OR (SUM(total_seconds) = ${len(params)-1} AND channel_id < ${len(params)}))"
                    else:
                        query += f" HAVING SUM(total_seconds) < ${len(params)}"
                else:
                    query += " HAVING SUM(total_seconds) > 0"

                # Add ORDER BY and LIMIT
                query += f" ORDER BY total_seconds DESC, channel_id DESC LIMIT {limit}"

                rows = await conn.fetch(query, *params)

                # Get total seconds for percentage calculation (with SAME filters)
                total_query = """
                    SELECT COALESCE(SUM(total_seconds), 0) as total_seconds
                    FROM voice_session_history_hourly
                    WHERE guild_id = $1
                """
                total_params = [guild_id_int]
                total_param_counter = 2

                if user_ids:
                    placeholders = [
                        f"${total_param_counter + i}" for i in range(len(user_ids))]
                    total_query += f" AND user_id IN ({', '.join(placeholders)})"
                    total_params.extend(user_ids)
                    total_param_counter += len(user_ids)

                if state_flags_filter is not None:
                    total_query += f" AND (state_flags = 0 OR (state_flags & ${total_param_counter}) != 0)"
                    total_params.append(state_flags_filter)
                    total_param_counter += 1

                if start_time:
                    total_query += f" AND hour >= ${total_param_counter}"
                    total_params.append(start_time)
                    total_param_counter += 1
                if end_time:
                    total_query += f" AND hour <= ${total_param_counter}"
                    total_params.append(end_time)
                    total_param_counter += 1

                total_query, total_params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, total_query, total_params, 'voice_session_history_hourly',
                    include_users=True, include_channels=True
                )

                total_query, total_params = await self._apply_bot_filter(
                    total_query, total_params, guild_id, 'voice_session_history_hourly'
                )

                total_row = await conn.fetchrow(total_query, *total_params)
                total_seconds = total_row['total_seconds'] if total_row and total_row['total_seconds'] else 0

                result = []
                for row in rows:
                    channel_seconds = row['total_seconds'] or 0
                    percentage = (channel_seconds / total_seconds *
                                  100) if total_seconds > 0 else 0

                    result.append({
                        'channel_id': str(row['channel_id']),
                        'total_seconds': channel_seconds,
                        'total_hours': round(channel_seconds / 3600, 2),
                        'session_count': row['session_count'] or 0,
                        'percentage': round(percentage, 1)
                    })

                return result

        except Exception as e:
            logger.error(
                f"Error in q_leaderboard_server_top_voice_channels: {e}")
            logger.error(traceback.format_exc())
            return []
