    # ======================================================================
    # MENTIONS RATIO CALCULATOR (Received / Sent) - already defined but ensure they exist
    # ======================================================================

    async def q_user_mentions_ratio_server(
        self, guild_id: int, user_id: int,
        role_filter_ids: Optional[List[int]] = None,
        start_time: Optional[datetime] = None,
        end_time: Optional[datetime] = None
    ) -> Dict[str, Any]:
        """Calculate mentions ratio for a user (SERVER SCOPE)."""
        if not self.pool:
            return {'mentions_sent': 0, 'mentions_received': 0, 'ratio': 0.0}

        try:
            start_time = ensure_aware(start_time) if start_time else None
            end_time = ensure_aware(end_time) if end_time else None

            async with self.pool.acquire() as conn:
                # Query for mentions sent
                sent_query = """
                    SELECT COALESCE(SUM(mention_count), 0) as mentions_sent
                    FROM user_mentions_hourly
                    WHERE guild_id = $1 AND mentioner_user_id = $2
                """
                sent_params = [guild_id, user_id]
                param_index = 3

                if start_time:
                    sent_query += f" AND hour >= ${param_index}"
                    sent_params.append(start_time)
                    param_index += 1
                if end_time:
                    sent_query += f" AND hour <= ${param_index}"
                    sent_params.append(end_time)
                    param_index += 1

                if role_filter_ids:
                    user_ids = await self._get_users_with_roles(str(guild_id), [str(rid) for rid in role_filter_ids])
                    if user_ids and user_id not in user_ids:
                        return {'mentions_sent': 0, 'mentions_received': 0, 'ratio': 0.0}

                sent_query, sent_params = await self._apply_bot_filter(sent_query, sent_params, str(guild_id), 'user_mentions_hourly')
                sent_row = await conn.fetchrow(sent_query, *sent_params)
                mentions_sent = sent_row['mentions_sent'] if sent_row else 0

                # Query for mentions received
                received_query = """
                    SELECT COALESCE(SUM(mention_count), 0) as mentions_received
                    FROM user_mentions_hourly
                    WHERE guild_id = $1 AND mentioned_user_id = $2
                """
                received_params = [guild_id, user_id]
                param_index = 3

                if start_time:
                    received_query += f" AND hour >= ${param_index}"
                    received_params.append(start_time)
                    param_index += 1
                if end_time:
                    received_query += f" AND hour <= ${param_index}"
                    received_params.append(end_time)
                    param_index += 1

                received_query, received_params = await self._apply_bot_filter(received_query, received_params, str(guild_id), 'user_mentions_hourly')
                received_row = await conn.fetchrow(received_query, *received_params)
                mentions_received = received_row['mentions_received'] if received_row else 0

                # Use 1 as minimum to avoid division by zero
                sent_for_ratio = max(mentions_sent, 1)
                ratio = mentions_received / sent_for_ratio
                ratio_display = round(ratio, 2)

                return {
                    'mentions_sent': mentions_sent,
                    'mentions_received': mentions_received,
                    'ratio': ratio,
                    'ratio_display': ratio_display
                }

        except Exception as e:
            logger.error(f"Failed to calculate user mentions ratio: {e}")
            return {'mentions_sent': 0, 'mentions_received': 0, 'ratio': 0.0, 'ratio_display': 0.0}

    # ======================================================================
    # MENTIONS TO USER LEADERBOARD (Who a user mentioned)
    # ======================================================================

    async def q_leaderboard_mentions_to_user_server(
        self, guild_id: int, source_user_id: int,
        limit: int = 100,
        role_filter_ids: Optional[List[int]] = None,
        start_time: Optional[datetime] = None,
        end_time: Optional[datetime] = None
    ) -> List[Dict[str, Any]]:
        """
        Get leaderboard of users that the source user mentioned (SERVER SCOPE).
        """
        if not self.pool:
            return []

        try:
            start_time = ensure_aware(start_time) if start_time else None
            end_time = ensure_aware(end_time) if end_time else None

            async with self.pool.acquire() as conn:
                query = """
                    SELECT 
                        mentioned_user_id as user_id,
                        SUM(mention_count) as mention_count,
                        MAX(hour) as last_mention
                    FROM user_mentions_hourly
                    WHERE guild_id = $1 AND mentioner_user_id = $2
                """
                params = [guild_id, source_user_id]
                param_index = 3

                if start_time:
                    query += f" AND hour >= ${param_index}"
                    params.append(start_time)
                    param_index += 1
                if end_time:
                    query += f" AND hour <= ${param_index}"
                    params.append(end_time)
                    param_index += 1

                if role_filter_ids:
                    user_ids = await self._get_users_with_roles(str(guild_id), [str(rid) for rid in role_filter_ids])
                    if user_ids and source_user_id not in user_ids:
                        return []
                    if user_ids:
                        query += f" AND mentioned_user_id = ANY(${param_index}::bigint[])"
                        params.append(user_ids)
                        param_index += 1

                query, params = await self._apply_bot_filter(query, params, str(guild_id), 'user_mentions_hourly')
                query, params = await self._apply_comprehensive_blacklist_filters(
                    str(guild_id), query, params, 'user_mentions_hourly',
                    include_users=True, include_channels=True
                )

                total_query = """
                    SELECT COALESCE(SUM(mention_count), 0) as total_mentions
                    FROM user_mentions_hourly
                    WHERE guild_id = $1 AND mentioner_user_id = $2
                """
                total_params = [guild_id, source_user_id]
                total_param_index = 3

                if start_time:
                    total_query += f" AND hour >= ${total_param_index}"
                    total_params.append(start_time)
                    total_param_index += 1
                if end_time:
                    total_query += f" AND hour <= ${total_param_index}"
                    total_params.append(end_time)
                    total_param_index += 1

                total_row = await conn.fetchrow(total_query, *total_params)
                total_mentions = total_row['total_mentions'] if total_row else 0

                if total_mentions == 0:
                    return []

                query += """
                    GROUP BY mentioned_user_id
                    HAVING SUM(mention_count) > 0
                    ORDER BY mention_count DESC
                """

                if limit:
                    query += f" LIMIT ${param_index}"
                    params.append(limit)

                rows = await conn.fetch(query, *params)

                result = []
                for row in rows:
                    user_mentions = row['mention_count'] or 0
                    percentage = (user_mentions / total_mentions *
                                  100) if total_mentions > 0 else 0

                    result.append({
                        'user_id': row['user_id'],
                        'mention_count': user_mentions,
                        'last_mention': row['last_mention'].isoformat() if row['last_mention'] else None,
                        'percentage': round(percentage, 1)
                    })

                return result

        except Exception as e:
            logger.error(
                f"Failed to fetch server mentions to user leaderboard: {e}")
            return []

    async def q_leaderboard_mentions_target_user(self, guild_id: str, mentioned_user_id: str,
                                                 limit: int = 100000000000,
                                                 role_filter_ids: Optional[List[str]] = None,
                                                 start_time: Optional[datetime] = None,
                                                 end_time: Optional[datetime] = None,
                                                 after_value: Optional[int] = None,
                                                 after_id: Optional[str] = None,
                                                 use_cache: bool = True) -> List[Dict[str, Any]]:
        """Get leaderboard of users who mention a target user with keyset pagination using hourly aggregated table."""
        if not self.pool:
            return []

        try:
            # Generate cache key
            cache_key = None
            if use_cache and after_value is None:
                cache_key = f"leaderboard:mentions:{guild_id}:{mentioned_user_id}:{role_filter_ids}"
                cached = await self._get_cached_leaderboard(cache_key)
                if cached:
                    if after_value is not None:
                        start_idx = 0
                        for i, item in enumerate(cached):
                            if item['mention_count'] < after_value:
                                start_idx = i
                                break
                            elif item['mention_count'] == after_value and after_id and int(item['user_id']) < int(after_id):
                                start_idx = i
                                break
                        return cached[start_idx:start_idx + limit]
                    else:
                        return cached[:limit]

            async with self.pool.acquire() as conn:
                total_query = '''
                    SELECT COALESCE(SUM(mention_count), 0) as total_mentions
                    FROM user_mentions_hourly
                    WHERE guild_id = $1
                    AND mentioned_user_id = $2
                '''
                total_params = [int(guild_id), int(mentioned_user_id)]

                # Apply role filtering if needed (filtering by mentioner's roles)
                if role_filter_ids:
                    user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                    if user_ids:
                        placeholders = [
                            f"${len(total_params) + i + 1}" for i in range(len(user_ids))]
                        total_query += f" AND mentioner_user_id IN ({', '.join(placeholders)})"
                        total_params.extend(user_ids)
                    else:
                        return []

                total_query, total_params = await self._apply_bot_filter(total_query, total_params, guild_id, 'user_mentions_hourly')

                if start_time:
                    total_params.append(start_time)
                    total_query += f" AND hour >= ${len(total_params)}"
                if end_time:
                    total_params.append(end_time)
                    total_query += f" AND hour <= ${len(total_params)}"

                total_query, total_params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, total_query, total_params, 'user_mentions_hourly',
                    include_users=True, include_channels=True
                )

                try:
                    total_row = await conn.fetchrow(total_query, *total_params)
                except asyncpg.PostgresError as e:
                    raise DatabaseQueryError(
                        "Failed to fetch total mentions for leaderboard",
                        context={'guild_id': guild_id,
                                 'mentioned_user_id': mentioned_user_id},
                        original=e
                    )

                total_mentions = total_row['total_mentions'] or 0

                if total_mentions == 0:
                    return []

                query = '''
                    SELECT
                        mentioner_user_id,
                        SUM(mention_count) as mention_count,
                        MAX(hour) as last_mention
                    FROM user_mentions_hourly
                    WHERE guild_id = $1
                    AND mentioned_user_id = $2
                '''
                params = [int(guild_id), int(mentioned_user_id)]
                param_index = 3

                # Apply role filtering if needed
                if role_filter_ids:
                    user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                    if user_ids:
                        placeholders = [
                            f"${param_index + i}" for i in range(len(user_ids))]
                        query += f" AND mentioner_user_id IN ({', '.join(placeholders)})"
                        params.extend(user_ids)
                        param_index += len(user_ids)

                query, params = await self._apply_bot_filter(query, params, guild_id, 'user_mentions_hourly')

                if start_time:
                    params.append(start_time)
                    query += f" AND hour >= ${len(params)}"
                    param_index += 1
                if end_time:
                    params.append(end_time)
                    query += f" AND hour <= ${len(params)}"
                    param_index += 1

                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'user_mentions_hourly',
                    include_users=True, include_channels=True
                )

                # Add GROUP BY first
                query += " GROUP BY mentioner_user_id"

                # Then add keyset pagination with HAVING
                if after_value is not None:
                    params.append(after_value)
                    if after_id:
                        params.append(int(after_id))
                        query += f" HAVING (SUM(mention_count) < ${len(params)-1}) OR (SUM(mention_count) = ${len(params)-1} AND mentioner_user_id < ${len(params)})"
                    else:
                        query += f" HAVING SUM(mention_count) < ${len(params)}"
                else:
                    query += " HAVING SUM(mention_count) > 0"

                # Then ORDER BY and LIMIT
                query += f" ORDER BY mention_count DESC, mentioner_user_id DESC LIMIT {limit}"

                try:
                    rows = await conn.fetch(query, *params)
                except asyncpg.PostgresError as e:
                    raise DatabaseQueryError(
                        "Failed to fetch mentions leaderboard",
                        context={'guild_id': guild_id,
                                 'mentioned_user_id': mentioned_user_id},
                        original=e
                    )

                result = []
                for row in rows:
                    user_mentions = row['mention_count'] or 0
                    percentage = (user_mentions / total_mentions *
                                  100) if total_mentions > 0 else 0

                    result.append({
                        'user_id': str(row['mentioner_user_id']),
                        'mention_count': user_mentions,
                        'last_mention': row['last_mention'].isoformat() if row['last_mention'] else None,
                        'percentage': round(percentage, 1)
                    })

                # Cache the full first page
                if cache_key and after_value is None and result:
                    full_first_page = result[:100]  # Cache up to 100 items
                    await self._set_cached_leaderboard(cache_key, full_first_page)

                return result

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching mentions leaderboard",
                context={'guild_id': guild_id,
                         'mentioned_user_id': mentioned_user_id},
                original=e
            )
        except asyncpg.exceptions.PostgresError as e:
            if "timeout" in str(e).lower():
                raise DatabaseTimeoutError(
                    "Database operation timed out while fetching mentions leaderboard",
                    context={'guild_id': guild_id,
                             'mentioned_user_id': mentioned_user_id},
                    original=e
                ) from e
            else:
                raise DatabaseQueryError(
                    "Database query failed while fetching mentions leaderboard",
                    context={'guild_id': guild_id,
                             'mentioned_user_id': mentioned_user_id},
                    original=e
                ) from e
        except DatabaseError:
            raise
        except Exception as e:
            raise DatabaseQueryError(
                "Unexpected error fetching mentions leaderboard",
                context={'guild_id': guild_id,
                         'mentioned_user_id': mentioned_user_id},
                original=e
            )

    # ============================================
    # EMOJI LEADERBOARDS (with keyset pagination) - UPDATED FOR AGGREGATED TABLES
    # ============================================

    async def q_emoji_server_leaderboard(self, guild_id: str,
                                         limit: int = 100000000000,
                                         role_filter_ids: Optional[List[str]] = None,
                                         start_time: Optional[datetime] = None,
                                         end_time: Optional[datetime] = None,
                                         usage_type: Optional[str] = None,
                                         after_value: Optional[int] = None,
                                         after_id: Optional[str] = None,
                                         use_cache: bool = True) -> List[Dict[str, Any]]:
        """Get server's emoji usage leaderboard with keyset pagination using hourly aggregated table."""
        if not self.pool:
            return []

        try:
            # Generate cache key
            cache_key = None
            if use_cache and after_value is None:
                # Include time filters in cache key
                time_key = f"{start_time}_{end_time}" if start_time or end_time else "notime"
                cache_key = f"leaderboard:emojis_server:{guild_id}:{role_filter_ids}:{usage_type}:{time_key}"
                cached = await self._get_cached_leaderboard(cache_key)
                if cached:
                    if after_value is not None:
                        start_idx = 0
                        for i, item in enumerate(cached):
                            if item['usage_count'] < after_value:
                                start_idx = i
                                break
                            elif item['usage_count'] == after_value and after_id and item['emoji_str'] < after_id:
                                start_idx = i
                                break
                        return cached[start_idx:start_idx + limit]
                    else:
                        return cached[:limit]

            async with self.pool.acquire() as conn:
                # FIX: Add time filters to total_query!
                total_query = '''
                    SELECT COALESCE(SUM(usage_count), 0) as total_usage
                    FROM emoji_usage_hourly
                    WHERE guild_id = $1
                '''
                total_params = [int(guild_id)]
                param_index = 2

                # Apply role filtering if needed
                if role_filter_ids:
                    user_ids = await self._get_users_with_roles(guild_id, role_filter_ids)
                    if user_ids:
                        placeholders = [
                            f"${param_index + i}" for i in range(len(user_ids))]
                        total_query += f" AND user_id IN ({', '.join(placeholders)})"
                        total_params.extend(user_ids)
                        param_index += len(user_ids)
                    else:
                        return []

                # Add time filters to total_query
                if start_time:
                    total_params.append(start_time)
                    total_query += f" AND hour >= ${len(total_params)}"
                if end_time:
                    total_params.append(end_time)
                    total_query += f" AND hour <= ${len(total_params)}"

                if usage_type:
                    total_params.append(usage_type)
                    total_query += f" AND usage_type = ${len(total_params)}"

                total_query, total_params = await self._apply_bot_filter(
                    total_query, total_params, guild_id, 'emoji_usage_hourly'
                )

                total_row = await conn.fetchrow(total_query, *total_params)
                total_usage = total_row['total_usage'] or 0

                if total_usage == 0:
                    return []

                # Main query
                query = '''
                    SELECT
                        emoji_str,
                        is_custom,
                        SUM(usage_count) as total_usage,
                        COUNT(DISTINCT user_id) as unique_users
                    FROM emoji_usage_hourly
                    WHERE guild_id = $1
                '''
                params = [int(guild_id)]
                param_index = 2

                # Apply role filtering if needed
                if role_filter_ids and user_ids:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(user_ids))]
                    query += f" AND user_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                    param_index += len(user_ids)

                # Add time filters
                if start_time:
                    params.append(start_time)
                    query += f" AND hour >= ${len(params)}"
                if end_time:
                    params.append(end_time)
                    query += f" AND hour <= ${len(params)}"

                if usage_type:
                    params.append(usage_type)
                    query += f" AND usage_type = ${len(params)}"

                query, params = await self._apply_bot_filter(
                    query, params, guild_id, 'emoji_usage_hourly'
                )

                # Apply blacklist filters
                query, params = await self._apply_comprehensive_blacklist_filters(
                    guild_id, query, params, 'emoji_usage_hourly',
                    include_users=True, include_channels=True
                )

                # Add GROUP BY
                query += " GROUP BY emoji_str, is_custom"

                # Add keyset pagination with HAVING
                if after_value is not None:
                    params.append(after_value)
                    if after_id:
                        params.append(after_id)
                        query += f" HAVING (SUM(usage_count) < ${len(params)-1}) OR (SUM(usage_count) = ${len(params)-1} AND emoji_str < ${len(params)})"
                    else:
                        query += f" HAVING SUM(usage_count) < ${len(params)}"
                else:
                    query += " HAVING SUM(usage_count) > 0"

                query += f" ORDER BY total_usage DESC, emoji_str DESC LIMIT {limit}"

                try:
                    rows = await conn.fetch(query, *params)
                except asyncpg.PostgresError as e:
                    raise DatabaseQueryError(
                        "Failed to fetch server emoji leaderboard",
                        context={'guild_id': guild_id},
                        original=e
                    )

                result = []
                for row in rows:
                    emoji_usage = row['total_usage'] or 0
                    unique_users = row['unique_users'] or 0
                    percentage = (emoji_usage / total_usage *
                                  100) if total_usage > 0 else 0
                    avg_usage = emoji_usage / max(unique_users, 1)

                    result.append({
                        'emoji_str': row['emoji_str'],
                        'is_custom': row['is_custom'],
                        'usage_count': emoji_usage,
                        'unique_users': unique_users,
                        'avg_usage_per_user': round(avg_usage, 2),
                        'percentage': round(percentage, 1)
                    })

                # Cache the full first page
                if cache_key and after_value is None and result:
                    full_first_page = result[:100]  # Cache up to 100 items
                    await self._set_cached_leaderboard(cache_key, full_first_page)

                return result

        except asyncpg.exceptions.PostgresConnectionError as e:
            raise DatabaseConnectionError(
                "Database connection failed while fetching server emoji leaderboard",
                context={'guild_id': guild_id},
                original=e
            )
        except DatabaseError:
            raise
        except Exception as e:
            raise DatabaseQueryError(
                "Unexpected error fetching server emoji leaderboard",
                context={'guild_id': guild_id},
                original=e
            )

