async def get_current_user(
    session_id: Optional[str] = Cookie(None, alias="session")
) -> Optional[Dict]:
    """Get current authenticated user from session cookie"""
    if not session_id:
        return None

    try:
        session = await auth_db.get_session(session_id)
        if not session:
            return None

        user = await auth_db.get_user_by_discord_id(session['discord_id'])
        return user
    except DatabaseError as e:
        logger.error(f"Database error in get_current_user: {e}")
        return None
    
ADMIN_DISCORD_IDS = {"591655972414685229", "1428927519515611141"}

async def require_admin(user: Optional[Dict] = Depends(get_current_user)) -> Dict:
    if not user or str(user.get("discord_id")) not in ADMIN_DISCORD_IDS:
        raise HTTPException(status_code=403, detail="Admin access required")
    return user

# ============================================
# LIFESPAN MANAGER
# ============================================


@asynccontextmanager
async def lifespan(app: FastAPI):
    """Manage application lifecycle"""
    try:
        logger.info(
            f"Connecting to DB: {DB_HOST}:{DB_PORT}/{DB_NAME} as {DB_USER}")
        await auth_db.initialize()
        logger.info("auth_db initialized successfully")
        await db_stats.initialize()
        logger.info("db_stats initialized successfully")
    except DatabaseError as e:
        logger.error(f"Failed to initialize databases: {e}")
        raise
    except Exception as e:
        logger.error(f"Unexpected error during startup: {e}")
        raise
    yield
    await auth_db.close()
    await db_stats.close()
    await discord_api.close()


