# ============================================
# HELPER FUNCTIONS
# ============================================


def format_duration(total_seconds):
    """Format duration in seconds to human readable format"""
    if total_seconds == 0:
        return "0s"

    days = total_seconds // (3600 * 24)
    hours = (total_seconds % (3600 * 24)) // 3600
    minutes = (total_seconds % 3600) // 60
    seconds = total_seconds % 60

    if days > 0:
        return f"{days}d {hours}h"
    elif hours > 0:
        return f"{hours}h {minutes}m"
    elif minutes > 0:
        return f"{minutes}m {seconds}s"
    else:
        return f"{int(seconds)}s"


def format_streak(streak_days):
    """Format streak days to human readable format"""
    if streak_days >= 365:
        years = streak_days // 365
        days = streak_days % 365
        if days > 0:
            return f"{years}y {days}d"
        return f"{years}y"
    return f"{streak_days}d"


@app.get("/api/user/timezone")
async def get_user_timezone(
    user: Optional[Dict] = Depends(get_current_user),
    guild_id: Optional[str] = Query(
        None, description="Optional guild ID for public access")
):
    """Get the user's selected timezone from settings, or default for public access"""

    # If authenticated, get their server's timezone
    if user:
        try:
            selected_server = user.get('selected_server')
            if selected_server:
                settings = await db_stats.get_guild_settings(selected_server)
                return {"timezone": settings.get('timezone', 'UTC')}
        except Exception as e:
            logger.error(f"Error fetching user timezone: {e}")

    # If not authenticated but guild_id provided for StatsHQ
    if guild_id == STATSHQ_GUILD_ID:
        try:
            settings = await db_stats.get_guild_settings(guild_id)
            return {"timezone": settings.get('timezone', 'UTC'), "public": True}
        except Exception as e:
            logger.error(f"Error fetching public timezone: {e}")

    # Default fallback
    return {"timezone": "UTC"}

