@app.get("/api/server/top/users/messages")
async def server_top_users_messages(
    guild_id: str,
    limit: int = 100000000000,
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated list of role IDs"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get server's top users by messages with bot filter, blacklist, and role filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        try:
            guild_id_int = int(guild_id)
        except ValueError as e:
            raise ValidationError(
                "Invalid guild_id format",
                context={'guild_id': guild_id, 'error': str(e)},
                original=e
            )

        # Parse role_filter_ids if provided
        role_filter_list = None
        if role_filter_ids:
            role_filter_list = [rid.strip()
                                for rid in role_filter_ids.split(',') if rid.strip()]

        async with db_stats.pool.acquire() as conn:
            # Get blacklisted users first
            try:
                blacklists = await db_stats._get_cached_blacklists(guild_id_int)
                blacklisted_user_ids = set(blacklists['users'])
            except DatabaseQueryError as e:
                logger.warning(f"Failed to get blacklists: {e}")
                blacklisted_user_ids = set()

            # Get users with roles if filtering
            allowed_user_ids = None
            if role_filter_list:
                try:
                    allowed_user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                    if not allowed_user_ids:
                        return {'data': [], 'has_more': False}
                    allowed_user_ids = set(allowed_user_ids)
                except DatabaseQueryError as e:
                    logger.error(f"Failed to get users with roles: {e}")
                    raise DatabaseQueryError(
                        "Role filtering failed",
                        context={'guild_id': guild_id,
                                 'role_filter_ids': role_filter_list},
                        original=e
                    )

            # First get total messages for percentage calculation
            total_query = """
                SELECT COALESCE(SUM(message_count), 0) as total_messages
                FROM message_tracking_hourly
                WHERE guild_id = $1
            """
            total_params = [guild_id_int]

            # Apply bot filter to total_query
            total_query, total_params = await db_stats._apply_bot_filter(
                total_query, total_params, guild_id, 'message_tracking_hourly'
            )

            # Apply role filtering to total_query
            if allowed_user_ids:
                placeholders = [
                    f"${len(total_params) + i + 1}" for i in range(len(allowed_user_ids))]
                total_query += f" AND user_id IN ({', '.join(placeholders)})"
                total_params.extend(allowed_user_ids)

            # Apply time filters to total_query
            if start_time:
                total_params.append(start_time)
                total_query += f" AND hour >= ${len(total_params)}"
            if end_time:
                total_params.append(end_time)
                total_query += f" AND hour <= ${len(total_params)}"

            # Apply blacklist to total_query
            if blacklisted_user_ids:
                placeholders = [
                    f"${len(total_params) + i + 1}" for i in range(len(blacklisted_user_ids))]
                total_query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                total_params.extend(blacklisted_user_ids)

            try:
                total_row = await conn.fetchrow(total_query, *total_params)
            except asyncpg.PostgresError as e:
                if "timeout" in str(e).lower():
                    raise DatabaseTimeoutError(
                        "Database operation timed out while fetching total messages",
                        context={'guild_id': guild_id},
                        original=e
                    )
                else:
                    raise DatabaseQueryError(
                        "Failed to fetch total messages",
                        context={'guild_id': guild_id},
                        original=e
                    )

            total_messages = total_row['total_messages'] if total_row else 0

            if total_messages == 0:
                return {'data': [], 'has_more': False}

            # Get user breakdown
            query = """
                SELECT 
                    user_id,
                    SUM(message_count) as message_count,
                    COALESCE(SUM(total_chars), 0) as total_chars,
                    COALESCE(SUM(total_chars) / NULLIF(SUM(message_count), 0), 0) as avg_chars
                FROM message_tracking_hourly
                WHERE guild_id = $1
            """
            params = [guild_id_int]

            # Apply bot filter to main query
            query, params = await db_stats._apply_bot_filter(
                query, params, guild_id, 'message_tracking_hourly'
            )

            # Apply role filtering to main query
            if allowed_user_ids:
                placeholders = [
                    f"${len(params) + i + 1}" for i in range(len(allowed_user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(allowed_user_ids)

            # Apply time filters to main query
            if start_time:
                params.append(start_time)
                query += f" AND hour >= ${len(params)}"
            if end_time:
                params.append(end_time)
                query += f" AND hour <= ${len(params)}"

            # Apply blacklist to main query
            if blacklisted_user_ids:
                placeholders = [
                    f"${len(params) + i + 1}" for i in range(len(blacklisted_user_ids))]
                query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                params.extend(blacklisted_user_ids)

            query += """
                GROUP BY user_id
                ORDER BY message_count DESC
            """

            # Add LIMIT
            query += f" LIMIT ${len(params) + 1}"
            params.append(limit)

            try:
                rows = await conn.fetch(query, *params)
            except asyncpg.PostgresError as e:
                if "timeout" in str(e).lower():
                    raise DatabaseTimeoutError(
                        "Database operation timed out while fetching top users",
                        context={'guild_id': guild_id},
                        original=e
                    )
                else:
                    raise DatabaseQueryError(
                        "Failed to fetch top users",
                        context={'guild_id': guild_id},
                        original=e
                    )

            result = []
            for row in rows:
                user_messages = row['message_count'] or 0
                percentage = (user_messages / total_messages *
                              100) if total_messages > 0 else 0
                result.append({
                    'user_id': str(row['user_id']),
                    'message_count': user_messages,
                    'total_chars': row['total_chars'] or 0,
                    'avg_chars': round(row['avg_chars'] or 0, 2),
                    'percentage': round(percentage, 1)
                })

            return {
                'data': result,
                'has_more': len(result) == limit
            }

    except ValidationError as e:
        logger.warning(f"Validation error in server_top_users_messages: {e}")
        raise HTTPException(status_code=400, detail=str(e))
    except DatabaseConnectionError as e:
        logger.error(
            f"Database connection error in server_top_users_messages: {e}")
        raise HTTPException(
            status_code=503, detail="Database connection failed")
    except DatabaseTimeoutError as e:
        logger.error(f"Database timeout in server_top_users_messages: {e}")
        raise HTTPException(
            status_code=504, detail="Database operation timed out")
    except DatabaseQueryError as e:
        logger.error(f"Database query error in server_top_users_messages: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch data")
    except Exception as e:
        logger.error(
            f"Unexpected error in server_top_users_messages: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail="Internal server error")


@app.get("/api/server/top/users/voice")
async def server_top_users_voice(
    guild_id: str,
    limit: int = 100000000000,
    role_filter_ids: Optional[str] = Query(None),
    start_time: Optional[str] = Query(None),  # Accept string
    end_time: Optional[str] = Query(None),    # Accept string
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get server's top users by voice with time filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Convert string dates to datetime
        start_time_dt = None
        end_time_dt = None

        if start_time:
            start_time_dt = datetime.fromisoformat(
                start_time.replace('Z', '+00:00'))
        if end_time:
            end_time_dt = datetime.fromisoformat(
                end_time.replace('Z', '+00:00'))

        role_filter_list = role_filter_ids.split(
            ',') if role_filter_ids else None

        result = await db_stats.q_server_top_users_voice(
            guild_id=guild_id,
            role_filter_ids=role_filter_list,
            start_time=start_time_dt,
            end_time=end_time_dt,
            limit=limit
        )

        # Filter out deleted users
        if result:
            user_ids = [str(item['user_id']) for item in result]
            existence_map = await discord_api.verify_entities_exist(guild_id, 'user', user_ids)
            result = [item for item in result if existence_map.get(
                str(item['user_id']), True)]

        return result

    except Exception as e:
        logger.error(f"Error in server_top_users_voice: {e}")
        logger.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=str(e))


