@app.post("/api/emoji/user/top/channels")
async def emoji_user_top_channels(request: EmojiUserRequest):
    """
    Get user's top channels by emoji usage.
    Can filter by usage_type: 'all', 'message', or 'reaction'
    Can filter by category_id
    """
    try:
        # Validate IDs
        try:
            guild_id_int = int(request.guild_id)
            user_id_int = int(request.user_id)
        except ValueError as e:
            raise HTTPException(
                status_code=400, detail=f"Invalid ID format: {e}")

        # Apply usage_type filter if specified
        usage_type = None
        if request.usage_type and request.usage_type != 'all':
            usage_type = request.usage_type

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering if needed
            if request.role_filter_ids:
                user_ids = await db_stats._get_users_with_roles(request.guild_id, request.role_filter_ids)
                if not user_ids or user_id_int not in user_ids:
                    return []

            query = """
                SELECT 
                    channel_id,
                    SUM(usage_count) as total_usage,
                    SUM(CASE WHEN usage_type = 'message' THEN usage_count ELSE 0 END) as message_usage,
                    SUM(CASE WHEN usage_type = 'reaction' THEN usage_count ELSE 0 END) as reaction_usage,
                    COUNT(DISTINCT emoji_str) as unique_emojis
                FROM emoji_usage_hourly
                WHERE guild_id = $1 AND user_id = $2
            """
            params = [int(request.guild_id), int(request.user_id)]
            param_index = 3

            # Apply category filter if specified
            if request.category_id:
                params.append(int(request.category_id))
                query += f" AND category_id = ${len(params)}"

            # Apply usage_type filter
            if usage_type:
                params.append(usage_type)
                query += f" AND usage_type = ${len(params)}"

            # Apply time filters
            if request.start_time:
                params.append(request.start_time)
                query += f" AND hour >= ${len(params)}"
            if request.end_time:
                params.append(request.end_time)
                query += f" AND hour <= ${len(params)}"

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(
                query, params, request.guild_id, 'emoji_usage_hourly'
            )

            query += """
                GROUP BY channel_id
                HAVING SUM(usage_count) > 0
                ORDER BY total_usage DESC
                LIMIT $"""
            query += str(len(params) + 1)
            params.append(request.limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                result.append({
                    'channel_id': str(row['channel_id']),
                    'total_usage': row['total_usage'] or 0,
                    'message_usage': row['message_usage'] or 0,
                    'reaction_usage': row['reaction_usage'] or 0,
                    'unique_emojis': row['unique_emojis'] or 0
                })

            # Filter out deleted channels
            if result:
                channel_ids = [item['channel_id'] for item in result]
                existence_map = await discord_api.verify_entities_exist(
                    request.guild_id, 'channel', channel_ids
                )

                filtered_result = []
                for item in result:
                    if existence_map.get(item['channel_id'], True):
                        filtered_result.append(item)

                result = filtered_result

            return result

    except ValueError as e:
        logger.error(f"Invalid ID format in emoji_user_top_channels: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except DatabaseError as e:
        logger.error(f"Database error in emoji_user_top_channels: {e}")
        raise HTTPException(status_code=500, detail=str(e))
    except Exception as e:
        logger.error(f"Unexpected error in emoji_user_top_channels: {e}")
        raise HTTPException(status_code=500, detail=str(e))


