# ============================================
# SERVER MESSAGE HOURLY DISTRIBUTION ENDPOINT
# ============================================


@app.post("/api/server/activity-distribution/messages")
async def server_activity_distribution_messages(request: ActivityDistributionRequest):
    """Get server's message distribution by hour with role filtering"""
    try:
        guild_id_int = int(request.guild_id)

        user_ids = None
        if request.role_filter_ids:
            user_ids = await db_stats._get_users_with_roles(request.guild_id, request.role_filter_ids)
            if not user_ids:
                messages = {f'hour_{i}': 0 for i in range(24)}
                return {'messages': messages, 'total_messages': 0}

        async with db_stats.pool.acquire() as conn:
            messages = {f'hour_{i}': 0 for i in range(24)}
            total_messages = 0

            if request.days_back == 0:
                query = f"""
                    SELECT 
                        EXTRACT(HOUR FROM hour AT TIME ZONE 'UTC' AT TIME ZONE '{request.timezone_str}') as hour_of_day,
                        COALESCE(SUM(message_count), 0) as message_count
                    FROM message_tracking_hourly
                    WHERE guild_id = $1
                """
                params = [guild_id_int]
            else:
                query = f"""
                    SELECT 
                        EXTRACT(HOUR FROM hour AT TIME ZONE 'UTC' AT TIME ZONE '{request.timezone_str}') as hour_of_day,
                        COALESCE(SUM(message_count), 0) as message_count
                    FROM message_tracking_hourly
                    WHERE guild_id = $1
                    AND hour >= NOW() - INTERVAL '{request.days_back} days'
                """
                params = [guild_id_int]

            param_index = 2

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_index += len(user_ids)

            query, params = await db_stats._apply_bot_filter(query, params, request.guild_id, 'message_tracking_hourly')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                request.guild_id, query, params, 'message_tracking_hourly',
                include_users=True, include_channels=True
            )

            query += " GROUP BY hour_of_day ORDER BY hour_of_day"

            rows = await conn.fetch(query, *params)

            for row in rows:
                hour = int(row['hour_of_day'])
                count = row['message_count'] or 0
                messages[f'hour_{hour}'] = count
                total_messages += count

            return {
                'messages': messages,
                'total_messages': total_messages
            }

    except Exception as e:
        logger.error(f"Error in server_activity_distribution_messages: {e}")
        return {'messages': {f'hour_{i}': 0 for i in range(24)}, 'total_messages': 0}


