@app.get("/api/user/profile-picture/{user_id}")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def get_user_profile_picture(
    user_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Get a user's Discord profile picture URL.
    Now works for both authenticated and unauthenticated requests.
    """
    try:
        # Validate user_id format
        try:
            user_id_int = int(user_id)
        except ValueError:
            return JSONResponse(
                status_code=400,
                content={
                    "success": False,
                    "error": "Invalid user ID format"
                }
            )

        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
            url = f"{DISCORD_API_BASE}/users/{user_id}"

            # ✅ ADD TIMEOUT HERE (5 seconds)
            async with session.get(url, headers=headers, timeout=5) as resp:
                if resp.status == 200:
                    user_data = await resp.json()

                    avatar_hash = user_data.get('avatar')
                    if avatar_hash:
                        extension = 'gif' if avatar_hash.startswith(
                            'a_') else 'png'
                        avatar_url = f"https://cdn.discordapp.com/avatars/{user_id}/{avatar_hash}.{extension}?size=256"
                    else:
                        try:
                            discriminator = int(
                                user_data.get('discriminator', '0'))
                            default_avatar_num = discriminator % 5
                        except (ValueError, TypeError):
                            default_avatar_num = 0
                        avatar_url = f"https://cdn.discordapp.com/embed/avatars/{default_avatar_num}.png"

                    return {
                        "success": True,
                        "user_id": user_id,
                        "username": user_data.get('username'),
                        "global_name": user_data.get('global_name'),
                        "avatar_url": avatar_url,
                        "avatar_hash": avatar_hash
                    }
                elif resp.status == 404:
                    return JSONResponse(
                        status_code=404,
                        content={
                            "success": False,
                            "error": "User not found"
                        }
                    )
                else:
                    error_text = await resp.text()
                    return JSONResponse(
                        status_code=resp.status,
                        content={
                            "success": False,
                            "error": f"Discord API error: {resp.status}"
                        }
                    )

    except asyncio.TimeoutError:
        return JSONResponse(
            status_code=504,
            content={
                "success": False,
                "error": "Discord API timeout"
            }
        )
    except aiohttp.ClientTimeout:
        return JSONResponse(
            status_code=504,
            content={
                "success": False,
                "error": "Discord API timeout"
            }
        )
    except Exception as e:
        logger.error(f"Error fetching user profile picture: {e}")
        return JSONResponse(
            status_code=500,
            content={
                "success": False,
                "error": "Internal server error"
            }
        )


@app.get("/api/user/profile-picture/batch")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def get_batch_user_profile_pictures(
    user_ids: str = Query(...,
                          description="Comma-separated list of user IDs, max 50"),
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Get profile pictures for multiple users at once using BATCH requests.
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        user_id_list = [uid.strip()
                        for uid in user_ids.split(',') if uid.strip()]

        if len(user_id_list) > 50:
            return JSONResponse(
                status_code=400,
                content={
                    "success": False,
                    "error": "Maximum 50 user IDs allowed per request"
                }
            )

        results = {}

        # BATCH FIX: Use asyncio.gather for concurrent requests with timeouts
        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

            async def fetch_user(user_id: str):
                try:
                    url = f"{DISCORD_API_BASE}/users/{user_id}"
                    # ✅ ADD TIMEOUT HERE (5 seconds per user)
                    async with session.get(url, headers=headers, timeout=5) as resp:
                        if resp.status == 200:
                            user_data = await resp.json()
                            avatar_hash = user_data.get('avatar')
                            if avatar_hash:
                                extension = 'gif' if avatar_hash.startswith(
                                    'a_') else 'png'
                                avatar_url = f"https://cdn.discordapp.com/avatars/{user_id}/{avatar_hash}.{extension}?size=128"
                            else:
                                try:
                                    discriminator = int(
                                        user_data.get('discriminator', '0'))
                                    default_avatar_num = discriminator % 5
                                except (ValueError, TypeError):
                                    default_avatar_num = 0
                                avatar_url = f"https://cdn.discordapp.com/embed/avatars/{default_avatar_num}.png"

                            return user_id, {
                                "success": True,
                                "username": user_data.get('username'),
                                "global_name": user_data.get('global_name'),
                                "avatar_url": avatar_url
                            }
                        elif resp.status == 404:
                            return user_id, {"success": False, "error": "User not found"}
                        else:
                            return user_id, {"success": False, "error": f"Discord API error: {resp.status}"}
                except asyncio.TimeoutError:
                    return user_id, {"success": False, "error": "Request timeout"}
                except Exception as e:
                    return user_id, {"success": False, "error": str(e)}

            # Execute all requests concurrently
            tasks = [fetch_user(uid) for uid in user_id_list]
            batch_results = await asyncio.gather(*tasks)

            # Collect results
            for user_id, result in batch_results:
                results[user_id] = result

        return {
            "success": True,
            "results": results
        }

    except Exception as e:
        logger.error(f"Error in batch profile picture fetch: {e}")
        return JSONResponse(
            status_code=500,
            content={
                "success": False,
                "error": "Internal server error"
            }
        )


