@app.get("/api/debug/test-fernet")
async def test_fernet(user: Optional[Dict] = Depends(get_current_user)):
    """Test if Fernet encryption/decryption is working correctly"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        test_string = "test_user_123"

        # Encrypt
        encrypted = db_stats.fernet.encrypt(test_string.encode())
        encrypted_str = encrypted.decode()

        # Decrypt
        decrypted = db_stats.fernet.decrypt(encrypted_str.encode())
        decrypted_str = decrypted.decode()

        # Also try to decrypt a real record from the database
        sample_username = None
        async with db_stats.pool.acquire() as conn:
            row = await conn.fetchrow("""
                SELECT encrypted_username 
                FROM message_tracking_hourly 
                WHERE encrypted_username IS NOT NULL 
                LIMIT 1
            """)
            if row:
                sample_username = row['encrypted_username']
                test_decrypt = db_stats.decrypt_username(sample_username)

        return {
            "success": True,
            "fernet_exists": db_stats.fernet is not None,
            "test_encrypted": encrypted_str,
            "test_decrypted": decrypted_str,
            "test_passed": test_string == decrypted_str,
            "sample_encrypted_exists": sample_username is not None,
            "sample_decrypted": test_decrypt if sample_username else None
        }
    except Exception as e:
        return {
            "success": False,
            "error": str(e),
            "error_type": type(e).__name__
        }


