@app.post("/api/public/username/batch/{table_name}")
async def public_batch_get_username_from_table(
    table_name: str,
    request: Request
):
    """
    Public endpoint - Batch get decrypted usernames from a specific table.
    Only works for public StatsHQ guild.

    Valid table names: messages, voice, emojis, mentions, invites, activity, 
                       member_joins, member_leaves, role_growth

    Request body:
    {
        "guild_id": 1424021358680998022,
        "user_ids": [123, 456, 789]
    }
    """
    valid_tables = ['messages', 'voice', 'emojis', 'mentions', 'invites',
                    'activity', 'member_joins', 'member_leaves', 'role_growth']

    if table_name not in valid_tables:
        raise HTTPException(
            status_code=400, detail=f"Invalid table name. Must be one of: {', '.join(valid_tables)}")

    try:
        body = await request.json()
        guild_id = body.get('guild_id')
        user_ids = body.get('user_ids', [])

        if not guild_id or not user_ids:
            raise HTTPException(
                status_code=400, detail="guild_id and user_ids are required")

        # Only allow StatsHQ guild for public access
        if str(guild_id) != STATSHQ_GUILD_ID:
            raise HTTPException(
                status_code=403, detail="Access denied. This endpoint is only for public StatsHQ statistics.")

        # Convert to integers if they're strings
        user_ids_int = [int(uid) if isinstance(uid, str)
                        else uid for uid in user_ids]

        results = await db_stats.batch_get_decrypted_usernames_any_table(guild_id, user_ids_int, table_name)

        return {
            "success": True,
            "source": table_name,
            "guild_id": guild_id,
            "results": {str(k): v for k, v in results.items()},
            "public": True
        }
    except Exception as e:
        logger.error(f"Error in public batch username from {table_name}: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ============================================
# USERNAME DISCOVERY ENDPOINT
# ============================================

@app.get("/api/username/discover-tables/{guild_id}/{user_id}")
async def discover_username_tables(
    guild_id: int,
    user_id: int,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Discover which tables contain username data for a user.
    Returns a list of tables where the user's username was found.
    Requires authentication.
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    tables_to_check = [
        ('messages', 'get_decrypted_username_from_messages'),
        ('voice', 'get_decrypted_username_from_voice'),
        ('emojis', 'get_decrypted_username_from_emojis'),
        ('mentions', 'get_decrypted_username_from_mentions'),
        ('invites', 'get_decrypted_username_from_invites'),
        ('activity', 'get_decrypted_username_from_activity'),
        ('member_joins', 'get_decrypted_username_from_member_joins'),
        ('member_leaves', 'get_decrypted_username_from_member_leaves'),
        ('role_growth', 'get_decrypted_username_from_role_growth'),
        ('slash_commands', 'get_decrypted_username_from_slash_commands')
    ]

    results = {}
    username_found = None

    for table_name, method_name in tables_to_check:
        try:
            method = getattr(db_stats, method_name)
            username = await method(guild_id, user_id)
            results[table_name] = {
                "found": username is not None,
                "username": username if username else None
            }
            if username and not username_found:
                username_found = username
        except Exception as e:
            results[table_name] = {
                "found": False,
                "error": str(e)
            }

    return {
        "success": True,
        "user_id": user_id,
        "primary_username": username_found or f"User {user_id}",
        "table_breakdown": results
    }


@app.get("/api/user/top/categories/voice")
async def user_top_categories_voice(
    guild_id: str,
    user_id: str,
    limit: int = 100000000000,
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated list of role IDs"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get user's top categories by voice with time filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        guild_id_int = int(guild_id)
        user_id_int = int(user_id)

        # Parse role_filter_ids if provided
        role_filter_list = None
        if role_filter_ids:
            role_filter_list = [rid.strip()
                                for rid in role_filter_ids.split(',') if rid.strip()]

        async with db_stats.pool.acquire() as conn:
            # Build query
            query = """
                SELECT 
                    category_id,
                    SUM(total_seconds) as total_seconds,
                    SUM(session_count) as session_count,
                    COUNT(DISTINCT channel_id) as unique_channels
                FROM voice_session_history_hourly
                WHERE guild_id = $1 
                AND user_id = $2
                AND category_id IS NOT NULL
                AND category_id != 0
            """
            params = [guild_id_int, user_id_int]

            # Add time filters
            if start_time:
                params.append(start_time)
                query += f" AND hour >= ${len(params)}"
            if end_time:
                params.append(end_time)
                query += f" AND hour <= ${len(params)}"

            query += """
                GROUP BY category_id
                ORDER BY total_seconds DESC
            """

            # Add LIMIT
            query += f" LIMIT ${len(params) + 1}"
            params.append(limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                result.append({
                    'category_id': str(row['category_id']),
                    'total_seconds': row['total_seconds'],
                    'total_hours': round(row['total_seconds'] / 3600, 2),
                    'session_count': row['session_count'],
                    'unique_channels': row['unique_channels']
                })

            # Filter out deleted categories
            if result:
                category_ids = [item['category_id'] for item in result]
                existence_map = await discord_api.verify_entities_exist(
                    guild_id, 'category', category_ids
                )

                filtered_result = []
                for item in result:
                    if existence_map.get(item['category_id'], True):
                        filtered_result.append(item)

                result = filtered_result

            return result

    except Exception as e:
        logger.error(f"Error in user_top_categories_voice: {e}")
        logger.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=str(e))


