@app.get("/api/server/real-users")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def get_server_real_users(
    guild_id: str,
    limit: int = Query(100, ge=1, le=100000000000),
    role_filter_ids: Optional[List[str]] = Query(
        None, description="Comma-separated list of role IDs to filter by"),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get real users from Discord API with blacklist filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Validate guild_id
        try:
            guild_id_int = int(guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400, detail=f"Invalid guild_id format: {guild_id}")

        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(guild_id_int)
        blacklisted_user_ids = set(int(uid)
                                   for uid in blacklists.get('users', []))

        # Parse role_filter_ids if provided
        role_filter_list = None
        if role_filter_ids:
            role_filter_list = [rid.strip()
                                for rid in role_filter_ids.split(',') if rid.strip()]

        # First get top users by messages from database, with role filtering
        top_users = await db_stats.q_server_top_users_messages(
            guild_id=guild_id,
            role_filter_ids=role_filter_list,
            limit=limit
        )

        if not top_users:
            return []

        # Extract user IDs and filter out blacklisted users
        user_ids = []
        for u in top_users:
            uid = str(u['user_id'])
            if int(u['user_id']) not in blacklisted_user_ids:
                user_ids.append(uid)

        # Filter out deleted users
        existence_map = await discord_api.verify_entities_exist(guild_id, 'user', user_ids)

        # Keep only existing users
        valid_user_ids = [
            uid for uid in user_ids if existence_map.get(uid, True)]

        # Fetch profile pictures and usernames from Discord for valid users
        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

            user_list = []
            for user_id in valid_user_ids[:limit]:
                try:
                    url = f"{DISCORD_API_BASE}/users/{user_id}"
                    async with session.get(url, headers=headers) as resp:
                        if resp.status == 200:
                            user_data = await resp.json()

                            # Get avatar URL
                            avatar_hash = user_data.get('avatar')
                            if avatar_hash:
                                extension = 'gif' if avatar_hash.startswith(
                                    'a_') else 'png'
                                avatar_url = f"https://cdn.discordapp.com/avatars/{user_id}/{avatar_hash}.{extension}?size=128"
                            else:
                                default_avatar = int(
                                    user_data.get('discriminator', '0')) % 5
                                avatar_url = f"https://cdn.discordapp.com/embed/avatars/{default_avatar}.png"

                            user_list.append({
                                "id": user_id,
                                "username": user_data.get('username', 'Unknown'),
                                "global_name": user_data.get('global_name'),
                                "display_name": user_data.get('global_name') or user_data.get('username', 'Unknown'),
                                "avatar": avatar_url,
                                "discriminator": user_data.get('discriminator', '0')
                            })
                except Exception as e:
                    logger.error(f"Error fetching user {user_id}: {e}")
                    continue

            return user_list

    except ValueError as e:
        logger.error(f"Invalid ID format in get_server_real_users: {e}")
        raise HTTPException(status_code=400, detail="Invalid ID format")
    except Exception as e:
        logger.error(f"Error in get_server_real_users: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/server/real-channels")
async def get_server_real_channels(
    guild_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get real channels with blacklist filtering - works for authenticated users or public StatsHQ"""

    try:
        try:
            guild_id_int = int(guild_id)
        except ValueError as e:
            raise ValidationError(
                "Invalid guild_id format",
                context={'guild_id': guild_id, 'error': str(e)},
                original=e
            )

        # Check if this is a public request (unauthenticated + StatsHQ guild)
        is_public_request = not user and guild_id == STATSHQ_GUILD_ID

        # For non-public guilds, require authentication
        if not is_public_request and not user:
            raise HTTPException(
                status_code=401,
                detail="Authentication required for non-public guilds"
            )

        # Get channels from database cache
        channels = await db_stats.get_all_channels_for_guild(guild_id_int)

        # Get blacklisted channels for this guild (skip for public? or include?)
        blacklists = await db_stats._get_cached_blacklists(guild_id_int)
        blacklisted_channel_ids = set(blacklists['channels'])

        # Format response - filter out blacklisted channels
        result = []
        for ch in channels:
            channel_id_str = str(ch['channel_id'])

            # Skip blacklisted channels
            if channel_id_str in blacklisted_channel_ids:

                continue

            if ch['channel_type'] != 'category':  # Only return actual channels, not categories
                result.append({
                    "id": channel_id_str,
                    "name": ch['channel_name'],
                    "type": ch['channel_type'],
                    "category_id": str(ch['category_id']) if ch.get('category_id') else None,
                })

        return result

    except ValidationError as e:
        logger.warning(f"Validation error in get_server_real_channels: {e}")
        raise HTTPException(status_code=400, detail=str(e))
    except DatabaseConnectionError as e:
        logger.error(
            f"Database connection error in get_server_real_channels: {e}")
        raise HTTPException(
            status_code=503, detail="Database connection failed")
    except DatabaseQueryError as e:
        logger.error(f"Database query error in get_server_real_channels: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch channels")
    except Exception as e:
        logger.error(
            f"Unexpected error in get_server_real_channels: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail="Internal server error")


