@app.get("/api/server/real-roles")
async def get_server_real_roles(
    guild_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Get real roles from current_role_members table with role_name and role_color.
    No blacklist filtering needed for roles display - returns all roles.
    Works for authenticated users only.
    """
    # Helper function to format role color
    def format_role_color(color):
        """Convert role color to hex string format"""
        if not color:
            return "#99aab5"  # Default Discord gray
        if isinstance(color, int):
            return f"#{color:06x}"
        if isinstance(color, str):
            return color if color.startswith('#') else f"#{color}"
        return "#99aab5"

    try:
        # Validate guild_id
        try:
            guild_id_int = int(guild_id)
        except ValueError as e:
            raise ValidationError(
                "Invalid guild_id format",
                context={'guild_id': guild_id, 'error': str(e)},
                original=e
            )

        # Check if this is a public request (unauthenticated + StatsHQ guild)
        is_public_request = not user and guild_id == STATSHQ_GUILD_ID

        # For non-public guilds, require authentication
        if not is_public_request and not user:
            raise HTTPException(
                status_code=401,
                detail="Authentication required for non-public guilds"
            )

        # Get roles from current_role_members table with name and color
        try:
            async with db_stats.pool.acquire() as conn:
                # First, check if we have roles with names in the table
                role_rows = await conn.fetch("""
                    SELECT DISTINCT 
                        role_id, 
                        role_name, 
                        role_color,
                        MAX(updated_at) as last_updated
                    FROM current_role_members
                    WHERE guild_id = $1
                    AND role_id IS NOT NULL
                    GROUP BY role_id, role_name, role_color
                    ORDER BY role_id
                """, guild_id_int)

                if not role_rows:
                    # No roles found in table - return empty list
                    logger.warning(
                        f"No roles found in current_role_members for guild {guild_id}")
                    return []

                # Format the response
                roles = []
                for row in role_rows:
                    role_id = str(row['role_id'])
                    role_name = row.get('role_name')
                    role_color = row.get('role_color')

                    # Handle default values if name/color are missing
                    if not role_name:
                        role_name = f"Role {role_id}"

                    # Format color safely
                    role_color = format_role_color(role_color)

                    roles.append({
                        "id": role_id,
                        "name": role_name,
                        "color": role_color,
                        "position": 0,  # We don't store position, can be added later
                        "hoist": False,  # Default values - can be added to table later
                        "mentionable": False  # Default values - can be added to table later
                    })

                # Sort roles by role_id (or you could add a position column later)
                roles.sort(key=lambda x: x['id'])

                return roles

        except asyncpg.PostgresError as e:
            raise DatabaseQueryError(
                "Failed to fetch roles from current_role_members",
                context={'guild_id': guild_id},
                original=e
            )

    except ValidationError as e:
        logger.warning(f"Validation error in get_server_real_roles: {e}")
        raise HTTPException(status_code=400, detail=str(e))
    except DatabaseConnectionError as e:
        logger.error(
            f"Database connection error in get_server_real_roles: {e}")
        raise HTTPException(
            status_code=503, detail="Database connection failed")
    except DatabaseQueryError as e:
        logger.error(f"Database query error in get_server_real_roles: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch roles")
    except Exception as e:
        logger.error(
            f"Unexpected error in get_server_real_roles: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail="Internal server error")

