@app.post("/api/invite/timeseries")
async def invite_timeseries(request: InviteTimeseriesRequest):
    """
    Get invite timeseries data aggregated by day/week/month with timezone support.
    Can filter by time period, role, and invite type.
    """
    try:
        guild_id_int = int(request.guild_id)

        filter_value = str(request.filter_type).lower(
        ) if request.filter_type else "all"
        if filter_value not in ["all", "valid", "suspicious", "left"]:
            filter_value = "all"

        # Get timezone from request or default to UTC
        timezone_str = getattr(request, 'timezone_str', 'UTC')

        async with db_stats.pool.acquire() as conn:
            # Determine date truncation with timezone support
            if request.interval == "day":
                # Convert created_at to server timezone, then truncate to date
                date_trunc = f"DATE(created_at AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}')"
            elif request.interval == "week":
                date_trunc = f"DATE_TRUNC('week', created_at AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}')::DATE"
            elif request.interval == "month":
                date_trunc = f"DATE_TRUNC('month', created_at AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}')::DATE"
            else:
                date_trunc = f"DATE(created_at AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}')"

            query = f"""
                SELECT
                    {date_trunc} as date_col,
                    COUNT(*) as total_invites,
                    COUNT(*) FILTER (WHERE invite_type = 'valid') as valid_invites,
                    COUNT(*) FILTER (WHERE invite_type = 'suspicious') as suspicious_invites,
                    COUNT(*) FILTER (WHERE invite_type = 'left') as left_invites,
                    COUNT(DISTINCT inviter_id) as unique_inviters,
                    COUNT(DISTINCT invitee_id) as unique_invitees
                FROM invite_tracking
                WHERE guild_id = $1
            """
            params = [guild_id_int]
            param_index = 2

            if filter_value != "all":
                query += f" AND invite_type = ${param_index}"
                params.append(filter_value)
                param_index += 1

            if request.role_filter_ids and len(request.role_filter_ids) > 0:
                user_ids = await db_stats._get_users_with_roles(request.guild_id, request.role_filter_ids)
                if user_ids and len(user_ids) > 0:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(user_ids))]
                    query += f" AND inviter_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                    param_index += len(user_ids)
                else:
                    return []

            if request.start_time and request.end_time:
                query += f" AND created_at >= ${param_index} AND created_at <= ${param_index + 1}"
                params.append(request.start_time)
                params.append(request.end_time)
                param_index += 2
            elif request.start_time:
                query += f" AND created_at >= ${param_index}"
                params.append(request.start_time)
                param_index += 1
            elif request.end_time:
                query += f" AND created_at <= ${param_index}"
                params.append(request.end_time)
                param_index += 1
            elif request.days:
                query += f" AND created_at >= NOW() - INTERVAL '1 day' * ${param_index}"
                params.append(request.days)
                param_index += 1

            query, params = await db_stats._apply_bot_filter(query, params, request.guild_id, 'invite_tracking')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                request.guild_id, query, params, 'invite_tracking',
                include_users=True, include_channels=False
            )

            query += f" GROUP BY date_col ORDER BY date_col ASC"

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                date_value = row['date_col']
                result.append({
                    "date": date_value.isoformat() if isinstance(date_value, (datetime, date)) else str(date_value),
                    "total_invites": row['total_invites'] or 0,
                    "valid_invites": row['valid_invites'] or 0,
                    "suspicious_invites": row['suspicious_invites'] or 0,
                    "left_invites": row['left_invites'] or 0,
                    "unique_inviters": row['unique_inviters'] or 0,
                    "unique_invitees": row['unique_invitees'] or 0
                })

            return result

    except Exception as e:
        logger.error(
            f"Unexpected error in invite_timeseries: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/user/timeseries/messages/daily")
async def user_timeseries_messages_daily(
    guild_id: str,
    user_id: str,
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated list of role IDs"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    timezone_str: Optional[str] = Query(
        'UTC', description="Timezone for date grouping"),
    max_points: int = Query(
        90, ge=1, le=365, description="Maximum number of data points"),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get daily message timeseries data for a specific user with role, bot, blacklist, and timezone filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        guild_id_int = int(guild_id)
        user_id_int = int(user_id)

        role_filter_list = role_filter_ids.split(
            ',') if role_filter_ids else None

        if role_filter_list:
            user_ids_with_roles = await db_stats._get_users_with_roles(guild_id, role_filter_list)
            if not user_ids_with_roles or user_id_int not in user_ids_with_roles:
                return []

        if not end_time:
            end_time = datetime.utcnow()
        if not start_time:
            start_time = end_time - timedelta(days=max_points)

        days_in_range = (end_time - start_time).days
        if days_in_range > max_points:
            start_time = end_time - timedelta(days=max_points)

        async with db_stats.pool.acquire() as conn:
            # Build query with proper WHERE clause from the start
            query = f"""
                SELECT 
                    DATE(hour AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}') as date,
                    COALESCE(SUM(message_count), 0) as message_count
                FROM message_tracking_hourly
                WHERE guild_id = $1 
                AND user_id = $2
                AND hour >= $3 
                AND hour <= $4
            """
            params = [guild_id_int, user_id_int, start_time, end_time]

            # Apply bot filter (adds AND is_bot = FALSE to existing WHERE)
            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')

            # Apply blacklist filters (adds AND conditions to existing WHERE)
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'message_tracking_hourly',
                include_users=True, include_channels=True
            )

            # Add GROUP BY and ORDER BY
            query += " GROUP BY date ORDER BY date ASC"

            rows = await conn.fetch(query, *params)

            data_by_date = {row['date'].isoformat(): row['message_count']
                            for row in rows}

            result = []
            current_date = start_time.date()
            end_date_obj = end_time.date()

            while current_date <= end_date_obj:
                date_str = current_date.isoformat()
                result.append({
                    'date': date_str,
                    'messages': data_by_date.get(date_str, 0)
                })
                current_date += timedelta(days=1)

            return result

    except Exception as e:
        logger.error(f"Error in user messages daily timeseries: {e}")
        logger.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=str(e))


