# ============================================
# HELPER FUNCTION FOR USER DISPLAY INFO (used by invite endpoints)
# ============================================


async def get_user_display_info(bot, guild_id: str, user_id: int) -> Dict[str, Any]:
    """
    Get display information for a user.
    This is a simplified version that doesn't require a Discord bot instance.
    For now, returns basic info. In production, you might want to cache this.
    """
    try:
        # Try to get from Discord API
        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
            url = f"{DISCORD_API_BASE}/users/{user_id}"

            async with session.get(url, headers=headers) as resp:
                if resp.status == 200:
                    user_data = await resp.json()

                    avatar_hash = user_data.get('avatar')
                    if avatar_hash:
                        extension = 'gif' if avatar_hash.startswith(
                            'a_') else 'png'
                        avatar_url = f"https://cdn.discordapp.com/avatars/{user_id}/{avatar_hash}.{extension}?size=128"
                    else:
                        default_avatar = int(
                            user_data.get('discriminator', '0')) % 5
                        avatar_url = f"https://cdn.discordapp.com/embed/avatars/{default_avatar}.png"

                    return {
                        'name': user_data.get('global_name') or user_data.get('username', f'User {user_id}'),
                        'global_name': user_data.get('global_name'),
                        'username': user_data.get('username'),
                        'avatar_url': avatar_url,
                        'discriminator': user_data.get('discriminator', '0')
                    }
    except Exception as e:
        print("❌ Error in getting a user's display info in get_user_display_info")

    # Fallback
    return {
        'name': f'User {user_id}',
        'global_name': None,
        'username': None,
        'avatar_url': None,
        'discriminator': '0'
    }


@app.get("/api/channel/top/users")
async def channel_top_users(
    guild_id: str,
    channel_id: str,
    limit: int = 100000000000,
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated list of role IDs to filter by"),
    start_time: Optional[datetime] = Query(None),
    end_time: Optional[datetime] = Query(None),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get top users in a specific channel by message count with role filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Validate IDs
        try:
            guild_id_int = int(guild_id)
            channel_id_int = int(channel_id)
        except ValueError as e:
            raise HTTPException(
                status_code=400, detail=f"Invalid ID format: {e}")

        # Parse role_filter_ids if provided
        role_filter_list = None
        if role_filter_ids:
            role_filter_list = [rid.strip()
                                for rid in role_filter_ids.split(',') if rid.strip()]

        async with db_stats.pool.acquire() as conn:
            # Build the base query
            query = """
                SELECT
                    user_id,
                    SUM(message_count) as message_count
                FROM message_tracking_hourly
                WHERE guild_id = $1
                AND channel_id = $2
            """
            params = [guild_id_int, channel_id_int]
            param_counter = 3

            # Apply role filtering if needed
            if role_filter_list:
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if user_ids:
                    placeholders = []
                    for i in range(len(user_ids)):
                        placeholders.append(f"${param_counter + i}")
                    query += f" AND user_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                    param_counter += len(user_ids)
                else:
                    # No users have these roles
                    return []

            # Add time filters
            if start_time:
                query += f" AND hour >= ${param_counter}"
                params.append(start_time)
                param_counter += 1
            if end_time:
                query += f" AND hour <= ${param_counter}"
                params.append(end_time)
                param_counter += 1

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(
                query, params, guild_id, 'message_tracking_hourly'
            )

            # Update param_counter after bot filter (it might have added parameters)
            param_counter = len(params) + 1

            # Apply blacklist filters
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'message_tracking_hourly',
                include_users=True, include_channels=False,
                specific_channel_id=channel_id
            )

            # Update param_counter again after blacklist filters
            param_counter = len(params) + 1

            # Add GROUP BY and ORDER BY
            query += " GROUP BY user_id ORDER BY message_count DESC"

            # Add LIMIT - IMPORTANT: Use param_counter correctly
            query += f" LIMIT ${param_counter}"
            params.append(limit)  # This must be an integer

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                result.append({
                    'user_id': str(row['user_id']),
                    'message_count': row['message_count'] or 0
                })

            return result

    except Exception as e:
        logger.error(f"Error in channel_top_users: {e}")
        logger.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=str(e))


async def _apply_activity_role_filter(query: str, params: List, guild_id: str,
                                      role_filter_ids: Optional[List[str]],
                                      table_name: str = 'activity_sessions_hourly') -> tuple:
    """Apply role filtering to activity queries by restricting to users with specified roles."""
    if not role_filter_ids:
        return query, params

    user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_ids)

    if not user_ids:
        # No users have these roles, return empty result
        if 'WHERE' in query.upper():
            query += " AND 1=0"
        else:
            query += " WHERE 1=0"
        return query, params

    # Add user_id filter
    placeholders = []
    start_idx = len(params) + 1
    for i in range(len(user_ids)):
        placeholders.append(f"${start_idx + i}")

    user_condition = f"user_id IN ({', '.join(placeholders)})"

    if 'WHERE' in query.upper():
        query += f" AND {user_condition}"
    else:
        query += f" WHERE {user_condition}"

    params.extend(user_ids)
    return query, params


async def _apply_activity_time_filter(query: str, params: List, start_time: Optional[datetime],
                                      end_time: Optional[datetime], days: int) -> tuple:
    """Apply time filtering to activity queries."""
    param_index = len(params) + 1

    if start_time and end_time:
        # Use exact time range
        query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
        params.append(start_time)
        params.append(end_time)
    elif start_time:
        query += f" AND hour >= ${param_index}"
        params.append(start_time)
    elif end_time:
        query += f" AND hour <= ${param_index}"
        params.append(end_time)
    elif days > 0:
        # Use days back
        query += f" AND hour >= NOW() - INTERVAL '1 day' * ${param_index}"
        params.append(days)

    return query, params


