@app.post("/api/emoji/server/top/emojis")
async def emoji_server_top_emojis(request: EmojiLeaderboardRequest):
    """
    Get server's top emojis by usage.
    Can filter by usage_type: 'all', 'message', or 'reaction'
    """
    try:
        # Validate guild_id
        try:
            guild_id_int = int(request.guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400, detail=f"Invalid guild_id format: {request.guild_id}")

        # Apply usage_type filter if specified
        usage_type = None
        if request.usage_type and request.usage_type != 'all':
            usage_type = request.usage_type

        result = await db_stats.q_emoji_server_leaderboard(
            guild_id=request.guild_id,
            limit=request.limit,
            role_filter_ids=request.role_filter_ids,
            start_time=request.start_time,
            end_time=request.end_time,
            usage_type=usage_type
        )

        # Add message/reaction breakdown based on usage_type
        if result:
            for item in result:
                total = item.get('usage_count', 0)
                if request.usage_type == 'all':
                    # Approximate breakdown when both types are included
                    item['message_count'] = total // 2
                    item['reaction_count'] = total - item['message_count']
                elif request.usage_type == 'message':
                    item['message_count'] = total
                    item['reaction_count'] = 0
                elif request.usage_type == 'reaction':
                    item['message_count'] = 0
                    item['reaction_count'] = total
                else:
                    item['message_count'] = 0
                    item['reaction_count'] = 0

        return result
    except ValueError as e:
        logger.error(f"Invalid ID format in emoji_server_top_emojis: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except DatabaseError as e:
        logger.error(f"Database error in emoji_server_top_emojis: {e}")
        raise HTTPException(status_code=500, detail=str(e))
    except Exception as e:
        logger.error(f"Unexpected error in emoji_server_top_emojis: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/emoji/server/top/users")
async def emoji_server_top_users(request: EmojiLeaderboardRequest, user: Optional[Dict] = Depends(get_current_user)):
    """
    Get server's top emoji users with role, bot, and blacklist filtering.
    Can filter by usage_type: 'all', 'message', or 'reaction'
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Validate guild_id
        try:
            guild_id_int = int(request.guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400, detail=f"Invalid guild_id format: {request.guild_id}")

        # Apply usage_type filter if specified
        usage_type = None
        if request.usage_type and request.usage_type != 'all':
            usage_type = request.usage_type

        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(guild_id_int)
        blacklisted_user_ids = set(int(uid)
                                   for uid in blacklists.get('users', []))
        blacklisted_channel_ids = set(int(cid)
                                      for cid in blacklists.get('channels', []))
        blacklisted_category_ids = set(
            int(cat_id) for cat_id in blacklists.get('categories', []))

        async with db_stats.pool.acquire() as conn:
            query = """
                SELECT 
                    user_id,
                    SUM(usage_count) as total_usage,
                    SUM(CASE WHEN usage_type = 'message' THEN usage_count ELSE 0 END) as message_usage,
                    SUM(CASE WHEN usage_type = 'reaction' THEN usage_count ELSE 0 END) as reaction_usage,
                    COUNT(DISTINCT emoji_str) as unique_emojis,
                    MAX(hour) as last_used
                FROM emoji_usage_hourly
                WHERE guild_id = $1
            """
            params = [int(request.guild_id)]
            param_index = 2

            # Apply usage_type filter
            if usage_type:
                query += f" AND usage_type = ${param_index}"
                params.append(usage_type)
                param_index += 1

            # Apply role filtering if needed
            if request.role_filter_ids:
                user_ids = await db_stats._get_users_with_roles(request.guild_id, request.role_filter_ids)
                if user_ids:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(user_ids))]
                    query += f" AND user_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                    param_index += len(user_ids)
                else:
                    return []

            # Apply user blacklist
            if blacklisted_user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_user_ids))]
                query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_user_ids))
                param_index += len(blacklisted_user_ids)

            # Apply channel blacklist
            if blacklisted_channel_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_channel_ids))]
                query += f" AND channel_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_channel_ids))
                param_index += len(blacklisted_channel_ids)

            # Apply category blacklist
            if blacklisted_category_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_category_ids))]
                query += f" AND category_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_category_ids))
                param_index += len(blacklisted_category_ids)

            # Apply time filters
            if request.start_time:
                query += f" AND hour >= ${param_index}"
                params.append(request.start_time)
                param_index += 1
            if request.end_time:
                query += f" AND hour <= ${param_index}"
                params.append(request.end_time)
                param_index += 1

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(
                query, params, request.guild_id, 'emoji_usage_hourly'
            )

            query += """
                GROUP BY user_id
                HAVING SUM(usage_count) > 0
                ORDER BY total_usage DESC
                LIMIT $"""
            query += str(param_index)
            params.append(request.limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                result.append({
                    'user_id': str(row['user_id']),
                    'total_usage': row['total_usage'] or 0,
                    'message_usage': row['message_usage'] or 0,
                    'reaction_usage': row['reaction_usage'] or 0,
                    'unique_emojis': row['unique_emojis'] or 0,
                    'last_used': row['last_used'].isoformat() if row['last_used'] else None
                })

            # Filter out deleted users
            if result:
                user_ids = [item['user_id'] for item in result]
                existence_map = await discord_api.verify_entities_exist(
                    request.guild_id, 'user', user_ids
                )

                filtered_result = []
                for item in result:
                    if existence_map.get(item['user_id'], True):
                        filtered_result.append(item)

                result = filtered_result

            return result

    except ValueError as e:
        logger.error(f"Invalid ID format in emoji_server_top_users: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except Exception as e:
        logger.error(f"Unexpected error in emoji_server_top_users: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/public/emoji/server/top/channels")
async def public_emoji_server_top_channels(request: Request):
    """Public endpoint for server's top channels by emoji usage with role, bot, and blacklist filtering - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')

        # Only allow StatsHQ guild
        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(status_code=403, detail="Access denied.")

        limit = body.get('limit', 10)
        usage_type = body.get('usage_type')
        role_filter_ids = body.get('role_filter_ids')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(int(guild_id))
        blacklisted_user_ids = set(int(uid)
                                   for uid in blacklists.get('users', []))
        blacklisted_channel_ids = set(int(cid)
                                      for cid in blacklists.get('channels', []))
        blacklisted_category_ids = set(
            int(cat_id) for cat_id in blacklists.get('categories', []))

        # Apply role filtering - get users with the selected roles
        allowed_user_ids = None
        if role_filter_ids:
            if isinstance(role_filter_ids, str):
                role_filter_list = [
                    rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
            else:
                role_filter_list = role_filter_ids
            allowed_user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
            if not allowed_user_ids:
                return []
            allowed_user_ids = set(allowed_user_ids)

        # Get bot filter setting
        settings = await db_stats.get_guild_settings(guild_id)
        bot_filter = settings.get('bot_filter', False)

        async with db_stats.pool.acquire() as conn:
            # Build the complete query
            query = """
                SELECT 
                    channel_id,
                    SUM(usage_count) as total_usage,
                    SUM(CASE WHEN usage_type = 'message' THEN usage_count ELSE 0 END) as message_usage,
                    SUM(CASE WHEN usage_type = 'reaction' THEN usage_count ELSE 0 END) as reaction_usage,
                    COUNT(DISTINCT user_id) as unique_users,
                    COUNT(DISTINCT emoji_str) as unique_emojis
                FROM emoji_usage_hourly
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_counter = 2

            # Apply role filter (include ONLY users with selected roles)
            if allowed_user_ids:
                user_id_list = list(allowed_user_ids)
                placeholders = [
                    f"${param_counter + i}" for i in range(len(user_id_list))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_id_list)
                param_counter += len(user_id_list)

            # Apply user blacklist (exclude blacklisted users)
            if blacklisted_user_ids:
                placeholders = [
                    f"${param_counter + i}" for i in range(len(blacklisted_user_ids))]
                query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_user_ids))
                param_counter += len(blacklisted_user_ids)

            # Apply channel blacklist (exclude blacklisted channels)
            if blacklisted_channel_ids:
                placeholders = [
                    f"${param_counter + i}" for i in range(len(blacklisted_channel_ids))]
                query += f" AND channel_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_channel_ids))
                param_counter += len(blacklisted_channel_ids)

            # Apply category blacklist
            if blacklisted_category_ids:
                placeholders = [
                    f"${param_counter + i}" for i in range(len(blacklisted_category_ids))]
                query += f" AND category_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_category_ids))
                param_counter += len(blacklisted_category_ids)

            # Apply bot filter
            if bot_filter:
                query += " AND is_bot = FALSE"

            # Apply usage type filter
            if usage_type and usage_type != 'all':
                query += f" AND usage_type = ${param_counter}"
                params.append(usage_type)
                param_counter += 1

            # Apply time filters
            if start_time:
                query += f" AND hour >= ${param_counter}"
                params.append(start_time)
                param_counter += 1
            if end_time:
                query += f" AND hour <= ${param_counter}"
                params.append(end_time)
                param_counter += 1

            # Add channel filter (exclude null/zero)
            query += " AND channel_id IS NOT NULL AND channel_id != 0"

            # Add GROUP BY, HAVING, ORDER BY
            query += """
                GROUP BY channel_id
                HAVING SUM(usage_count) > 0
                ORDER BY total_usage DESC
                LIMIT $"""
            query += str(param_counter)
            params.append(limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                result.append({
                    'channel_id': str(row['channel_id']),
                    'total_usage': row['total_usage'] or 0,
                    'message_usage': row['message_usage'] or 0,
                    'reaction_usage': row['reaction_usage'] or 0,
                    'unique_users': row['unique_users'] or 0,
                    'unique_emojis': row['unique_emojis'] or 0
                })

            return result

    except Exception as e:
        logger.error(f"Error in public_emoji_server_top_channels: {e}")
        return []

