@app.post("/api/emoji/channel/top/emojis")
async def emoji_channel_top_emojis(request: ChannelStatsRequest):
    """
    Get top emojis in a specific channel.
    Can filter by usage_type: 'all', 'message', or 'reaction'
    """
    try:
        # Validate IDs
        try:
            guild_id_int = int(request.guild_id)
            channel_id_int = int(request.channel_id)
        except ValueError as e:
            raise HTTPException(
                status_code=400, detail=f"Invalid ID format: {e}")

        # Apply usage_type filter if specified
        usage_type = None
        if request.usage_type and request.usage_type != 'all':
            usage_type = request.usage_type

        async with db_stats.pool.acquire() as conn:
            # First get total usage for percentage calculation
            total_query = """
                SELECT COALESCE(SUM(usage_count), 0) as total_usage
                FROM emoji_usage_hourly
                WHERE guild_id = $1 AND channel_id = $2
            """
            total_params = [int(request.guild_id), int(request.channel_id)]

            if usage_type:
                total_params.append(usage_type)
                total_query += f" AND usage_type = ${len(total_params)}"

            if request.start_time:
                total_params.append(request.start_time)
                total_query += f" AND hour >= ${len(total_params)}"
            if request.end_time:
                total_params.append(request.end_time)
                total_query += f" AND hour <= ${len(total_params)}"

            total_row = await conn.fetchrow(total_query, *total_params)
            total_usage = total_row['total_usage'] if total_row else 0

            # Get emoji breakdown
            query = """
                SELECT 
                    emoji_str,
                    is_custom,
                    SUM(usage_count) as total_usage,
                    SUM(CASE WHEN usage_type = 'message' THEN usage_count ELSE 0 END) as message_usage,
                    SUM(CASE WHEN usage_type = 'reaction' THEN usage_count ELSE 0 END) as reaction_usage,
                    COUNT(DISTINCT user_id) as unique_users
                FROM emoji_usage_hourly
                WHERE guild_id = $1 AND channel_id = $2
            """
            params = [int(request.guild_id), int(request.channel_id)]
            param_index = 3

            if usage_type:
                query += f" AND usage_type = ${param_index}"
                params.append(usage_type)
                param_index += 1

            if request.start_time:
                query += f" AND hour >= ${param_index}"
                params.append(request.start_time)
                param_index += 1
            if request.end_time:
                query += f" AND hour <= ${param_index}"
                params.append(request.end_time)
                param_index += 1

            # Apply role filtering if needed
            if request.role_filter_ids:
                user_ids = await db_stats._get_users_with_roles(request.guild_id, request.role_filter_ids)
                if user_ids:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(user_ids))]
                    query += f" AND user_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                    param_index += len(user_ids)
                else:
                    return []

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(
                query, params, request.guild_id, 'emoji_usage_hourly'
            )

            query += """
                GROUP BY emoji_str, is_custom
                HAVING SUM(usage_count) > 0
                ORDER BY total_usage DESC
                LIMIT $"""
            query += str(param_index)
            params.append(request.limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                percentage = (row['total_usage'] /
                              total_usage * 100) if total_usage > 0 else 0
                result.append({
                    'emoji_str': row['emoji_str'],
                    'is_custom': row['is_custom'],
                    'total_usage': row['total_usage'] or 0,
                    'message_usage': row['message_usage'] or 0,
                    'reaction_usage': row['reaction_usage'] or 0,
                    'unique_users': row['unique_users'] or 0,
                    'percentage': round(percentage, 1)
                })

            return result

    except ValueError as e:
        logger.error(f"Invalid ID format in emoji_channel_top_emojis: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except DatabaseError as e:
        logger.error(f"Database error in emoji_channel_top_emojis: {e}")
        raise HTTPException(status_code=500, detail=str(e))
    except Exception as e:
        logger.error(f"Unexpected error in emoji_channel_top_emojis: {e}")
        raise HTTPException(status_code=500, detail=str(e))


