@app.get("/api/emoji/channels")
async def get_emoji_channels(
    guild_id: str,
    user_id: Optional[str] = Query(
        None, description="Filter channels by specific user"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    days_back: Optional[int] = Query(
        None, description="Days to look back"),
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Get all channels that have emoji usage data with blacklist filtering.
    Optionally filter by specific user.
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Validate guild_id
        try:
            guild_id_int = int(guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400, detail=f"Invalid guild_id format: {guild_id}")

        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(guild_id_int)
        blacklisted_user_ids = set(int(uid)
                                   for uid in blacklists.get('users', []))
        blacklisted_channel_ids = set(int(cid)
                                      for cid in blacklists.get('channels', []))

        async with db_stats.pool.acquire() as conn:
            query = """
                SELECT DISTINCT channel_id
                FROM emoji_usage_hourly
                WHERE guild_id = $1
                AND channel_id IS NOT NULL
                AND channel_id != 0
            """
            params = [guild_id_int]
            param_index = 2

            # Apply channel blacklist
            if blacklisted_channel_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_channel_ids))]
                query += f" AND channel_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_channel_ids))
                param_index += len(blacklisted_channel_ids)

            if user_id:
                try:
                    user_id_int = int(user_id)
                    # Check if user is blacklisted
                    if user_id_int in blacklisted_user_ids:
                        return {"channel_ids": [], "count": 0}
                    query += f" AND user_id = ${param_index}"
                    params.append(user_id_int)
                    param_index += 1
                except ValueError:
                    raise HTTPException(
                        status_code=400, detail=f"Invalid user_id format: {user_id}")

            if start_time and end_time:
                query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                params.append(start_time)
                params.append(end_time)
                param_index += 2
            elif start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
                param_index += 1
            elif end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)
                param_index += 1
            elif days_back:
                query += f" AND hour >= NOW() - INTERVAL '1 day' * ${param_index}"
                params.append(days_back)
                param_index += 1

            query += " ORDER BY channel_id"

            rows = await conn.fetch(query, *params)
            channel_ids = [str(row['channel_id']) for row in rows]

            # Verify channels still exist
            existence_map = await discord_api.verify_entities_exist(
                guild_id, 'channel', channel_ids
            )

            # Filter to only existing channels
            existing_channels = [
                cid for cid in channel_ids if existence_map.get(cid, True)]

            return {
                "guild_id": guild_id,
                "channel_ids": existing_channels,
                "count": len(existing_channels),
                "filtered_count": len(channel_ids) - len(existing_channels)
            }

    except ValueError as e:
        logger.error(f"Invalid ID format in get_emoji_channels: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except Exception as e:
        logger.error(f"Unexpected error in get_emoji_channels: {e}")
        raise HTTPException(status_code=500, detail=str(e))


