@app.get("/api/voice/users")
async def get_voice_users(
    guild_id: str = Query(..., description="Guild ID"),
    start_time: Optional[datetime] = Query(None),
    end_time: Optional[datetime] = Query(None),
    days_back: Optional[int] = Query(None),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get all users who have voice activity data with blacklist filtering - authenticated users only"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        guild_id_int = int(guild_id)

        # Verify user is a member of this guild
        user_servers = await auth_db.get_user_servers(user['discord_id'])
        if not any(s['guild_id'] == guild_id for s in user_servers):
            raise HTTPException(
                status_code=403, detail="You are not a member of this guild")

        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(guild_id_int)
        blacklisted_user_ids = set(int(uid)
                                   for uid in blacklists.get('users', []))

        async with db_stats.pool.acquire() as conn:
            query = """
                SELECT DISTINCT user_id
                FROM voice_session_history_hourly
                WHERE guild_id = $1
            """
            params = [guild_id_int]
            param_index = 2

            # Apply user blacklist
            if blacklisted_user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_user_ids))]
                query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_user_ids))
                param_index += len(blacklisted_user_ids)

            if start_time and end_time:
                query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                params.append(start_time)
                params.append(end_time)
            elif start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
            elif end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)
            elif days_back:
                query += f" AND hour >= NOW() - INTERVAL '1 day' * ${param_index}"
                params.append(days_back)

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')

            query += " ORDER BY user_id"

            rows = await conn.fetch(query, *params)
            user_ids = [str(row['user_id']) for row in rows]

            # Filter out deleted users
            existence_map = await discord_api.verify_entities_exist(guild_id, 'user', user_ids)
            filtered_users = [
                uid for uid in user_ids if existence_map.get(uid, True)]

            return {
                "user_ids": filtered_users,
                "count": len(filtered_users),
                "guild_id": guild_id
            }

    except ValueError as e:
        logger.error(f"Invalid ID format in get_voice_users: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except Exception as e:
        logger.error(f"Error in get_voice_users: {e}")
        return {"user_ids": [], "count": 0}


