@app.get("/api/server/top/voice-channels")
async def server_top_voice_channels(
    guild_id: str,
    limit: int = 100000000000,
    role_filter_ids: Optional[str] = Query(None),
    start_time: Optional[str] = Query(None),  # Accept string
    end_time: Optional[str] = Query(None),    # Accept string
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get server's top voice channels with time filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Convert string dates to datetime
        start_time_dt = None
        end_time_dt = None

        if start_time:
            start_time_dt = datetime.fromisoformat(
                start_time.replace('Z', '+00:00'))
        if end_time:
            end_time_dt = datetime.fromisoformat(
                end_time.replace('Z', '+00:00'))

        role_filter_list = role_filter_ids.split(
            ',') if role_filter_ids else None

        result = await db_stats.q_server_top_voice_channels(
            guild_id=guild_id,
            role_filter_ids=role_filter_list,
            start_time=start_time_dt,
            end_time=end_time_dt,
            limit=limit
        )

        return result

    except Exception as e:
        logger.error(f"Error in server_top_voice_channels: {e}")
