@app.post("/api/guild/activity-users")
async def guild_activity_users(
    request: Request,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Get all users who have activity sessions in a guild with blacklist filtering.
    Requires authentication.
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        body = await request.json()
        guild_id = body.get('guild_id')
        limit = body.get('limit', 500)

        if not guild_id:
            raise HTTPException(status_code=400, detail="guild_id is required")

        # Verify user has access to this guild
        user_servers = await auth_db.get_user_servers(user['discord_id'])
        if not any(s['guild_id'] == guild_id for s in user_servers):
            raise HTTPException(
                status_code=403,
                detail="You are not a member of this guild or do not have access"
            )

        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(int(guild_id))
        blacklisted_user_ids = set(int(uid)
                                   for uid in blacklists.get('users', []))

        async with db_stats.pool.acquire() as conn:
            # Get distinct user IDs from activity_sessions_hourly with blacklist filter
            query = """
                SELECT DISTINCT user_id
                FROM activity_sessions_hourly
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_index = 2

            # Apply user blacklist
            if blacklisted_user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_user_ids))]
                query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_user_ids))
                param_index += len(blacklisted_user_ids)

            query += " ORDER BY user_id LIMIT $"
            query += str(param_index)
            params.append(limit)

            rows = await conn.fetch(query, *params)
            user_ids = [str(row['user_id']) for row in rows]

            return {
                "success": True,
                "guild_id": guild_id,
                "user_ids": user_ids,
                "count": len(user_ids)
            }

    except json.JSONDecodeError:
        raise HTTPException(
            status_code=400,
            detail="Invalid JSON body. Please provide {guild_id: ..., limit: ...}"
        )
    except Exception as e:
        logger.error(f"Error in guild_activity_users: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/activity/server/top", response_model=ActivityCategoryStatsResponse)
async def activity_server_top(request: ActivityServerTopRequest):
    """
    Get all top activities in a server.
    Can be filtered by time period and sorted by users, sessions, or time.
    """
    try:
        # Validate guild_id
        try:
            guild_id_int = int(request.guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400, detail=f"Invalid guild_id format: {request.guild_id}")

        async with db_stats.pool.acquire() as conn:
            # Build base query
            query = '''
                SELECT
                    display_name,
                    activity_type,
                    COUNT(DISTINCT user_id) as user_count,
                    SUM(total_duration_seconds) as total_duration_seconds,
                    SUM(session_count) as session_count
                FROM activity_sessions_hourly
                WHERE guild_id = $1
            '''
            params = [guild_id_int]

            # Apply role filtering if needed
            if request.role_filter_ids:
                query, params = await _apply_activity_role_filter(
                    query, params, request.guild_id, request.role_filter_ids
                )

            # Apply time filtering
            query, params = await _apply_activity_time_filter(
                query, params, request.start_time, request.end_time, request.days
            )

            # Apply bot filter from guild settings
            query, params = await db_stats._apply_bot_filter(
                query, params, request.guild_id, 'activity_sessions_hourly'
            )

            # Group by display_name and activity_type
            query += " GROUP BY display_name, activity_type"

            # Execute query
            rows = await conn.fetch(query, *params)

            # Convert to list of dicts
            stats = [dict(row) for row in rows]

            # Apply sorting based on sort_by parameter
            if request.sort_by == "users":
                stats.sort(key=lambda x: x.get(
                    'user_count', 0) or 0, reverse=True)
            elif request.sort_by == "sessions":
                stats.sort(key=lambda x: x.get(
                    'session_count', 0) or 0, reverse=True)
            elif request.sort_by == "time":
                stats.sort(key=lambda x: x.get(
                    'total_duration_seconds', 0) or 0, reverse=True)

            # Format response
            activities = []
            for stat in stats:
                total_seconds = stat.get('total_duration_seconds', 0) or 0
                activities.append(ActivityStatItem(
                    display_name=stat['display_name'],
                    activity_type=stat['activity_type'],
                    session_count=stat.get('session_count', 0) or 0,
                    total_duration_seconds=total_seconds,
                    total_duration_formatted=format_duration(total_seconds),
                    user_count=stat.get('user_count', 0) or 0
                ))

            return ActivityCategoryStatsResponse(
                guild_id=request.guild_id,
                category="all",
                days=request.days,
                sort_by=request.sort_by,
                total_activities=len(activities),
                activities=activities
            )

    except ValueError as e:
        logger.error(f"Invalid ID format in activity_server_top: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except DatabaseError as e:
        logger.error(f"Database error in activity_server_top: {e}")
        raise HTTPException(status_code=500, detail=str(e))
    except Exception as e:
        logger.error(f"Unexpected error in activity_server_top: {e}")
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))


