@app.get("/api/category/top/channels")
async def category_top_channels(
    guild_id: str,
    category_id: str,
    limit: int = 100000000000,
    role_filter_ids: Optional[str] = Query(None),
    start_time: Optional[datetime] = Query(None),
    end_time: Optional[datetime] = Query(None),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get top channels in a specific category by message count"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Validate IDs
        try:
            guild_id_int = int(guild_id)
            category_id_int = int(category_id)
        except ValueError as e:
            raise HTTPException(
                status_code=400, detail=f"Invalid ID format: {e}")

        # Parse role_filter_ids if provided
        role_filter_list = None
        if role_filter_ids:
            role_filter_list = [rid.strip()
                                for rid in role_filter_ids.split(',') if rid.strip()]

        async with db_stats.pool.acquire() as conn:
            query = """
                SELECT 
                    channel_id,
                    SUM(message_count) as message_count,
                    COUNT(DISTINCT user_id) as unique_users
                FROM message_tracking_hourly
                WHERE guild_id = $1 
                AND category_id = $2
            """
            params = [int(guild_id), int(category_id)]
            param_index = 3

            # Apply role filtering if needed
            if role_filter_list:
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if user_ids:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(user_ids))]
                    query += f" AND user_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                    param_index += len(user_ids)
                else:
                    return []

            if start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
                param_index += 1
            if end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)
                param_index += 1

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(
                query, params, guild_id, 'message_tracking_hourly'
            )

            # Add GROUP BY
            query += " GROUP BY channel_id"

            # Add ORDER BY
            query += " ORDER BY message_count DESC"

            # Add LIMIT
            query += f" LIMIT ${param_index}"
            params.append(limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                result.append({
                    'channel_id': str(row['channel_id']),
                    'message_count': row['message_count'] or 0,
                    'unique_users': row['unique_users'] or 0
                })

            return result

    except Exception as e:
        logger.error(f"Error in category_top_channels: {e}")
        raise HTTPException(status_code=500, detail=str(e))


