class ChannelStatsRequest(BaseModel):
    guild_id: str
    channel_id: str
    role_filter_ids: Optional[List[int]] = None
    start_time: Optional[datetime] = None
    end_time: Optional[datetime] = None


@app.post("/api/channel/stats/messages")
async def channel_total_messages(request: ChannelStatsRequest):
    """Get channel's total message statistics with role filtering"""
    try:
        # Convert IDs to integers
        try:
            guild_id_int = int(request.guild_id)
            channel_id_int = int(request.channel_id)
        except ValueError as e:
            raise HTTPException(
                status_code=400, detail=f"Invalid ID format: {e}")

        async with db_stats.pool.acquire() as conn:
            query = """
                SELECT 
                    COALESCE(SUM(message_count), 0) as total_messages,
                    COALESCE(SUM(total_chars), 0) as total_chars,
                    COALESCE(SUM(total_chars) / NULLIF(SUM(message_count), 0), 0) as avg_chars,
                    COUNT(DISTINCT user_id) as unique_users,
                    COALESCE(SUM(attachment_count), 0) as has_attachments,
                    COALESCE(SUM(embed_count), 0) as has_embeds
                FROM message_tracking_hourly
                WHERE guild_id = $1 
                AND channel_id = $2
            """
            params = [guild_id_int, channel_id_int]

            # Apply role filtering if needed
            if request.role_filter_ids:
                user_ids = await db_stats._get_users_with_roles(request.guild_id, request.role_filter_ids)
                if user_ids:
                    placeholders = [
                        f"${len(params) + i + 1}" for i in range(len(user_ids))]
                    query += f" AND user_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                else:
                    # No users have these roles
                    return {
                        'total_messages': 0, 'total_chars': 0, 'avg_chars': 0.0,
                        'unique_users': 0, 'messages_per_user': 0.0,
                        'has_attachments': 0, 'has_embeds': 0
                    }

            if request.start_time:
                params.append(request.start_time)
                query += f" AND hour >= ${len(params)}"
            if request.end_time:
                params.append(request.end_time)
                query += f" AND hour <= ${len(params)}"

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(
                query, params, request.guild_id, 'message_tracking_hourly'
            )

            row = await conn.fetchrow(query, *params)

            total_messages = row['total_messages'] or 0
            unique_users = row['unique_users'] or 0
            messages_per_user = total_messages / max(unique_users, 1)

            return {
                'total_messages': total_messages,
                'total_chars': row['total_chars'] or 0,
                'avg_chars': round(row['avg_chars'] or 0, 2),
                'unique_users': unique_users,
                'messages_per_user': round(messages_per_user, 2),
                'has_attachments': row['has_attachments'] or 0,
                'has_embeds': row['has_embeds'] or 0
            }

    except ValueError as e:
        logger.error(f"Invalid ID format in channel_total_messages: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except Exception as e:
        logger.error(f"Error in channel_total_messages: {e}")
        raise HTTPException(status_code=500, detail=str(e))


