@app.post("/api/channel/stats/voice")
async def channel_total_voice(request: Request, user: Optional[Dict] = Depends(get_current_user)):
    """Get channel's total voice statistics with role filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        body = await request.json()

        guild_id = body.get('guild_id')
        channel_id = body.get('channel_id')
        role_filter_ids = body.get('role_filter_ids')  # ← ADD THIS
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')

        # Convert string dates to datetime
        start_time = None
        end_time = None

        if start_time_str:
            start_time = datetime.fromisoformat(
                start_time_str.replace('Z', '+00:00'))
        if end_time_str:
            end_time = datetime.fromisoformat(
                end_time_str.replace('Z', '+00:00'))

        if not guild_id or not channel_id:
            raise HTTPException(
                status_code=400, detail="guild_id and channel_id are required")

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering - THIS IS THE KEY PART
            user_ids = None
            if role_filter_ids:
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_ids)
                if not user_ids:
                    # No users have these roles, return empty result
                    return {
                        "total_seconds": 0,
                        "total_hours": 0,
                        "unique_users": 0,
                        "session_count": 0,
                        "avg_session": 0.0,
                        "seconds_per_user": 0.0
                    }

            query = """
                SELECT
                    COALESCE(SUM(total_seconds), 0) as total_seconds,
                    COUNT(DISTINCT user_id) as unique_users,
                    COALESCE(SUM(session_count), 0) as session_count
                FROM voice_session_history_hourly
                WHERE guild_id = $1 AND channel_id = $2
            """
            params = [int(guild_id), int(channel_id)]
            param_counter = 3

            # Apply role filter - ADD THIS SECTION
            if user_ids:
                placeholders = []
                for i in range(len(user_ids)):
                    placeholders.append(f"${param_counter + i}")
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_counter += len(user_ids)

            # Apply time filters
            if start_time:
                query += f" AND hour >= ${param_counter}"
                params.append(start_time)
                param_counter += 1
            if end_time:
                query += f" AND hour <= ${param_counter}"
                params.append(end_time)
                param_counter += 1

            # Apply voice state filter
            query, params = await db_stats._apply_voice_state_filter(query, params, guild_id, 'state_flags')

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')

            # Apply blacklist filters
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'voice_session_history_hourly',
                include_users=True, include_channels=False,
                specific_channel_id=channel_id
            )

            row = await conn.fetchrow(query, *params)

            total_seconds = row['total_seconds'] if row else 0
            unique_users = row['unique_users'] if row else 0

            return {
                "total_seconds": total_seconds,
                "total_hours": round(total_seconds / 3600, 2),
                "session_count": row['session_count'] if row else 0,
                "unique_users": unique_users,
                "avg_session": 0.0,
                "seconds_per_user": total_seconds / max(unique_users, 1)
            }

    except Exception as e:
        logger.error(f"Error in channel_total_voice: {e}")
        logger.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/category/activity/distribution")
async def category_activity_distribution(request: CategoryActivityDistributionRequest):
    """Get category's activity distribution by hour with role filtering"""
    try:
        try:
            guild_id_int = int(request.guild_id)
            category_id_int = int(request.category_id)
        except ValueError as e:
            raise HTTPException(
                status_code=400, detail=f"Invalid ID format: {e}")

        # Verify category exists in discord_channels table
        category_info = await db_stats.get_category_from_cache(guild_id_int, category_id_int)
        if not category_info:
            logger.warning(
                f"Category {request.category_id} not found in discord_channels table")
            # Continue anyway - the category might have been added recently

        async with db_stats.pool.acquire() as conn:
            messages = {f'hour_{i}': 0 for i in range(24)}
            total_messages = 0

            # Get users with roles if filtering
            user_ids = None
            if request.role_filter_ids:
                user_ids = await db_stats._get_users_with_roles(request.guild_id, request.role_filter_ids)
                if not user_ids:
                    return {
                        'messages': {f'hour_{i}': 0 for i in range(24)},
                        'total_messages': 0
                    }

            # Messages query
            if request.days_back == 0:
                query_messages = f"""
                    SELECT 
                        EXTRACT(HOUR FROM hour AT TIME ZONE 'UTC' AT TIME ZONE '{request.timezone_str}') as hour_of_day,
                        SUM(message_count) as message_count
                    FROM message_tracking_hourly
                    WHERE guild_id = $1 
                    AND category_id = $2
                """
                params_messages = [guild_id_int, category_id_int]
            else:
                query_messages = f"""
                    SELECT 
                        EXTRACT(HOUR FROM hour AT TIME ZONE 'UTC' AT TIME ZONE '{request.timezone_str}') as hour_of_day,
                        SUM(message_count) as message_count
                    FROM message_tracking_hourly
                    WHERE guild_id = $1 
                    AND category_id = $2 
                    AND hour >= NOW() - INTERVAL '{request.days_back} days'
                """
                params_messages = [guild_id_int, category_id_int]

            # Apply role filtering
            if user_ids:
                placeholders = [
                    f"${len(params_messages) + i + 1}" for i in range(len(user_ids))]
                query_messages += f" AND user_id IN ({', '.join(placeholders)})"
                params_messages.extend(user_ids)

            # Apply bot filter
            query_messages, params_messages = await db_stats._apply_bot_filter(
                query_messages, params_messages, request.guild_id, 'message_tracking_hourly'
            )

            query_messages += " GROUP BY hour_of_day ORDER BY hour_of_day"

            rows_messages = await conn.fetch(query_messages, *params_messages)
            for row in rows_messages:
                hour = int(row['hour_of_day'])
                count = row['message_count'] or 0
                messages[f'hour_{hour}'] = count
                total_messages += count

            # Add category info to response if available
            response = {
                'messages': messages,
                'total_messages': total_messages
            }

            if category_info:
                response['category_name'] = category_info.get('category_name')

            return response

    except ValueError as e:
        logger.error(
            f"Invalid ID format in category_activity_distribution: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except Exception as e:
        logger.error(f"Error in category_activity_distribution: {e}")
        return {
            'messages': {f'hour_{i}': 0 for i in range(24)},
            'total_messages': 0
        }


