@app.get("/api/growth/roles")
async def get_roles_with_growth_data(
    guild_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Get all roles that have growth data in the role_growth_hourly table.
    Uses role_name and role_color from current_role_members table.
    Returns only roles that actually have recorded additions or removals.
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Validate guild_id
        try:
            guild_id_int = int(guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400, detail=f"Invalid guild_id format: {guild_id}")

        # Verify user is a member of this guild
        user_servers = await auth_db.get_user_servers(user['discord_id'])
        if not any(s['guild_id'] == guild_id for s in user_servers):
            raise HTTPException(
                status_code=403, detail="You are not a member of this guild")

        async with db_stats.pool.acquire() as conn:
            # Get distinct role IDs from role_growth_hourly table
            query = """
                SELECT DISTINCT role_id
                FROM role_growth_hourly
                WHERE guild_id = $1
                ORDER BY role_id
            """
            rows = await conn.fetch(query, guild_id_int)
            role_ids = [row['role_id'] for row in rows]

            if not role_ids:
                return {
                    "success": True,
                    "guild_id": guild_id,
                    "total_roles": 0,
                    "roles": []
                }

            # Convert to list of ints for the IN clause
            role_ids_list = list(role_ids)

            # Get role details from current_role_members table (NOT Discord API)
            role_details_query = f"""
                SELECT DISTINCT ON (role_id)
                    role_id,
                    role_name,
                    role_color,
                    updated_at
                FROM current_role_members
                WHERE guild_id = $1
                AND role_id = ANY($2::bigint[])
                ORDER BY role_id, updated_at DESC
            """

            role_rows = await conn.fetch(role_details_query, guild_id_int, role_ids_list)

            # Create a map of role_id -> role details
            role_details_map = {}
            for row in role_rows:
                role_id = str(row['role_id'])
                role_details_map[role_id] = {
                    'name': row['role_name'] or f"Role {role_id}",
                    'color': row['role_color'] or "#99aab5",
                    'position': 0,  # Default if not stored
                    'hoist': False,
                    'mentionable': False
                }

            # Build the response with growth statistics
            roles_with_details = []

            for role_id in role_ids:
                role_id_str = str(role_id)
                role_info = role_details_map.get(role_id_str, {})

                # Get additional stats for this role
                stats_query = """
                    SELECT 
                        COALESCE(SUM(added_count), 0) as total_added,
                        COALESCE(SUM(removed_count), 0) as total_removed,
                        COUNT(DISTINCT user_id) as unique_users_affected
                    FROM role_growth_hourly
                    WHERE guild_id = $1 AND role_id = $2
                """
                stats_row = await conn.fetchrow(stats_query, guild_id_int, role_id)

                # Get current member count from current_role_members
                current_members_query = """
                    SELECT COUNT(DISTINCT user_id) as current_members
                    FROM current_role_members
                    WHERE guild_id = $1 AND role_id = $2
                """
                current_members_row = await conn.fetchrow(current_members_query, guild_id_int, role_id)

                total_added = stats_row['total_added'] if stats_row else 0
                total_removed = stats_row['total_removed'] if stats_row else 0

                roles_with_details.append({
                    'role_id': role_id_str,
                    'name': role_info.get('name', f'Role {role_id_str}'),
                    'color': role_info.get('color', '#99aab5'),
                    'position': role_info.get('position', 0),
                    'hoist': role_info.get('hoist', False),
                    'mentionable': role_info.get('mentionable', False),
                    'total_added': total_added,
                    'total_removed': total_removed,
                    'net_growth': total_added - total_removed,
                    'unique_users_affected': stats_row['unique_users_affected'] if stats_row else 0,
                    'current_members': current_members_row['current_members'] if current_members_row else 0
                })

            # Sort by net growth (most positive first) or by total activity
            roles_with_details.sort(
                key=lambda x: (
                    abs(x['total_added'] + x['total_removed']),
                    x['net_growth']
                ),
                reverse=True
            )

            # Limit to 100 roles for performance
            roles_with_details = roles_with_details[:100]

            return {
                "success": True,
                "guild_id": guild_id,
                "total_roles": len(roles_with_details),
                "roles": roles_with_details,
                "source": "current_role_members_table"
            }

    except ValueError as e:
        logger.error(f"Invalid ID format in get_roles_with_growth_data: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except DatabaseError as e:
        logger.error(f"Database error in get_roles_with_growth_data: {e}")
        raise HTTPException(status_code=500, detail=str(e))
    except Exception as e:
        logger.error(f"Unexpected error in get_roles_with_growth_data: {e}")
        raise HTTPException(status_code=500, detail=str(e))


