@app.get("/api/growth/roles/simple")
async def get_roles_with_growth_data_simple(
    guild_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Get just the role IDs that have growth data (no Discord API calls, faster).
    Includes role_name and role_color from current_role_members table.
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Validate guild_id
        try:
            guild_id_int = int(guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400, detail=f"Invalid guild_id format: {guild_id}")

        # Verify user is a member of this guild
        user_servers = await auth_db.get_user_servers(user['discord_id'])
        if not any(s['guild_id'] == guild_id for s in user_servers):
            raise HTTPException(
                status_code=403, detail="You are not a member of this guild")

        async with db_stats.pool.acquire() as conn:
            # Get distinct role IDs with their names and colors
            query = """
                SELECT DISTINCT ON (role_id)
                    role_id,
                    role_name,
                    role_color
                FROM current_role_members
                WHERE guild_id = $1
                AND role_id IN (
                    SELECT DISTINCT role_id 
                    FROM role_growth_hourly 
                    WHERE guild_id = $1
                )
                ORDER BY role_id
            """
            rows = await conn.fetch(query, guild_id_int)

            roles = []
            for row in rows:
                role_id = str(row['role_id'])
                roles.append({
                    "role_id": role_id,
                    "name": row['role_name'] or f"Role {role_id}",
                    "color": row['role_color'] or "#99aab5"
                })

            return {
                "success": True,
                "guild_id": guild_id,
                "total_roles": len(roles),
                "roles": roles
            }

    except ValueError as e:
        logger.error(
            f"Invalid ID format in get_roles_with_growth_data_simple: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except DatabaseError as e:
        logger.error(
            f"Database error in get_roles_with_growth_data_simple: {e}")
        raise HTTPException(status_code=500, detail=str(e))
    except Exception as e:
        logger.error(
            f"Unexpected error in get_roles_with_growth_data_simple: {e}")
        raise HTTPException(status_code=500, detail=str(e))


