@app.get("/api/growth/role/summary")
async def get_role_growth_summary(
    guild_id: str,
    role_id: str,
    days: int = Query(30, ge=1, le=2000, description="Days to look back"),
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Get a comprehensive growth summary for a specific role using current_role_members table.
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Validate IDs
        try:
            guild_id_int = int(guild_id)
            role_id_int = int(role_id)
        except ValueError as e:
            raise HTTPException(
                status_code=400, detail=f"Invalid ID format: {e}")

        # Get role additions/removals data
        role_data = await db_stats.get_role_additions_removals(
            guild_id=guild_id,
            role_id=role_id,
            days=days
        )

        # Get projected growth
        projected = await db_stats.get_projected_role_growth(guild_id, role_id, days=min(days, 30))

        # Get role details from current_role_members table (NOT Discord API)
        role_details = None
        async with db_stats.pool.acquire() as conn:
            row = await conn.fetchrow("""
                SELECT role_name, role_color
                FROM current_role_members
                WHERE guild_id = $1 AND role_id = $2
                LIMIT 1
            """, guild_id_int, role_id_int)

            if row:
                role_details = {
                    'name': row['role_name'] or f'Role {role_id}',
                    'color': row['role_color'] or "#99aab5",
                    'position': 0,  # Can be added to table later
                    'hoist': False,  # Can be added to table later
                    'mentionable': False  # Can be added to table later
                }
            else:
                role_details = {'name': f'Role {role_id}'}

        # Get current members with this role from current_role_members table
        current_members = 0
        try:
            async with db_stats.pool.acquire() as conn:
                count = await conn.fetchval("""
                    SELECT COUNT(DISTINCT user_id)
                    FROM current_role_members
                    WHERE guild_id = $1 AND role_id = $2
                """, guild_id_int, role_id_int)
                current_members = count or 0
        except Exception as e:
            logger.error(
                f"Error getting current members for role {role_id}: {e}")
            current_members = 0

        return {
            "success": True,
            "guild_id": guild_id,
            "role_id": role_id,
            "role_details": role_details,
            "current_members": current_members,
            "total_added": role_data['total_added'],
            "total_removed": role_data['total_removed'],
            "net_growth": role_data['net_growth'],
            "growth_rate": (role_data['net_growth'] / days) if days > 0 else 0,
            "timeseries": {
                "added": role_data['added'],
                "removed": role_data['removed']
            },
            "projected_growth": {
                "added_forecast": projected['added_forecast'][:min(days, 30)],
                "removed_forecast": projected['removed_forecast'][:min(days, 30)],
                "volatility": projected['volatility'],
                "trend_direction": projected['trend_direction']
            },
            "period_days": days,
            "generated_at": datetime.utcnow().isoformat(),
            "source": "current_role_members_table"
        }

    except Exception as e:
        logger.error(
            f"Error getting role growth summary for {guild_id}/{role_id}: {e}")
        raise HTTPException(status_code=500, detail=str(e))


