@app.get("/api/user/servers", response_model=List[ServerResponse])
async def get_user_servers(
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get user's Discord servers (ONLY servers they are actually members of)"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    discord_id = user['discord_id']

    try:
        # Read from database - permissions are already stored
        servers = await auth_db.get_user_servers(discord_id)

        # Verify guilds still exist
        guild_ids = [s['guild_id'] for s in servers]
        existence_map = await discord_api.verify_entities_exist('', 'guild', guild_ids)

        # Filter out deleted guilds
        valid_servers = [
            s for s in servers if existence_map.get(s['guild_id'], True)]

        result = []
        for row in valid_servers:
            is_stats_hq = row['guild_id'] == STATSHQ_GUILD_ID

            # Parse permissions as BIGINT to check flags
            permissions_str = str(row.get('permissions', '0'))
            try:
                # Use int() - Python handles big integers natively
                permissions_int = int(permissions_str)
            except (ValueError, TypeError):
                permissions_int = 0

            ADMIN_PERMISSION = 0x8
            MANAGE_SERVER_PERMISSION = 0x20

            has_admin = (permissions_int & ADMIN_PERMISSION) != 0
            has_manage_server = (
                permissions_int & MANAGE_SERVER_PERMISSION) != 0

            result.append(ServerResponse(
                id=row['guild_id'],
                name=row['guild_name'],
                icon=row['guild_icon'],
                member_count=row['member_count'],
                has_bot=True,
                selected=row['guild_id'] == user.get('selected_server'),
                is_statshq=is_stats_hq,
                # Keep original for compatibility
                permissions=str(row.get('permissions', '0')),
                has_admin=has_admin,  # Add this field
                has_manage_server=has_manage_server  # Add this field
            ))

        return result

    except DatabaseError as e:
        logger.error(
            f"Database error fetching servers for user {discord_id}: {e}")
        return []
    except Exception as e:
        logger.error(
            f"Unexpected error fetching servers for user {discord_id}: {e}")
        raise HTTPException(status_code=500, detail="Failed to fetch servers")

@app.post("/api/user/save-server")
async def save_server(
    request: SaveServerRequest,
    user: Optional[Dict] = Depends(get_current_user)
):
    """Save user's selected server preference - Privileged users can save any server the bot is in"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    # Define privileged users
    PRIVILEGED_USERS = ['1428927519515611141', '591655972414685229']
    is_privileged = user['discord_id'] in PRIVILEGED_USERS

    # For regular users: Verify the user is actually a member of this server
    if not is_privileged:
        servers = await auth_db.get_user_servers(user['discord_id'])
        server_ids = [s['guild_id'] for s in servers]

        # Verify guild still exists
        existence_map = await discord_api.verify_entities_exist('', 'guild', [request.guild_id])
        guild_exists = existence_map.get(request.guild_id, False)

        if request.guild_id not in server_ids or not guild_exists:
            raise HTTPException(
                status_code=403,
                detail="You are not a member of this server, the bot is not present, or the server no longer exists"
            )

        # Just update the selected server for regular users
        try:
            success = await auth_db.update_user_selected_server(user['discord_id'], request.guild_id)

            if success:
                await db_stats.cache_user_server(user['discord_id'], request.guild_id)
                await db_stats.record_recent_server(user['discord_id'], request.guild_id)

            if not success:
                raise HTTPException(
                    status_code=500, detail="Failed to save server preference"
                )

            return {"success": True, "selected_server": request.guild_id}
        except DatabaseError as e:
            logger.error(f"Database error saving server: {e}")
            raise HTTPException(
                status_code=500, detail="Failed to save server preference"
            )

    else:
        # Check if bot is in the guild
        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
            url = f"{DISCORD_API_BASE}/guilds/{request.guild_id}?with_counts=true"

            async with session.get(url, headers=headers, timeout=10) as resp:
                if resp.status != 200:
                    raise HTTPException(
                        status_code=403,
                        detail=f"Bot is not in this server or server not found. Privileged users can only save servers the bot is in."
                    )

                guild_data = await resp.json()
                member_count = guild_data.get('approximate_member_count', 0)

                # Ensure the server is in user's server list
                existing_servers = await auth_db.get_user_servers(user['discord_id'])
                existing_ids = [s['guild_id'] for s in existing_servers]

                if request.guild_id not in existing_ids:
                    # Add the server to user's list
                    async with auth_db.pool.acquire() as conn:
                        await conn.execute("""
                            INSERT INTO user_servers (discord_id, guild_id, guild_name, guild_icon, member_count, permissions)
                            VALUES ($1, $2, $3, $4, $5, $6)
                            ON CONFLICT (discord_id, guild_id) DO UPDATE SET
                                guild_name = EXCLUDED.guild_name,
                                guild_icon = EXCLUDED.guild_icon,
                                member_count = EXCLUDED.member_count,
                                permissions = EXCLUDED.permissions,
                                last_updated = CURRENT_TIMESTAMP
                        """,
                                           user['discord_id'],
                                           request.guild_id,
                                           guild_data['name'],
                                           guild_data.get('icon'),
                                           member_count,
                                           "0"
                                           )

                # Update selected server
                success = await auth_db.update_user_selected_server(user['discord_id'], request.guild_id)

                if success:
                    await db_stats.cache_user_server(user['discord_id'], request.guild_id)
                    await db_stats.record_recent_server(user['discord_id'], request.guild_id)

                return {
                    "success": True,
                    "selected_server": request.guild_id,
                    "message": f"Server set to: {guild_data['name']}"
                }
                
