# In your blacklist_get endpoint (around line 12000)
@app.post("/api/blacklist/get")
async def blacklist_get(request: BlacklistGetRequest):
    """Get blacklist for guild"""
    try:
        if not db_stats.db_connected:
            return {"items": []}

        items = await db_stats.get_blacklist(
            guild_id=request.guild_id,
            entity_type=request.entity_type
        )

        # Verify blacklisted entities still exist - USE CACHED VERSION
        if items:
            # Group by entity type
            by_type = {}
            for item in items:
                entity_type = item['type']
                if entity_type not in by_type:
                    by_type[entity_type] = []
                by_type[entity_type].append(item['entity_id'])

            # Check existence for each type using CACHED method
            filtered_items = []
            for entity_type, entity_ids in by_type.items():
                # Use the new cached verification method
                existence_map = await db_stats.verify_entities_exist_with_cache(
                    request.guild_id, entity_type, entity_ids
                )

                # Keep only items that still exist
                for item in items:
                    if item['type'] == entity_type and existence_map.get(item['entity_id'], True):
                        filtered_items.append(item)

            items = filtered_items

        return {"items": items}
    except DatabaseError as e:
        logger.error(f"Database error in blacklist_get: {e}")
        return {"items": [], "error": str(e)}
    except Exception as e:
        logger.error(f"Unexpected error in blacklist_get: {e}")
        return {"items": [], "error": str(e)}


