@app.post("/api/settings/dashboard-access/set/public")
async def set_dashboard_access_public(request: Request, user: Optional[Dict] = Depends(get_current_user)):
    """Set dashboard access level to Public (anyone can view, no authentication required)"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        body = await request.json()
        guild_id = body.get('guild_id')

        if not guild_id:
            raise HTTPException(status_code=400, detail="guild_id is required")

        # Verify user is a member of this guild
        user_servers = await auth_db.get_user_servers(user['discord_id'])
        if not any(s['guild_id'] == guild_id for s in user_servers):
            raise HTTPException(
                status_code=403, detail="You are not a member of this guild")

        # Check if user has admin permissions from database
        permissions = await auth_db.get_user_permissions_from_db(user['discord_id'], guild_id)

        if permissions is None:
            raise HTTPException(
                status_code=403, detail="Could not verify guild membership")

        is_admin = (permissions & 0x8) != 0

        if not is_admin:
            raise HTTPException(
                status_code=403, detail="Only administrators can change dashboard access level")

        # Update the setting
        success = await db_stats.update_setting(guild_id, 'dashboard_access_level', 'Public')

        if success:
            return {
                "success": True,
                "message": "Dashboard access level set to Public - anyone can view the dashboard",
                "dashboard_access_level": "Public"
            }
        else:
            return {
                "success": False,
                "message": "Failed to update dashboard access level"
            }, 500

    except DatabaseError as e:
        logger.error(f"Database error: {e}")
        return {"success": False, "message": f"Database error: {str(e)}"}, 500
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


