@app.post("/api/settings/get", response_model=SettingsResponse)
async def settings_get(request: SettingsGetRequest):
    """Get guild settings"""
    try:
        if not db_stats.db_connected:
            return SettingsResponse(
                guild_id=request.guild_id,
                prefix="s!",
                timezone="UTC",
                voice_states=[],
                permission_level="Default",
                bot_filter=False,
                dashboard_access_level="Member",
                created_at=None,
                default_time_mode="days_back",
                default_days_back=14,
                default_from_date=None,
                default_to_date=None,
                default_rolling_type=None,
                default_rolling_value=None
            )
        settings = await db_stats.get_guild_settings(request.guild_id)
        if not settings:
            return SettingsResponse(
                guild_id=request.guild_id,
                prefix="s!",
                timezone="UTC",
                voice_states=[],
                permission_level="Default",
                bot_filter=False,
                dashboard_access_level="Member",
                created_at=None,
                default_time_mode="days_back",
                default_days_back=14,
                default_from_date=None,
                default_to_date=None,
                default_rolling_type=None,
                default_rolling_value=None
            )
        return SettingsResponse(
            guild_id=str(settings['guild_id']),
            prefix=settings['prefix'],
            timezone=settings['timezone'],
            voice_states=settings['voice_states'],
            permission_level=settings['permission_level'],
            bot_filter=settings['bot_filter'],
            dashboard_access_level=settings.get(
                'dashboard_access_level', 'Member'),
            created_at=settings.get('created_at'),
            default_time_mode=settings.get('default_time_mode', 'days_back'),
            default_days_back=settings.get('default_days_back', 14),
            default_from_date=settings.get('default_from_date'),
            default_to_date=settings.get('default_to_date'),
            default_rolling_type=settings.get('default_rolling_type'),
            default_rolling_value=settings.get('default_rolling_value')
        )
    except DatabaseError as e:
        logger.error(f"Database error in settings_get: {e}")
        return SettingsResponse(
            guild_id=request.guild_id,
            prefix="s!",
            timezone="UTC",
            voice_states=[],
            permission_level="Default",
            bot_filter=False,
            dashboard_access_level="Member",
            created_at=None,
            default_time_mode="days_back",
            default_days_back=14,
            default_from_date=None,
            default_to_date=None,
            default_rolling_type=None,
            default_rolling_value=None
        )
    except Exception as e:
        logger.error(f"Unexpected error in settings_get: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/settings/update")
async def settings_update(request: SettingsUpdateRequest):
    """Update guild setting"""
    try:
        if not db_stats.db_connected:
            return {"success": False, "message": "Database not connected"}

        # Handle different value types
        value = request.value

        # Convert value if needed based on setting type
        if request.setting == "voice_states":
            # Already a list
            pass
        elif request.setting == "bot_filter":
            value = bool(value)
        elif request.setting == "prefix":
            value = str(value).strip()
            if len(value) > 10:
                return {"success": False, "message": "Prefix cannot be longer than 10 characters"}
        elif request.setting == "timezone":
            value = str(value)
        elif request.setting == "permission_level":
            value = str(value)
            if value not in ['All', 'Default', 'User Restriction', 'Moderator', 'Admin']:
                return {"success": False, "message": "Invalid permission level"}
        elif request.setting == "dashboard_access_level":
            value = str(value)
            # Make sure the value is one of the allowed ones
            if value not in ['Public', 'Member', 'Moderator', 'Admin']:
                return {"success": False, "message": f"Invalid dashboard access level: {value}"}

        success = await db_stats.update_setting(
            guild_id=request.guild_id,
            setting=request.setting,
            value=value
        )

        if success:
            return {"success": True, "message": f"Successfully updated {request.setting}"}
        else:
            return {"success": False, "message": f"Failed to update {request.setting}"}
    except DatabaseError as e:
        logger.error(f"Database error in settings_update: {e}")
        return {"success": False, "message": f"Database error: {str(e)}"}
    except Exception as e:
        logger.error(f"Unexpected error in settings_update: {e}")
        return {"success": False, "message": f"Unexpected error: {str(e)}"}


