@app.post("/api/category/stats/voice")
async def category_total_voice(request: Request, user: Optional[Dict] = Depends(get_current_user)):
    """Get category's total voice statistics with role filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        body = await request.json()

        guild_id = body.get('guild_id')
        category_id = body.get('category_id')
        role_filter_ids = body.get('role_filter_ids')  # ← ADD THIS
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')

        # Convert string dates to datetime
        start_time = None
        end_time = None

        if start_time_str:
            start_time = datetime.fromisoformat(
                start_time_str.replace('Z', '+00:00'))
        if end_time_str:
            end_time = datetime.fromisoformat(
                end_time_str.replace('Z', '+00:00'))

        if not guild_id or not category_id:
            raise HTTPException(
                status_code=400, detail="guild_id and category_id are required")

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering - THIS IS THE KEY PART
            user_ids = None
            if role_filter_ids:
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_ids)
                if not user_ids:
                    # No users have these roles, return empty result
                    return {
                        "total_seconds": 0,
                        "total_hours": 0,
                        "unique_users": 0,
                        "session_count": 0,
                        "avg_session": 0.0,
                        "seconds_per_user": 0.0
                    }

            query = """
                SELECT
                    COALESCE(SUM(total_seconds), 0) as total_seconds,
                    COUNT(DISTINCT user_id) as unique_users,
                    COALESCE(SUM(session_count), 0) as session_count
                FROM voice_session_history_hourly
                WHERE guild_id = $1 AND category_id = $2
            """
            params = [int(guild_id), int(category_id)]
            param_counter = 3

            # Apply role filter - ADD THIS SECTION
            if user_ids:
                placeholders = []
                for i in range(len(user_ids)):
                    placeholders.append(f"${param_counter + i}")
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_counter += len(user_ids)

            # Apply time filters
            if start_time:
                query += f" AND hour >= ${param_counter}"
                params.append(start_time)
                param_counter += 1
            if end_time:
                query += f" AND hour <= ${param_counter}"
                params.append(end_time)
                param_counter += 1

            # Apply voice state filter
            query, params = await db_stats._apply_voice_state_filter(query, params, guild_id, 'state_flags')

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')

            # Apply blacklist filters
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'voice_session_history_hourly',
                include_users=True, include_channels=False,
                specific_category_id=category_id
            )

            row = await conn.fetchrow(query, *params)

            total_seconds = row['total_seconds'] if row else 0
            unique_users = row['unique_users'] if row else 0

            return {
                "total_seconds": total_seconds,
                "total_hours": round(total_seconds / 3600, 2),
                "session_count": row['session_count'] if row else 0,
                "unique_users": unique_users,
                "avg_session": 0.0,
                "seconds_per_user": total_seconds / max(unique_users, 1)
            }

    except Exception as e:
        logger.error(f"Error in category_total_voice: {e}")
        logger.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=str(e))

