# LEADERBOARD ENDPOINTS (with error handling)
# ============================================


@app.get("/api/leaderboard/server/top/text-channels")
async def leaderboard_server_top_text_channels(
    guild_id: str,
    limit: int = 100000000000,
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated list of role IDs"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get server's top text channels leaderboard with time filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        guild_id_int = int(guild_id)

        # Parse role_filter_ids if provided
        role_filter_list = None
        if role_filter_ids:
            role_filter_list = [rid.strip()
                                for rid in role_filter_ids.split(',') if rid.strip()]

        async with db_stats.pool.acquire() as conn:
            # First get total messages for percentage calculation
            total_query = """
                SELECT COALESCE(SUM(message_count), 0) as total_messages
                FROM message_tracking_hourly
                WHERE guild_id = $1
            """
            total_params = [guild_id_int]

            # Apply role filtering if needed
            if role_filter_list:
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if user_ids:
                    placeholders = [
                        f"${len(total_params) + i + 1}" for i in range(len(user_ids))]
                    total_query += f" AND user_id IN ({', '.join(placeholders)})"
                    total_params.extend(user_ids)

            # Add time filters
            if start_time:
                total_params.append(start_time)
                total_query += f" AND hour >= ${len(total_params)}"
            if end_time:
                total_params.append(end_time)
                total_query += f" AND hour <= ${len(total_params)}"

            total_row = await conn.fetchrow(total_query, *total_params)
            total_messages = total_row['total_messages'] if total_row else 0

            if total_messages == 0:
                return []

            # Get channel breakdown
            query = """
                SELECT 
                    channel_id,
                    SUM(message_count) as message_count,
                    COALESCE(SUM(total_chars), 0) as total_chars,
                    COUNT(DISTINCT user_id) as unique_users,
                    COALESCE(SUM(total_chars) / NULLIF(SUM(message_count), 0), 0) as avg_chars
                FROM message_tracking_hourly
                WHERE guild_id = $1
            """
            params = [guild_id_int]

            # Apply role filtering
            if role_filter_list and user_ids:
                placeholders = [
                    f"${len(params) + i + 1}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)

            # Add time filters
            if start_time:
                params.append(start_time)
                query += f" AND hour >= ${len(params)}"
            if end_time:
                params.append(end_time)
                query += f" AND hour <= ${len(params)}"

            query += """
                GROUP BY channel_id
                ORDER BY message_count DESC
            """

            # Add LIMIT - use len(params) + 1
            query += f" LIMIT ${len(params) + 1}"
            params.append(limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                channel_messages = row['message_count'] or 0
                percentage = (channel_messages / total_messages *
                              100) if total_messages > 0 else 0
                result.append({
                    'channel_id': str(row['channel_id']),
                    'message_count': channel_messages,
                    'total_chars': row['total_chars'] or 0,
                    'unique_users': row['unique_users'] or 0,
                    'avg_chars': round(row['avg_chars'] or 0, 2),
                    'percentage': round(percentage, 1)
                })

            # Filter out deleted channels
            if result:
                channel_ids = [str(item['channel_id']) for item in result]
                existence_map = await discord_api.verify_entities_exist(
                    guild_id, 'channel', channel_ids
                )

                filtered_result = []
                for item in result:
                    if existence_map.get(str(item['channel_id']), True):
                        filtered_result.append(item)

                result = filtered_result

            return result
    except Exception as e:
        logger.error(f"Error in text channels leaderboard: {e}")
        logger.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/leaderboard/server/top/voice-channels")
async def leaderboard_server_top_voice_channels(
    guild_id: str,
    limit: int = 100000000000,
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated list of role IDs"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    user: Optional[Dict] = Depends(get_current_user)
):
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        guild_id_int = int(guild_id)

        # Parse role_filter_ids if provided
        role_filter_list = None
        if role_filter_ids:
            role_filter_list = [rid.strip()
                                for rid in role_filter_ids.split(',') if rid.strip()]

        # FIX: Pass the time parameters to the database method
        result = await db_stats.q_leaderboard_server_top_voice_channels(
            guild_id=guild_id,
            limit=limit,
            role_filter_ids=role_filter_list,
            start_time=start_time,  # ADD THIS
            end_time=end_time        # ADD THIS
        )

        # Filter out deleted channels
        if result:
            channel_ids = [str(item['channel_id']) for item in result]
            existence_map = await discord_api.verify_entities_exist(
                guild_id, 'channel', channel_ids
            )

            filtered_result = []
            for item in result:
                if existence_map.get(str(item['channel_id']), True):
                    filtered_result.append(item)

            result = filtered_result

        # Convert channel IDs to strings
        for item in result:
            if 'channel_id' in item:
                item['channel_id'] = str(item['channel_id'])
        return result
    except ValueError as e:
        logger.error(f"Invalid ID format: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except Exception as e:
        logger.error(f"Error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


