@app.post("/api/activity/leaderboard", response_model=PaginatedActivityResponse)
async def get_activity_leaderboard(request: LeaderboardActivityRequest):
    """Get activity leaderboard"""
    try:
        # Validate guild_id
        try:
            guild_id_int = int(request.guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400, detail=f"Invalid guild_id format: {request.guild_id}")

        stats = await db_stats.get_leaderboard_stats(
            guild_id=request.guild_id,
            category=request.category,
            days=request.days,
            role_id=request.role_id,
            sort_by=request.sort_by
        )

        # Apply pagination
        start_idx = request.page * request.limit
        end_idx = start_idx + request.limit
        paginated_stats = stats[start_idx:end_idx]

        formatted_stats = []
        for stat in paginated_stats:
            formatted_stats.append(ActivityStatsResponse(
                display_name=stat['display_name'],
                activity_type=stat['activity_type'],
                session_count=stat['session_count'],
                total_duration_seconds=stat['total_duration_seconds'],
                user_count=stat.get('user_count')
            ))

        total_items = len(stats)
        total_pages = (total_items + request.limit - 1) // request.limit

        return PaginatedActivityResponse(
            items=formatted_stats,
            page=request.page,
            total_pages=total_pages,
            total_items=total_items,
            has_next=request.page < total_pages - 1,
            has_previous=request.page > 0
        )
    except ValueError as e:
        logger.error(f"Invalid ID format in get_activity_leaderboard: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except DatabaseError as e:
        logger.error(f"Database error in get_activity_leaderboard: {e}")
        raise HTTPException(status_code=500, detail=str(e))
    except Exception as e:
        logger.error(f"Unexpected error in get_activity_leaderboard: {e}")
        raise HTTPException(status_code=500, detail=str(e))


