@app.get("/api/user/timeseries/voice/daily")
async def user_timeseries_voice_daily(
    guild_id: str,
    user_id: str,
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated list of role IDs"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    max_points: int = Query(
        90, ge=1, le=365, description="Maximum number of data points"),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get daily voice timeseries data for a specific user."""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        guild_id_int = int(guild_id)
        user_id_int = int(user_id)

        # Parse role_filter_ids if provided
        role_filter_list = None
        if role_filter_ids:
            role_filter_list = [rid.strip()
                                for rid in role_filter_ids.split(',') if rid.strip()]

        result = await db_stats.q_user_timeseries_voice_daily(
            guild_id=guild_id,
            user_id=user_id,
            role_filter_ids=role_filter_list,
            start_time=start_time,
            end_time=end_time,
            max_points=max_points
        )

        return result

    except ValueError as e:
        logger.error(f"Invalid ID format: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except Exception as e:
        logger.error(f"Error in user voice daily timeseries: {e}")
        logger.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/channel/timeseries/voice/daily")
async def channel_timeseries_voice_daily(
    guild_id: str,
    channel_id: str,
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated list of role IDs"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    timezone_str: Optional[str] = Query(
        'UTC', description="Timezone for date grouping"),
    max_points: int = Query(90, ge=1, le=365),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get daily voice timeseries data for a specific channel with role, bot, voice state, blacklist, and timezone filtering"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        guild_id_int = int(guild_id)
        channel_id_int = int(channel_id)

        role_filter_list = role_filter_ids.split(
            ',') if role_filter_ids else None

        if not end_time:
            end_time = datetime.utcnow()
        if not start_time:
            start_time = end_time - timedelta(days=max_points)

        days_in_range = (end_time - start_time).days
        if days_in_range > max_points:
            start_time = end_time - timedelta(days=max_points)

        async with db_stats.pool.acquire() as conn:
            user_ids = None
            if role_filter_list:
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    # Return empty result with all dates
                    result = []
                    current_date = start_time.date()
                    end_date_obj = end_time.date()
                    while current_date <= end_date_obj:
                        result.append({
                            "date": current_date.isoformat(),
                            "seconds": 0
                        })
                        current_date += timedelta(days=1)
                    return result

            # Build query with proper WHERE clause from the start
            query = f"""
                SELECT 
                    DATE(hour AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}') as date,
                    COALESCE(SUM(total_seconds), 0) as total_seconds
                FROM voice_session_history_hourly
                WHERE guild_id = $1 
                AND channel_id = $2
                AND hour >= $3 
                AND hour <= $4
            """
            params = [guild_id_int, channel_id_int, start_time, end_time]
            param_index = 5

            # Add role filter if needed (adds to existing WHERE)
            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_index += len(user_ids)

            # Apply voice state filter (adds to existing WHERE)
            query, params = await db_stats._apply_voice_state_filter(query, params, guild_id, 'state_flags')

            # Apply bot filter (adds to existing WHERE)
            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')

            # Apply blacklist filters (adds to existing WHERE)
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'voice_session_history_hourly',
                include_users=True, include_channels=False,
                specific_channel_id=channel_id
            )

            # Add GROUP BY and ORDER BY
            query += " GROUP BY date ORDER BY date ASC"

            rows = await conn.fetch(query, *params)

            data_by_date = {row['date'].isoformat(): row['total_seconds']
                            for row in rows}

            result = []
            current_date = start_time.date()
            end_date_obj = end_time.date()

            while current_date <= end_date_obj:
                date_str = current_date.isoformat()
                result.append({
                    'date': date_str,
                    'seconds': data_by_date.get(date_str, 0)
                })
                current_date += timedelta(days=1)

            return result

    except Exception as e:
        logger.error(f"Error in channel voice daily timeseries: {e}")
        logger.error(traceback.format_exc())
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/category/timeseries/voice/daily")
async def category_timeseries_voice_daily(
    guild_id: str,
    category_id: str,
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated list of role IDs"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    timezone_str: Optional[str] = Query(
        'UTC', description="Timezone for date grouping"),
    max_points: int = Query(90, ge=1, le=365),
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get daily voice timeseries data for a specific category with role, bot, voice state, blacklist, and timezone filtering"""
