# PRIVILEGED SERVER ENDPOINTS
# ============================================

@app.get("/api/admin/lookup-server/{guild_id}")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def admin_lookup_server(
    guild_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Privileged endpoint to look up any server the bot is in by its guild ID.
    Only accessible to users in the PRIVILEGED_USERS list.
    Returns server details if the bot is in that guild.
    """
    # Check if user is authenticated
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    # Check if user is privileged
    PRIVILEGED_USERS = ['1428927519515611141', '591655972414685229']
    if user['discord_id'] not in PRIVILEGED_USERS:
        raise HTTPException(
            status_code=403,
            detail="Access denied. This endpoint is only for privileged users."
        )

    try:
        # Validate guild_id format
        try:
            guild_id_int = int(guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400,
                detail=f"Invalid guild_id format: {guild_id}"
            )

        # Check if bot is in the guild using Discord API
        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
            url = f"{DISCORD_API_BASE}/guilds/{guild_id}?with_counts=true"

            async with session.get(url, headers=headers, timeout=10) as resp:
                if resp.status == 404:
                    return {
                        "success": False,
                        "found": False,
                        "message": f"Server with ID {guild_id} not found or bot is not in this server.",
                        "public": False
                    }
                elif resp.status != 200:
                    error_text = await resp.text()
                    logger.error(
                        f"Failed to fetch guild {guild_id}: {resp.status} - {error_text[:200]}")
                    return {
                        "success": False,
                        "found": False,
                        "message": f"Failed to fetch server information: HTTP {resp.status}",
                        "public": False
                    }

                guild_data = await resp.json()

                # Get bot's member info in this guild (for permissions)
                bot_member_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/members/{CLIENT_ID}"
                bot_permissions = 0
                bot_nick = None

                async with session.get(bot_member_url, headers=headers) as bot_resp:
                    if bot_resp.status == 200:
                        bot_member = await bot_resp.json()
                        bot_permissions = bot_member.get('permissions', 0)
                        bot_nick = bot_member.get('nick')

                # Check if bot has Administrator or Manage Server permissions
                ADMIN_PERMISSION = 0x8
                MANAGE_SERVER_PERMISSION = 0x20

                has_admin = (bot_permissions & ADMIN_PERMISSION) != 0
                has_manage_server = (
                    bot_permissions & MANAGE_SERVER_PERMISSION) != 0

                # Format the server response
                server_info = {
                    "id": str(guild_data['id']),
                    "name": guild_data['name'],
                    "icon": guild_data.get('icon'),
                    "member_count": guild_data.get('approximate_member_count', 0),
                    "owner_id": str(guild_data.get('owner_id', '')),
                    "description": guild_data.get('description'),
                    "features": guild_data.get('features', []),
                    "bot_permissions": bot_permissions,
                    "bot_has_admin": has_admin,
                    "bot_has_manage_server": has_manage_server,
                    "has_bot": True,
                    "icon_url": f"https://cdn.discordapp.com/icons/{guild_id}/{guild_data['icon']}.png?size=128" if guild_data.get('icon') else None
                }

                return {
                    "success": True,
                    "found": True,
                    "server": server_info,
                    "message": f"Found server: {guild_data['name']}",
                    "public": False
                }

    except aiohttp.ClientTimeout:
        logger.error(f"Timeout fetching guild {guild_id}")
        return {
            "success": False,
            "found": False,
            "message": "Request timed out. Please try again.",
            "public": False
        }
    except Exception as e:
        logger.error(f"Error in admin_lookup_server: {e}", exc_info=True)
        return {
            "success": False,
            "found": False,
            "message": f"Error: {str(e)}",
            "public": False
        }


@app.get("/api/admin/bot-servers")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def admin_get_bot_servers(
    user: Optional[Dict] = Depends(get_current_user),
    limit: int = Query(100, ge=1, le=100000000000)
):
    """
    Privileged endpoint to get all servers the bot is in.
    Only accessible to privileged users.
    Returns a list of all guilds the bot is a member of.
    """
    # Check if user is authenticated
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    # Check if user is privileged
    PRIVILEGED_USERS = ['1428927519515611141', '591655972414685229']
    if user['discord_id'] not in PRIVILEGED_USERS:
        raise HTTPException(
            status_code=403,
            detail="Access denied. This endpoint is only for privileged users."
        )

    try:
        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

            # Get bot's guilds (with pagination)
            all_guilds = []
            url = f"{DISCORD_API_BASE}/users/@me/guilds"
            params = {"limit": limit}

            async with session.get(url, headers=headers, params=params) as resp:
                if resp.status != 200:
                    error_text = await resp.text()
                    logger.error(
                        f"Failed to fetch bot guilds: {resp.status} - {error_text[:200]}")
                    return {
                        "success": False,
                        "message": f"Failed to fetch guilds: HTTP {resp.status}",
                        "guilds": []
                    }

                guilds = await resp.json()

                for guild in guilds:
                    guild_info = {
                        "id": str(guild['id']),
                        "name": guild['name'],
                        "icon": guild.get('icon'),
                        "owner": guild.get('owner', False),
                        "permissions": guild.get('permissions', '0'),
                        "features": guild.get('features', []),
                        "approximate_member_count": guild.get('approximate_member_count', 0),
                        "icon_url": f"https://cdn.discordapp.com/icons/{guild['id']}/{guild['icon']}.png?size=128" if guild.get('icon') else None
                    }
                    all_guilds.append(guild_info)

            return {
                "success": True,
                "total": len(all_guilds),
                "guilds": all_guilds,
                "public": False
            }

    except Exception as e:
        logger.error(f"Error in admin_get_bot_servers: {e}", exc_info=True)
        return {
            "success": False,
            "message": f"Error: {str(e)}",
            "guilds": []
        }


@app.post("/api/admin/add-server-to-user")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def admin_add_server_to_user(
    request: Request,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Privileged endpoint to add a server to a user's server list.
    This allows privileged users to save servers they're not a member of.
    """
    body = await request.json()
    guild_id = body.get('guild_id')

    # Check if user is authenticated
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    # Check if user is privileged
    PRIVILEGED_USERS = ['1428927519515611141', '591655972414685229']
    if user['discord_id'] not in PRIVILEGED_USERS:
        raise HTTPException(
            status_code=403,
            detail="Access denied. This endpoint is only for privileged users."
        )

    try:
        # First, verify the bot is in this guild and get server info
        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}
            url = f"{DISCORD_API_BASE}/guilds/{guild_id}?with_counts=true"

            async with session.get(url, headers=headers, timeout=10) as resp:
                if resp.status != 200:
                    raise HTTPException(
                        status_code=404,
                        detail=f"Bot is not in server with ID {guild_id} or server not found."
                    )

                guild_data = await resp.json()

                # Get member count (bot might not have member intent, so approximate)
                member_count = guild_data.get('approximate_member_count', 0)

                # Add the server to user's servers list in database
                # First check if it already exists
                existing_servers = await auth_db.get_user_servers(user['discord_id'])
                existing_ids = [s['guild_id'] for s in existing_servers]

                if guild_id not in existing_ids:
                    # Insert the server into user_servers
                    async with auth_db.pool.acquire() as conn:
                        await conn.execute("""
                            INSERT INTO user_servers (discord_id, guild_id, guild_name, guild_icon, member_count, permissions)
                            VALUES ($1, $2, $3, $4, $5, $6)
                            ON CONFLICT (discord_id, guild_id) DO UPDATE SET
                                guild_name = EXCLUDED.guild_name,
                                guild_icon = EXCLUDED.guild_icon,
                                member_count = EXCLUDED.member_count,
                                permissions = EXCLUDED.permissions,
                                last_updated = CURRENT_TIMESTAMP
                        """,
                                           user['discord_id'],
                                           guild_id,
                                           guild_data['name'],
                                           guild_data.get('icon'),
                                           member_count,
                                           "0"  # Default permissions for privileged user
                                           )

                # Now update the selected server
                await auth_db.update_user_selected_server(user['discord_id'], guild_id)

                # Cache the selected server
                await db_stats.cache_user_server(user['discord_id'], guild_id)

                return {
                    "success": True,
                    "message": f"Server '{guild_data['name']}' added to your list and set as active dashboard.",
                    "server": {
                        "id": guild_id,
                        "name": guild_data['name'],
                        "icon": guild_data.get('icon'),
                        "member_count": member_count,
                        "icon_url": f"https://cdn.discordapp.com/icons/{guild_id}/{guild_data['icon']}.png?size=128" if guild_data.get('icon') else None
                    }
                }

    except aiohttp.ClientTimeout:
        logger.error(f"Timeout adding server {guild_id}")
        raise HTTPException(
            status_code=504, detail="Request timed out. Please try again.")
    except Exception as e:
        logger.error(f"Error in admin_add_server_to_user: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=str(e))

