@app.get("/api/debug/bot-permissions/{guild_id}")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def debug_bot_permissions(
    guild_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Debug endpoint to get ALL permissions the bot has in a specific server.
    """
    # Check if user is authenticated and privileged
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    PRIVILEGED_USERS = ['1428927519515611141', '591655972414685229']
    if user['discord_id'] not in PRIVILEGED_USERS:
        raise HTTPException(status_code=403, detail="Access denied")

    try:
        guild_id_int = int(guild_id)

        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

            # First, try to get bot's roles from the guild endpoint
            # This doesn't require special intents - just basic bot token
            guild_url = f"{DISCORD_API_BASE}/guilds/{guild_id}"
            guild_data = None

            async with session.get(guild_url, headers=headers) as guild_resp:
                if guild_resp.status == 200:
                    guild_data = await guild_resp.json()
                else:
                    error_text = await guild_resp.text()

                    return {
                        "success": False,
                        "error": f"Failed to fetch guild info: HTTP {guild_resp.status}",
                        "bot_in_guild": guild_resp.status == 200
                    }

            # Now try to get bot's member info - this requires the bot to be in the guild
            bot_member_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/members/{CLIENT_ID}"
            bot_permissions = 0
            bot_role_ids = []

            async with session.get(bot_member_url, headers=headers) as member_resp:
                if member_resp.status == 200:
                    bot_member = await member_resp.json()
                    # Discord returns permissions as a STRING
                    perms_str = bot_member.get('permissions', '0')
                    bot_permissions = int(perms_str) if perms_str else 0
                    bot_role_ids = bot_member.get('roles', [])

                else:

                    return {
                        "success": False,
                        "error": f"Bot is not in this guild or missing permissions (HTTP {member_resp.status})",
                        "bot_in_guild": False
                    }

            # Get all roles to understand the permissions
            roles_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/roles"
            async with session.get(roles_url, headers=headers) as roles_resp:
                if roles_resp.status == 200:
                    all_roles = await roles_resp.json()

                    # Calculate permissions from roles if needed
                    calculated_perms = 0
                    for role in all_roles:
                        if role['id'] in bot_role_ids:
                            role_perms_str = role.get('permissions', '0')
                            role_perms = int(
                                role_perms_str) if role_perms_str else 0
                            calculated_perms |= role_perms

                    # Also include @everyone role
                    for role in all_roles:
                        if role['name'] == '@everyone':
                            everyone_perms_str = role.get('permissions', '0')
                            everyone_perms = int(
                                everyone_perms_str) if everyone_perms_str else 0
                            calculated_perms |= everyone_perms

                    # Use the higher of the two (member endpoint should be authoritative)
                    if bot_permissions == 0 and calculated_perms > 0:
                        bot_permissions = calculated_perms

            # Define permission flags
            PERMISSIONS = {
                "CREATE_INSTANT_INVITE": 0x1,
                "KICK_MEMBERS": 0x2,
                "BAN_MEMBERS": 0x4,
                "ADMINISTRATOR": 0x8,
                "MANAGE_CHANNELS": 0x10,
                "MANAGE_GUILD": 0x20,
                "ADD_REACTIONS": 0x40,
                "VIEW_AUDIT_LOG": 0x80,
                "PRIORITY_SPEAKER": 0x100,
                "STREAM": 0x200,
                "VIEW_CHANNEL": 0x400,
                "SEND_MESSAGES": 0x800,
                "SEND_TTS_MESSAGES": 0x1000,
                "MANAGE_MESSAGES": 0x2000,
                "EMBED_LINKS": 0x4000,
                "ATTACH_FILES": 0x8000,
                "READ_MESSAGE_HISTORY": 0x10000,
                "MENTION_EVERYONE": 0x20000,
                "USE_EXTERNAL_EMOJIS": 0x40000,
                "VIEW_GUILD_INSIGHTS": 0x80000,
                "CONNECT": 0x100000,
                "SPEAK": 0x200000,
                "MUTE_MEMBERS": 0x400000,
                "DEAFEN_MEMBERS": 0x800000,
                "MOVE_MEMBERS": 0x1000000,
                "USE_VAD": 0x2000000,
                "CHANGE_NICKNAME": 0x4000000,
                "MANAGE_NICKNAMES": 0x8000000,
                "MANAGE_ROLES": 0x10000000,
                "MANAGE_WEBHOOKS": 0x20000000,
                "MANAGE_EMOJIS_AND_STICKERS": 0x40000000,
                "USE_APPLICATION_COMMANDS": 0x80000000,
                "REQUEST_TO_SPEAK": 0x100000000,
                "MANAGE_EVENTS": 0x200000000,
                "MANAGE_THREADS": 0x400000000,
                "CREATE_PUBLIC_THREADS": 0x800000000,
                "CREATE_PRIVATE_THREADS": 0x1000000000,
                "USE_EXTERNAL_STICKERS": 0x2000000000,
                "SEND_MESSAGES_IN_THREADS": 0x4000000000,
                "USE_EMBEDDED_ACTIVITIES": 0x8000000000,
                "MODERATE_MEMBERS": 0x10000000000
            }

            # Calculate which permissions the bot has
            granted_permissions = []
            for perm_name, perm_value in PERMISSIONS.items():
                if bot_permissions & perm_value:
                    granted_permissions.append({
                        "name": perm_name,
                        "value": perm_value,
                        "bitwise": f"0x{perm_value:X}"
                    })

            has_administrator = (
                bot_permissions & PERMISSIONS["ADMINISTRATOR"]) != 0

            # Get role names for bot's roles
            bot_roles_info = []
            if bot_role_ids:
                roles_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/roles"
                async with session.get(roles_url, headers=headers) as roles_resp2:
                    if roles_resp2.status == 200:
                        all_roles2 = await roles_resp2.json()
                        role_map = {role['id']: role for role in all_roles2}
                        for role_id in bot_role_ids:
                            role = role_map.get(role_id, {})
                            bot_roles_info.append({
                                "id": str(role_id),
                                "name": role.get('name', f"Unknown Role {role_id}"),
                                "position": role.get('position', 0)
                            })

            return {
                "success": True,
                "guild_id": guild_id,
                "guild_name": guild_data.get('name', 'Unknown'),
                "bot_id": CLIENT_ID,
                "permissions_bitfield": bot_permissions,
                "permissions_bitfield_hex": f"0x{bot_permissions:X}",
                "has_administrator": has_administrator,
                "granted_permissions": granted_permissions,
                "total_permissions_count": len(granted_permissions),
                "bot_roles": bot_roles_info,
                "bot_in_guild": True,
                "debug_info": {
                    "permissions_source": "member_endpoint" if bot_permissions > 0 else "calculated_from_roles",
                    "raw_permissions_string": str(bot_permissions)
                }
            }

    except Exception as e:
        logger.error(f"Error in debug_bot_permissions: {e}", exc_info=True)
        return {
            "success": False,
            "error": str(e),
            "bot_in_guild": False
        }


@app.get("/api/debug/find-channel/{guild_id}/{channel_id}")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def debug_find_channel(
    guild_id: str,
    channel_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Debug endpoint to search for a specific channel by ID.
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    PRIVILEGED_USERS = ['1428927519515611141', '591655972414685229']
    if user['discord_id'] not in PRIVILEGED_USERS:
        raise HTTPException(status_code=403, detail="Access denied")

    try:
        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

            # First, check if the channel exists and get basic info
            channel_url = f"{DISCORD_API_BASE}/channels/{channel_id}"
            async with session.get(channel_url, headers=headers) as channel_resp:
                if channel_resp.status == 404:
                    return {
                        "success": True,
                        "channel_found": False,
                        "message": f"Channel with ID {channel_id} not found"
                    }
                elif channel_resp.status != 200:
                    return {
                        "success": False,
                        "error": f"Failed to fetch channel: HTTP {channel_resp.status}",
                        "channel_found": False
                    }

                channel_data = await channel_resp.json()

                # Verify the channel belongs to the specified guild
                if str(channel_data.get('guild_id')) != guild_id:
                    return {
                        "success": True,
                        "channel_found": False,
                        "message": f"Channel exists but is not in guild {guild_id}"
                    }

                # Get channel type
                CHANNEL_TYPES = {
                    0: "GUILD_TEXT",
                    2: "GUILD_VOICE",
                    4: "GUILD_CATEGORY",
                    5: "GUILD_ANNOUNCEMENT",
                    13: "GUILD_STAGE_VOICE",
                    15: "GUILD_FORUM",
                    16: "GUILD_MEDIA"
                }

                channel_type = CHANNEL_TYPES.get(
                    channel_data.get('type', 0), "UNKNOWN")

                # Get bot's permissions - we can view the channel since we fetched it successfully
                can_view = True
                can_send_messages = False
                can_read_history = False
                can_connect = False
                can_speak = False

                # For text channels, try to fetch messages to check permissions
                if channel_type == "GUILD_TEXT":
                    messages_url = f"{DISCORD_API_BASE}/channels/{channel_id}/messages?limit=1"
                    async with session.get(messages_url, headers=headers) as msg_resp:
                        if msg_resp.status == 200:
                            can_read_history = True
                            # If we can read, we likely can send (not always true but indicative)
                            can_send_messages = True
                        elif msg_resp.status == 403:
                            # Forbidden - means we can view but can't read messages
                            can_read_history = False
                            can_send_messages = False

                # For voice channels, try to get voice states
                elif channel_type == "GUILD_VOICE":
                    voice_states_url = f"{DISCORD_API_BASE}/channels/{channel_id}/voice-states"
                    async with session.get(voice_states_url, headers=headers) as vs_resp:
                        if vs_resp.status == 200:
                            can_connect = True
                            can_speak = True

                # Get parent category if exists
                parent_category = None
                if channel_data.get('parent_id'):
                    parent_url = f"{DISCORD_API_BASE}/channels/{channel_data['parent_id']}"
                    async with session.get(parent_url, headers=headers) as parent_resp:
                        if parent_resp.status == 200:
                            parent_data = await parent_resp.json()
                            parent_category = {
                                "id": str(parent_data['id']),
                                "name": parent_data.get('name')
                            }

                # Get channel permission overwrites (roles and members with specific permissions)
                overwrites_list = []
                overwrites_url = f"{DISCORD_API_BASE}/channels/{channel_id}/permissions"
                async with session.get(overwrites_url, headers=headers) as overwrites_resp:
                    if overwrites_resp.status == 200:
                        overwrites = await overwrites_resp.json()
                        for ow in overwrites:
                            ow_type = "Role" if ow['type'] == 0 else "Member"
                            overwrites_list.append({
                                "type": ow_type,
                                "id": str(ow['id']),
                                "allow": int(ow.get('allow', '0')),
                                "deny": int(ow.get('deny', '0'))
                            })

                # Build response
                result = {
                    "success": True,
                    "channel_found": True,
                    "channel": {
                        "id": str(channel_data['id']),
                        "name": channel_data.get('name'),
                        "type": channel_type,
                        "position": channel_data.get('position'),
                        "parent_category": parent_category,
                        "topic": channel_data.get('topic'),
                        "nsfw": channel_data.get('nsfw', False),
                        "bitrate": channel_data.get('bitrate'),
                        "user_limit": channel_data.get('user_limit'),
                        "rate_limit_per_user": channel_data.get('rate_limit_per_user')
                    },
                    "bot_permissions": {
                        "can_view": can_view,
                        "can_send_messages": can_send_messages,
                        "can_read_history": can_read_history,
                        "can_connect": can_connect,
                        "can_speak": can_speak
                    },
                    "channel_overwrites": overwrites_list
                }

                return result

    except Exception as e:
        logger.error(f"Error in debug_find_channel: {e}", exc_info=True)
        return {
            "success": False,
            "error": str(e),
            "channel_found": False
        }


@app.get("/api/debug/find-category/{guild_id}/{category_id}")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def debug_find_category(
    guild_id: str,
    category_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Debug endpoint to search for a specific category by ID in a guild.
    Returns detailed category information including all channels in it.
    Only accessible to privileged users.
    """
    # Check if user is authenticated
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    # Check if user is privileged
    PRIVILEGED_USERS = ['1428927519515611141', '591655972414685229']
    if user['discord_id'] not in PRIVILEGED_USERS:
        raise HTTPException(
            status_code=403,
            detail="Access denied. This endpoint is only for privileged users."
        )

    try:
        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

            # Get all channels in the guild
            channels_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/channels"

            async with session.get(channels_url, headers=headers, timeout=10) as resp:
                if resp.status != 200:
                    return {
                        "success": False,
                        "error": f"Failed to fetch guild channels: HTTP {resp.status}",
                        "category_found": False
                    }

                all_channels = await resp.json()

                # Search for the specific category (type 4)
                target_category = None
                channels_in_category = []
                channels_without_permission = []

                for channel in all_channels:
                    if channel.get('type') == 4 and str(channel['id']) == category_id:
                        target_category = channel
                    elif target_category and channel.get('parent_id') == int(category_id):
                        # For each channel, check if bot can view it
                        channels_in_category.append(channel)

                if not target_category:
                    return {
                        "success": True,
                        "category_found": False,
                        "message": f"Category with ID {category_id} not found in guild {guild_id}"
                    }

                # Get bot's permissions to check which channels are visible
                bot_member_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/members/{CLIENT_ID}"
                guild_permissions = 0
                bot_role_ids = []

                async with session.get(bot_member_url, headers=headers) as bot_resp:
                    if bot_resp.status == 200:
                        bot_member = await bot_resp.json()
                        perms_str = bot_member.get('permissions', '0')
                        guild_permissions = int(perms_str) if perms_str else 0
                        bot_role_ids = [int(rid)
                                        for rid in bot_member.get('roles', [])]

                # Get role hierarchy for permission calculation
                roles_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/roles"
                role_positions = {}

                async with session.get(roles_url, headers=headers) as roles_resp:
                    if roles_resp.status == 200:
                        roles_data = await roles_resp.json()
                        for role in roles_data:
                            role_positions[role['id']] = role.get(
                                'position', 0)

                # Define channel types
                CHANNEL_TYPES = {
                    0: "GUILD_TEXT",
                    2: "GUILD_VOICE",
                    5: "GUILD_ANNOUNCEMENT",
                    13: "GUILD_STAGE_VOICE",
                    15: "GUILD_FORUM",
                    16: "GUILD_MEDIA"
                }

                # Format channels and check visibility
                VIEW_CHANNEL = 0x400
                formatted_channels = []
                hidden_channels = []

                for ch in channels_in_category:
                    # Calculate effective permissions for this channel
                    effective_permissions = guild_permissions

                    # Get channel overwrites
                    channel_perms_url = f"{DISCORD_API_BASE}/channels/{ch['id']}/permissions"
                    async with session.get(channel_perms_url, headers=headers) as perm_resp:
                        if perm_resp.status == 200:
                            overwrites = await perm_resp.json()

                            # Apply @everyone overwrites first
                            for ow in overwrites:
                                if ow['type'] == 0 and ow['id'] == int(guild_id):
                                    allow = int(ow.get('allow', '0'))
                                    deny = int(ow.get('deny', '0'))
                                    effective_permissions = (
                                        effective_permissions & ~deny) | allow
                                    break

                            # Apply bot's role overwrites (sorted by position)
                            bot_roles_sorted = []
                            for role_id in bot_role_ids:
                                if role_id in role_positions:
                                    bot_roles_sorted.append(
                                        (role_positions[role_id], role_id))
                            bot_roles_sorted.sort(
                                key=lambda x: x[0], reverse=True)

                            for _, role_id in bot_roles_sorted:
                                for ow in overwrites:
                                    if ow['type'] == 0 and ow['id'] == role_id:
                                        allow = int(ow.get('allow', '0'))
                                        deny = int(ow.get('deny', '0'))
                                        effective_permissions = (
                                            effective_permissions & ~deny) | allow
                                        break

                            # Apply bot-specific member overwrite
                            for ow in overwrites:
                                if ow['type'] == 1 and str(ow['id']) == CLIENT_ID:
                                    allow = int(ow.get('allow', '0'))
                                    deny = int(ow.get('deny', '0'))
                                    effective_permissions = (
                                        effective_permissions & ~deny) | allow
                                    break

                    can_view = bool(effective_permissions & VIEW_CHANNEL)

                    channel_info = {
                        "id": str(ch['id']),
                        "name": ch.get('name'),
                        "type": CHANNEL_TYPES.get(ch.get('type', 0), f"UNKNOWN({ch.get('type')})"),
                        "position": ch.get('position'),
                        "nsfw": ch.get('nsfw', False),
                        "topic": ch.get('topic') if ch.get('type') in [0, 5, 15] else None,
                        "bitrate": ch.get('bitrate') if ch.get('type') == 2 else None,
                        "user_limit": ch.get('user_limit') if ch.get('type') == 2 else None,
                        "can_view": can_view
                    }

                    if can_view:
                        formatted_channels.append(channel_info)
                    else:
                        hidden_channels.append(channel_info)

                # Sort channels by position
                formatted_channels.sort(key=lambda x: x.get('position', 0))
                hidden_channels.sort(key=lambda x: x.get('position', 0))

                return {
                    "success": True,
                    "category_found": True,
                    "category": {
                        "id": str(target_category['id']),
                        "name": target_category.get('name'),
                        "type": "GUILD_CATEGORY",
                        "position": target_category.get('position'),
                        "nsfw": target_category.get('nsfw', False)
                    },
                    "channels_in_category": formatted_channels,
                    "hidden_channels": hidden_channels,
                    "total_channels": len(channels_in_category),
                    "visible_channels": len(formatted_channels),
                    "hidden_channels_count": len(hidden_channels)
                }

    except aiohttp.ClientTimeout:
        logger.error(
            f"Timeout finding category {category_id} in guild {guild_id}")
        return {
            "success": False,
            "error": "Request timed out. Please try again.",
            "category_found": False
        }
    except Exception as e:
        logger.error(f"Error in debug_find_category: {e}", exc_info=True)
        return {
            "success": False,
            "error": str(e),
            "category_found": False
        }


@app.get("/api/debug/roles/{guild_id}")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def debug_roles(
    guild_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Debug endpoint to get all roles in a guild with their order and bot's role position.
    Returns roles sorted by position (highest first) including bot's role info.
    Only accessible to privileged users.
    """
    # Check if user is authenticated
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    # Check if user is privileged
    PRIVILEGED_USERS = ['1428927519515611141', '591655972414685229']
    if user['discord_id'] not in PRIVILEGED_USERS:
        raise HTTPException(
            status_code=403,
            detail="Access denied. This endpoint is only for privileged users."
        )

    try:
        # Validate guild_id
        try:
            guild_id_int = int(guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400,
                detail=f"Invalid guild_id format: {guild_id}"
            )

        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

            # Get all roles in the guild
            roles_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/roles"

            async with session.get(roles_url, headers=headers, timeout=10) as resp:
                if resp.status != 200:
                    return {
                        "success": False,
                        "error": f"Failed to fetch guild roles: HTTP {resp.status}"
                    }

                all_roles = await resp.json()

                # Get bot's member info to find bot's roles
                bot_member_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/members/{CLIENT_ID}"
                bot_role_ids = []
                bot_role_positions = []

                async with session.get(bot_member_url, headers=headers) as bot_resp:
                    if bot_resp.status == 200:
                        bot_member = await bot_resp.json()
                        bot_role_ids = [str(role_id)
                                        for role_id in bot_member.get('roles', [])]

                # Sort roles by position (higher position = higher in hierarchy)
                sorted_roles = sorted(all_roles, key=lambda r: r.get(
                    'position', 0), reverse=True)

                # Format roles with their hierarchy position
                formatted_roles = []
                bot_roles_info = []
                bot_highest_role = None
                bot_position_index = None

                for idx, role in enumerate(sorted_roles):
                    role_id = str(role['id'])
                    is_bot_role = role_id in bot_role_ids
                    is_everyone_role = role['name'] == '@everyone'

                    # Handle permissions - could be string or int
                    permissions_raw = role.get('permissions', 0)
                    try:
                        permissions_int = int(permissions_raw)
                        permissions_hex = f"0x{permissions_int:X}"
                    except (ValueError, TypeError):
                        permissions_int = 0
                        permissions_hex = "0x0"

                    # Calculate color hex
                    color_raw = role.get('color', 0)
                    try:
                        color_hex = f"#{color_raw:06x}" if color_raw > 0 else "#99aab5"
                    except (ValueError, TypeError):
                        color_hex = "#99aab5"

                    role_info = {
                        "position_order": idx + 1,
                        "id": role_id,
                        "name": role['name'],
                        "color": color_hex,
                        "color_raw": color_raw if isinstance(color_raw, int) else 0,
                        "hoist": role.get('hoist', False),
                        "mentionable": role.get('mentionable', False),
                        "permissions": permissions_int,
                        "permissions_hex": permissions_hex,
                        "managed": role.get('managed', False),
                        "is_bot_role": is_bot_role,
                        "is_everyone_role": is_everyone_role
                    }
                    formatted_roles.append(role_info)

                    if is_bot_role:
                        bot_roles_info.append(role_info)
                        if not bot_highest_role or role.get('position', 0) > bot_highest_role.get('position', 0):
                            bot_highest_role = role_info
                            bot_position_index = idx + 1

                # Get bot's role hierarchy summary
                bot_role_summary = {
                    "has_roles": len(bot_roles_info) > 0,
                    "total_bot_roles": len(bot_roles_info),
                    "highest_role": bot_highest_role,
                    "highest_role_position": bot_position_index,
                    "bot_roles": bot_roles_info
                }

                # Calculate bot's effective permissions (combined from all roles + @everyone)
                bot_effective_permissions = 0
                for role in all_roles:
                    role_perms = role.get('permissions', 0)
                    try:
                        perm_int = int(role_perms)
                    except (ValueError, TypeError):
                        perm_int = 0

                    if str(role['id']) in bot_role_ids or role['name'] == '@everyone':
                        bot_effective_permissions |= perm_int

                # Check if bot has Administrator (overrides everything)
                ADMIN_PERMISSION = 0x8
                bot_has_administrator = (
                    bot_effective_permissions & ADMIN_PERMISSION) != 0

                return {
                    "success": True,
                    "guild_id": guild_id,
                    "total_roles": len(formatted_roles),
                    "roles": formatted_roles,
                    "bot_role_summary": bot_role_summary,
                    "bot_effective_permissions": bot_effective_permissions,
                    "bot_effective_permissions_hex": f"0x{bot_effective_permissions:X}",
                    "bot_has_administrator": bot_has_administrator,
                    "role_hierarchy_note": "Roles are sorted from highest position (top of hierarchy) to lowest position (bottom of hierarchy). Higher position value = higher in hierarchy."
                }

    except aiohttp.ClientTimeout:
        logger.error(f"Timeout fetching roles for guild {guild_id}")
        return {
            "success": False,
            "error": "Request timed out. Please try again."
        }
    except Exception as e:
        logger.error(f"Error in debug_roles: {e}", exc_info=True)
        return {
            "success": False,
            "error": str(e)
        }


@app.get("/api/debug/bot-role-hierarchy/{guild_id}")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def debug_bot_role_hierarchy(
    guild_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """
    Simplified debug endpoint to get bot's role hierarchy position.
    Returns just the essential information about bot's role position.
    Only accessible to privileged users.
    """
    # Check if user is authenticated
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    # Check if user is privileged
    PRIVILEGED_USERS = ['1428927519515611141', '591655972414685229']
    if user['discord_id'] not in PRIVILEGED_USERS:
        raise HTTPException(
            status_code=403,
            detail="Access denied. This endpoint is only for privileged users."
        )

    try:
        # Validate guild_id
        try:
            guild_id_int = int(guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400,
                detail=f"Invalid guild_id format: {guild_id}"
            )

        async with aiohttp.ClientSession() as session:
            headers = {'Authorization': f'Bot {DISCORD_TOKEN}'}

            # Get all roles
            roles_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/roles"

            async with session.get(roles_url, headers=headers, timeout=10) as resp:
                if resp.status != 200:
                    return {
                        "success": False,
                        "error": f"Failed to fetch guild roles: HTTP {resp.status}"
                    }

                all_roles = await resp.json()

                # Get bot's roles
                bot_member_url = f"{DISCORD_API_BASE}/guilds/{guild_id}/members/{CLIENT_ID}"
                bot_role_ids = []

                async with session.get(bot_member_url, headers=headers) as bot_resp:
                    if bot_resp.status == 200:
                        bot_member = await bot_resp.json()
                        bot_role_ids = [str(role_id)
                                        for role_id in bot_member.get('roles', [])]

                # Sort roles by position (highest first)
                sorted_roles = sorted(all_roles, key=lambda r: r.get(
                    'position', 0), reverse=True)

                # Find bot's highest role position
                bot_highest_role_position = None
                bot_highest_role_name = None
                bot_highest_role_id = None
                bot_position_index = None

                for idx, role in enumerate(sorted_roles):
                    if str(role['id']) in bot_role_ids:
                        if bot_highest_role_position is None or role.get('position', 0) > bot_highest_role_position:
                            bot_highest_role_position = role.get('position', 0)
                            bot_highest_role_name = role['name']
                            bot_highest_role_id = str(role['id'])
                            bot_position_index = idx + 1

                # Get total role count
                total_roles = len(sorted_roles)

                # Get @everyone role position (always lowest)
                everyone_position = None
                for idx, role in enumerate(sorted_roles):
                    if role['name'] == '@everyone':
                        everyone_position = idx + 1
                        break

                return {
                    "success": True,
                    "guild_id": guild_id,
                    "bot_has_roles": len(bot_role_ids) > 0,
                    "bot_role_count": len(bot_role_ids),
                    "bot_highest_role": {
                        "id": bot_highest_role_id,
                        "name": bot_highest_role_name,
                        "position": bot_highest_role_position,
                        "hierarchy_index": bot_position_index,
                        "out_of_total_roles": total_roles
                    },
                    "total_roles": total_roles,
                    "everyone_role_position": everyone_position,
                    "message": f"Bot's highest role is at position {bot_position_index} out of {total_roles} roles (1 = highest, {total_roles} = lowest)"
                }

    except Exception as e:
        logger.error(f"Error in debug_bot_role_hierarchy: {e}", exc_info=True)
        return {
            "success": False,
            "error": str(e)
        }
        

@app.get("/api/admin/diagnostics/db-size")
async def admin_db_size(user: Dict = Depends(require_admin)):
    async with db_stats.pool.acquire() as conn:
        rows = await conn.fetch("""
            SELECT relname AS table_name,
                   pg_size_pretty(pg_total_relation_size(relid)) AS size,
                   pg_total_relation_size(relid) AS bytes
            FROM pg_catalog.pg_statio_user_tables
            ORDER BY bytes DESC
        """)
        total = await conn.fetchval(
            "SELECT pg_size_pretty(pg_database_size(current_database()))"
        )
        restart_count = await conn.fetchval(
            "SELECT value FROM bot_diagnostics WHERE key = 'restart_count'"
        )
        last_restart = await conn.fetchval(
            "SELECT value FROM bot_diagnostics WHERE key = 'last_restart_at'"
        )
    return {
        "total_db_size": total,
        "tables": [dict(r) for r in rows],
        "restart_count": int(restart_count or 0),
        "last_restart_at": last_restart,
    }


@app.get("/api/admin/diagnostics/sync-jobs")
async def admin_sync_jobs(user: Dict = Depends(require_admin)):
    async with db_stats.pool.acquire() as conn:
        rows = await conn.fetch("""
            SELECT
                job_type,
                COUNT(*) FILTER (WHERE status = 'success') AS success_count,
                COUNT(*) FILTER (WHERE status = 'failed') AS failed_count,
                MAX(ran_at) AS last_run_at,
                AVG(duration_ms) AS avg_duration_ms,
                PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY duration_ms) AS p50_duration_ms,
                PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY duration_ms) AS p95_duration_ms
            FROM sync_job_runs
            GROUP BY job_type
            ORDER BY last_run_at DESC
        """)
    return {"jobs": [dict(r) for r in rows]}


@app.get("/api/admin/diagnostics/batch-writes")
async def admin_batch_writes(user: Dict = Depends(require_admin)):
    async with db_stats.pool.acquire() as conn:
        rows = await conn.fetch("""
            SELECT
                batch_type,
                SUM(successful_count) AS total_success,
                SUM(failed_count) AS total_failed,
                COUNT(*) AS total_flushes,
                MAX(ran_at) AS last_flush_at
            FROM batch_write_runs
            GROUP BY batch_type
            ORDER BY last_flush_at DESC
        """)
    return {"batches": [dict(r) for r in rows]}


@app.get("/api/admin/diagnostics/business")
async def admin_business_metrics(user: Dict = Depends(require_admin)):
    async with db_stats.pool.acquire() as conn:
        mrr = await conn.fetchval("""
            SELECT COALESCE(SUM(
                CASE WHEN billing_cycle = 'yearly' THEN final_price_usd / 12
                     ELSE final_price_usd END
            ), 0)
            FROM subscriptions WHERE status = 'active'
        """)
        active_by_tier = await conn.fetch("""
            SELECT COALESCE(m.module_key, t.tier_key) AS product,
                   s.billing_cycle, COUNT(*) AS count
            FROM subscriptions s
            LEFT JOIN modules m ON s.module_id = m.id
            LEFT JOIN tiers t ON s.tier_id = t.id
            WHERE s.status = 'active'
            GROUP BY product, s.billing_cycle
        """)
        churn_30d = await conn.fetchval("""
            SELECT COUNT(*) FROM subscriptions
            WHERE status = 'canceled' AND canceled_at > NOW() - INTERVAL '30 days'
        """)
        new_30d = await conn.fetchval("""
            SELECT COUNT(*) FROM subscriptions WHERE created_at > NOW() - INTERVAL '30 days'
        """)
        total_revenue = await conn.fetchval("""
            SELECT COALESCE(SUM(amount_usd), 0) FROM payment_transactions
            WHERE status = 'completed'
        """)
        top_spenders = await conn.fetch("""
            SELECT discord_id, guild_id, SUM(amount_usd) AS total_paid
            FROM payment_transactions
            WHERE status = 'completed'
            GROUP BY discord_id, guild_id
            ORDER BY total_paid DESC
            LIMIT 20
        """)
        by_guild = await conn.fetch("""
            SELECT s.guild_id, s.guild_name,
                   COALESCE(m.module_key, t.tier_key) AS product,
                   s.billing_cycle, s.status
            FROM subscriptions s
            LEFT JOIN modules m ON s.module_id = m.id
            LEFT JOIN tiers t ON s.tier_id = t.id
            WHERE s.status = 'active'
            ORDER BY s.guild_id
        """)
        discount_dist = await conn.fetch("""
            SELECT server_count_at_purchase, discount_pct, COUNT(*) AS count
            FROM subscriptions
            WHERE status = 'active'
            GROUP BY server_count_at_purchase, discount_pct
            ORDER BY server_count_at_purchase
        """)

    churn_rate = round((churn_30d / max(new_30d + churn_30d, 1)) * 100, 2)

    return {
        "mrr": float(mrr),
        "active_by_tier": [dict(r) for r in active_by_tier],
        "churned_last_30d": churn_30d,
        "new_last_30d": new_30d,
        "churn_rate_pct": churn_rate,
        "total_revenue_all_time": float(total_revenue),
        "top_spenders": [dict(r) for r in top_spenders],
        "subscriptions_by_guild": [dict(r) for r in by_guild],
        "discount_distribution": [dict(r) for r in discount_dist],
    }


