@app.get("/api/public/statshq/stats", response_model=PublicStatsHQStatsResponse)
async def public_statshq_stats():
    """Get overall StatsHQ statistics (public endpoint)"""
    try:
        # Get total messages
        messages_result = await db_stats.q_server_total_messages(
            guild_id=STATSHQ_GUILD_ID
        )

        # Get total voice
        voice_result = await db_stats.q_server_total_voice(
            guild_id=STATSHQ_GUILD_ID
        )

        # Get top channels - SEPARATE them
        top_text_channels = await db_stats.q_server_top_text_channels(
            guild_id=STATSHQ_GUILD_ID,
            limit=3
        )

        top_voice_channels = await db_stats.q_server_top_voice_channels(
            guild_id=STATSHQ_GUILD_ID,
            limit=3
        )

        # Get top users
        top_users_messages = await db_stats.q_server_top_users_messages(
            guild_id=STATSHQ_GUILD_ID,
            limit=50
        )

        # Format response - UPDATED to match new model
        return PublicStatsHQStatsResponse(
            guild_id=STATSHQ_GUILD_ID,
            guild_name=STATSHQ_GUILD_NAME,
            total_members=STATSHQ_MEMBER_COUNT,
            total_messages=messages_result.get('total_messages', 0),
            total_voice_hours=voice_result.get('total_hours', 0.0),
            total_users_active=len(top_users_messages),
            top_text_channels=top_text_channels,  # <- Separate field
            top_voice_channels=top_voice_channels,  # <- Separate field
            top_users=top_users_messages
        )
    except DatabaseError as e:
        logger.error(f"Database error in public_statshq_stats: {e}")
        # Return empty stats on error
        return PublicStatsHQStatsResponse(
            guild_id=STATSHQ_GUILD_ID,
            guild_name=STATSHQ_GUILD_NAME,
            total_members=0,
            total_messages=0,
            total_voice_hours=0.0,
            total_users_active=0,
            top_text_channels=[],  # <- Empty list
            top_voice_channels=[],  # <- Empty list
            top_users=[]
        )
    except Exception as e:
        logger.error(f"Unexpected error in public_statshq_stats: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/public/messages/users")
async def public_get_users(
    guild_id: str = Query(..., description="Guild ID"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format"),
    days_back: Optional[int] = Query(None, description="Days to look back")
):
    """Public endpoint to get users in a guild - only works for public StatsHQ guild"""

    # Only allow access to the public StatsHQ guild
    if guild_id != STATSHQ_GUILD_ID:
        raise HTTPException(
            status_code=403, detail="Access denied. This endpoint is only for public StatsHQ statistics.")

    try:
        async with db_stats.pool.acquire() as conn:
            # Build query with time filters
            query = """
                SELECT DISTINCT user_id
                FROM message_tracking_hourly
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_index = 2

            # Add time filtering
            if start_time and end_time:
                query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                params.append(start_time)
                params.append(end_time)
            elif start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
            elif end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)
            elif days_back:
                query += f" AND hour >= NOW() - INTERVAL '1 day' * ${param_index}"
                params.append(days_back)

            query += " ORDER BY user_id"

            rows = await conn.fetch(query, *params)
            user_ids = [str(row['user_id']) for row in rows]

            return {
                "user_ids": user_ids,
                "count": len(user_ids),
                "public": True,
                "guild_id": STATSHQ_GUILD_ID,
                "guild_name": STATSHQ_GUILD_NAME
            }

    except Exception as e:
        logger.error(f"Error in public_get_users: {e}")
        return {"user_ids": [], "count": 0, "public": True, "error": str(e)}


