@app.post("/api/public/server/activity/distribution")
async def public_server_activity_distribution(request: Request):
    """Public endpoint for server's hourly voice distribution with role, bot, and blacklist filtering - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')
        days_back = body.get('days_back', 30)
        role_filter_ids = body.get('role_filter_ids')
        timezone_str = body.get('timezone_str', 'UTC')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(
                status_code=403, detail="Access denied. This endpoint is only for public StatsHQ statistics.")

        voice_by_hour = {f"hour_{i}": 0 for i in range(24)}
        total_seconds = 0

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering if needed
            user_ids = None
            if role_filter_ids:
                if isinstance(role_filter_ids, str):
                    role_filter_list = [
                        rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
                else:
                    role_filter_list = role_filter_ids
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return {"voice": {f"hour_{i}": 0 for i in range(24)}, "total_seconds": 0, "public": True}

            if days_back == 0:
                query = f"""
                    SELECT 
                        EXTRACT(HOUR FROM hour AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}') as hour_of_day,
                        COALESCE(SUM(total_seconds), 0) as total_seconds
                    FROM voice_session_history_hourly
                    WHERE guild_id = $1
                """
                params = [int(guild_id)]
            else:
                query = f"""
                    SELECT 
                        EXTRACT(HOUR FROM hour AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}') as hour_of_day,
                        COALESCE(SUM(total_seconds), 0) as total_seconds
                    FROM voice_session_history_hourly
                    WHERE guild_id = $1
                    AND hour >= NOW() - INTERVAL '{days_back} days'
                """
                params = [int(guild_id)]

            param_index = 2

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_index += len(user_ids)

            query, params = await db_stats._apply_voice_state_filter(query, params, guild_id, 'state_flags')
            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'voice_session_history_hourly',
                include_users=True, include_channels=True
            )

            query += " GROUP BY hour_of_day ORDER BY hour_of_day"

            rows = await conn.fetch(query, *params)

            for row in rows:
                hour = int(row['hour_of_day'])
                seconds = row['total_seconds'] or 0
                voice_by_hour[f"hour_{hour}"] = seconds
                total_seconds += seconds

            return {
                "voice": voice_by_hour,
                "total_seconds": total_seconds,
                "public": True
            }

    except Exception as e:
        logger.error(f"Error in public_server_activity_distribution: {e}")
        return {"voice": {f"hour_{i}": 0 for i in range(24)}, "total_seconds": 0, "public": True}


@app.post("/api/public/server/stats/messages")
async def public_server_stats_messages(request: Request):
    """Public endpoint for server message statistics with role, bot, and blacklist filtering - only works for public StatsHQ guild"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')
        role_filter_ids = body.get('role_filter_ids')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(
                status_code=403, detail="Access denied. This endpoint is only for public StatsHQ statistics.")

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering if needed
            user_ids = None
            if role_filter_ids:
                if isinstance(role_filter_ids, str):
                    role_filter_list = [
                        rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
                else:
                    role_filter_list = role_filter_ids
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return {"total_messages": 0, "unique_users": 0, "public": True}

            query = """
                SELECT 
                    COALESCE(SUM(message_count), 0) as total_messages,
                    COUNT(DISTINCT user_id) as unique_users
                FROM message_tracking_hourly
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_index = 2

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_index += len(user_ids)

            if start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
                param_index += 1
            if end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)
                param_index += 1

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'message_tracking_hourly',
                include_users=True, include_channels=True
            )

            row = await conn.fetchrow(query, *params)

            return {
                "total_messages": row['total_messages'] or 0,
                "unique_users": row['unique_users'] or 0,
                "public": True
            }

    except Exception as e:
        logger.error(f"Error in public_server_stats_messages: {e}")
        return {"total_messages": 0, "unique_users": 0, "public": True, "error": str(e)}


@app.get("/api/public/server/top/users/messages")
async def public_server_top_users_messages(
    limit: int = Query(10, ge=1, le=100000000000),
    role_filter_ids: Optional[str] = Query(
        None, description="Comma-separated role IDs"),
    start_time: Optional[datetime] = Query(
        None, description="Start time ISO format"),
    end_time: Optional[datetime] = Query(
        None, description="End time ISO format")
):
    """Public endpoint for top users by messages - only works for StatsHQ"""
    try:
        guild_id = STATSHQ_GUILD_ID
        guild_id_int = int(guild_id)

        role_filter_list = role_filter_ids.split(
            ',') if role_filter_ids else None

        async with db_stats.pool.acquire() as conn:
            # Get blacklisted users
            blacklists = await db_stats._get_cached_blacklists(guild_id_int)
            blacklisted_user_ids = set(blacklists['users'])

            # Get users with roles if filtering
            allowed_user_ids = None
            if role_filter_list:
                allowed_user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not allowed_user_ids:
                    return {'data': [], 'has_more': False}
                allowed_user_ids = set(allowed_user_ids)

            # First get total messages
            total_query = """
                SELECT COALESCE(SUM(message_count), 0) as total_messages
                FROM message_tracking_hourly
                WHERE guild_id = $1
            """
            total_params = [guild_id_int]

            total_query, total_params = await db_stats._apply_bot_filter(total_query, total_params, guild_id, 'message_tracking_hourly')

            if allowed_user_ids:
                placeholders = [
                    f"${len(total_params) + i + 1}" for i in range(len(allowed_user_ids))]
                total_query += f" AND user_id IN ({', '.join(placeholders)})"
                total_params.extend(allowed_user_ids)

            if start_time:
                total_params.append(start_time)
                total_query += f" AND hour >= ${len(total_params)}"
            if end_time:
                total_params.append(end_time)
                total_query += f" AND hour <= ${len(total_params)}"

            if blacklisted_user_ids:
                placeholders = [
                    f"${len(total_params) + i + 1}" for i in range(len(blacklisted_user_ids))]
                total_query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                total_params.extend(blacklisted_user_ids)

            total_row = await conn.fetchrow(total_query, *total_params)
            total_messages = total_row['total_messages'] if total_row else 0

            if total_messages == 0:
                return {'data': [], 'has_more': False}

            # Get user breakdown
            query = """
                SELECT 
                    user_id,
                    SUM(message_count) as message_count,
                    COALESCE(SUM(total_chars), 0) as total_chars,
                    COALESCE(SUM(total_chars) / NULLIF(SUM(message_count), 0), 0) as avg_chars
                FROM message_tracking_hourly
                WHERE guild_id = $1
            """
            params = [guild_id_int]

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')

            if allowed_user_ids:
                placeholders = [
                    f"${len(params) + i + 1}" for i in range(len(allowed_user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(allowed_user_ids)

            if start_time:
                params.append(start_time)
                query += f" AND hour >= ${len(params)}"
            if end_time:
                params.append(end_time)
                query += f" AND hour <= ${len(params)}"

            if blacklisted_user_ids:
                placeholders = [
                    f"${len(params) + i + 1}" for i in range(len(blacklisted_user_ids))]
                query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                params.extend(blacklisted_user_ids)

            query += " GROUP BY user_id ORDER BY message_count DESC LIMIT $"
            query += str(len(params) + 1)
            params.append(limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                user_messages = row['message_count'] or 0
                percentage = (user_messages / total_messages *
                              100) if total_messages > 0 else 0
                result.append({
                    'user_id': str(row['user_id']),
                    'message_count': user_messages,
                    'total_chars': row['total_chars'] or 0,
                    'avg_chars': round(row['avg_chars'] or 0, 2),
                    'percentage': round(percentage, 1)
                })

            return {'data': result, 'has_more': len(result) == limit}

    except Exception as e:
        logger.error(f"Error in public_server_top_users_messages: {e}")
        return {'data': [], 'has_more': False}


