@app.post("/api/public/emoji/category/top/channels")
async def public_emoji_category_top_channels(request: Request):
    """Public endpoint for category's top channels by emoji usage with role, bot, and blacklist filtering - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')

        # Only allow StatsHQ guild
        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(status_code=403, detail="Access denied.")

        category_id = body.get('category_id')
        limit = body.get('limit', 20)
        usage_type = body.get('usage_type')
        role_filter_ids = body.get('role_filter_ids')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')

        # Convert dates
        start_time = None
        end_time = None
        if start_time_str:
            start_time = datetime.fromisoformat(
                start_time_str.replace('Z', '+00:00'))
        if end_time_str:
            end_time = datetime.fromisoformat(
                end_time_str.replace('Z', '+00:00'))

        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(int(guild_id))
        blacklisted_user_ids = set(int(uid) for uid in blacklists['users'])
        blacklisted_channel_ids = set(int(cid)
                                      for cid in blacklists['channels'])
        blacklisted_category_ids = set(
            int(cat_id) for cat_id in blacklists.get('categories', []))

        # Apply role filtering - get users with selected roles
        allowed_user_ids = None
        if role_filter_ids:
            if isinstance(role_filter_ids, str):
                role_filter_list = [
                    rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
            else:
                role_filter_list = role_filter_ids
            allowed_user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)

            if not allowed_user_ids:
                return []
            allowed_user_ids = set(allowed_user_ids)

        # Get bot filter setting
        settings = await db_stats.get_guild_settings(guild_id)
        bot_filter = settings.get('bot_filter', False)

        async with db_stats.pool.acquire() as conn:
            # Build the query - IMPORTANT: Include ALL filters
            query = """
                SELECT 
                    channel_id,
                    SUM(usage_count) as total_usage,
                    SUM(CASE WHEN usage_type = 'message' THEN usage_count ELSE 0 END) as message_usage,
                    SUM(CASE WHEN usage_type = 'reaction' THEN usage_count ELSE 0 END) as reaction_usage,
                    COUNT(DISTINCT user_id) as unique_users,
                    COUNT(DISTINCT emoji_str) as unique_emojis
                FROM emoji_usage_hourly
                WHERE guild_id = $1
                AND category_id = $2
            """
            params = [int(guild_id), int(category_id)]
            param_counter = 3

            # 1. APPLY ROLE FILTER
            if allowed_user_ids:
                user_id_list = list(allowed_user_ids)
                placeholders = []
                for i in range(len(user_id_list)):
                    placeholders.append(f"${param_counter + i}")
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_id_list)
                param_counter += len(user_id_list)

            # 2. APPLY USER BLACKLIST
            if blacklisted_user_ids:
                blacklist_placeholders = []
                for i in range(len(blacklisted_user_ids)):
                    blacklist_placeholders.append(f"${param_counter + i}")
                query += f" AND user_id NOT IN ({', '.join(blacklist_placeholders)})"
                params.extend(list(blacklisted_user_ids))
                param_counter += len(blacklisted_user_ids)

            # 3. APPLY CHANNEL BLACKLIST
            if blacklisted_channel_ids:
                channel_placeholders = []
                for i in range(len(blacklisted_channel_ids)):
                    channel_placeholders.append(f"${param_counter + i}")
                query += f" AND channel_id NOT IN ({', '.join(channel_placeholders)})"
                params.extend(list(blacklisted_channel_ids))
                param_counter += len(blacklisted_channel_ids)

            # 4. CHECK CATEGORY BLACKLIST
            if blacklisted_category_ids and int(category_id) in blacklisted_category_ids:
                return []

            # 5. APPLY BOT FILTER
            if bot_filter:
                query += " AND is_bot = FALSE"

            # 6. APPLY USAGE TYPE FILTER
            if usage_type and usage_type != 'all':
                query += f" AND usage_type = ${param_counter}"
                params.append(usage_type)
                param_counter += 1

            # 7. APPLY TIME FILTERS - THIS WAS MISSING!
            if start_time:
                query += f" AND hour >= ${param_counter}"
                params.append(start_time)
                param_counter += 1

            if end_time:
                query += f" AND hour <= ${param_counter}"
                params.append(end_time)
                param_counter += 1

            # Ensure channel_id is valid
            query += " AND channel_id IS NOT NULL AND channel_id != 0"

            # Add GROUP BY, HAVING, ORDER BY
            query += """
                GROUP BY channel_id
                HAVING SUM(usage_count) > 0
                ORDER BY total_usage DESC
            """

            # Add LIMIT
            query += f" LIMIT ${param_counter}"
            params.append(limit)

            # Execute query
            rows = await conn.fetch(query, *params)

            # Format results
            result = []
            for row in rows:
                result.append({
                    'channel_id': str(row['channel_id']),
                    'total_usage': row['total_usage'] or 0,
                    'message_usage': row['message_usage'] or 0,
                    'reaction_usage': row['reaction_usage'] or 0,
                    'unique_users': row['unique_users'] or 0,
                    'unique_emojis': row['unique_emojis'] or 0
                })

            return result

    except Exception as e:
        logger.error(f"Error in public_emoji_category_top_channels: {e}")
        logger.error(traceback.format_exc())
        return []


@app.get("/api/public/category/timeseries/messages/daily")
async def public_category_timeseries_messages_daily(
    guild_id: str = Query(..., description="Guild ID"),
    category_id: str = Query(..., description="Category ID"),
    role_filter_ids: Optional[str] = Query(None),
    start_time: Optional[datetime] = Query(None),
    end_time: Optional[datetime] = Query(None),
    timezone_str: Optional[str] = Query(
        'UTC', description="Timezone for date grouping"),
    max_points: int = Query(90, ge=1, le=365)
):
    """Public endpoint for category daily timeseries with role, bot, blacklist, and timezone filtering"""

    if guild_id != STATSHQ_GUILD_ID:
        raise HTTPException(
            status_code=403,
            detail="Access denied. This endpoint is only for public StatsHQ statistics."
        )

    try:
        guild_id_int = int(guild_id)
        category_id_int = int(category_id)

        role_filter_list = role_filter_ids.split(
            ',') if role_filter_ids else None

        if not end_time:
            end_time = datetime.utcnow()
        if not start_time:
            start_time = end_time - timedelta(days=max_points)

        days_in_range = (end_time - start_time).days
        if days_in_range > max_points:
            start_time = end_time - timedelta(days=max_points)

        async with db_stats.pool.acquire() as conn:
            user_ids = None
            if role_filter_list:
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return []

            query = f"""
                SELECT 
                    DATE(hour AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}') as date,
                    COALESCE(SUM(message_count), 0) as message_count
                FROM message_tracking_hourly
                WHERE guild_id = $1 
                AND category_id = $2
                AND hour >= $3 
                AND hour <= $4
            """
            params = [guild_id_int, category_id_int, start_time, end_time]
            param_index = 5

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'message_tracking_hourly',
                include_users=True, include_channels=False,
                specific_category_id=category_id
            )

            query += " GROUP BY date ORDER BY date ASC"

            rows = await conn.fetch(query, *params)

            data_by_date = {row['date'].isoformat(): row['message_count']
                            for row in rows}

            result = []
            current_date = start_time.date()
            end_date_obj = end_time.date()

            while current_date <= end_date_obj:
                date_str = current_date.isoformat()
                result.append({
                    'date': date_str,
                    'messages': data_by_date.get(date_str, 0)
                })
                current_date += timedelta(days=1)

            return result

    except Exception as e:
        logger.error(
            f"Error in public_category_timeseries_messages_daily: {e}")
        return []


@app.post("/api/public/category/activity/distribution")
async def public_category_activity_distribution(request: Request):
    """Public endpoint for category's hourly voice distribution with role, bot, and blacklist filtering - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')
        category_id = body.get('category_id')
        days_back = body.get('days_back', 30)
        # ← FIXED: extract role_filter_ids
        role_filter_ids = body.get('role_filter_ids')
        timezone_str = body.get('timezone_str', 'UTC')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(
                status_code=403, detail="Access denied. This endpoint is only for public StatsHQ statistics.")

        voice_by_hour = {f"hour_{i}": 0 for i in range(24)}

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering
            user_ids = None
            if role_filter_ids:
                if isinstance(role_filter_ids, str):
                    role_filter_list = [
                        rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
                else:
                    role_filter_list = role_filter_ids
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return {"voice": {f"hour_{i}": 0 for i in range(24)}, "public": True}

            query = f"""
                SELECT 
                    EXTRACT(HOUR FROM hour AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}') as hour_of_day,
                    COALESCE(SUM(total_seconds), 0) as total_seconds
                FROM voice_session_history_hourly
                WHERE guild_id = $1 AND category_id = $2
            """
            params = [int(guild_id), int(category_id)]

            if days_back and days_back > 0:
                query += f" AND hour >= NOW() - INTERVAL '{days_back} days'"

            if user_ids:
                placeholders = [
                    f"${len(params) + i + 1}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)

            query, params = await db_stats._apply_voice_state_filter(query, params, guild_id, 'state_flags')
            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'voice_session_history_hourly',
                include_users=True, include_channels=False,
                specific_category_id=category_id
            )

            query += " GROUP BY hour_of_day ORDER BY hour_of_day"

            rows = await conn.fetch(query, *params)

            for row in rows:
                hour = int(row['hour_of_day'])
                voice_by_hour[f"hour_{hour}"] = row['total_seconds'] or 0

            return {"voice": voice_by_hour, "public": True}

    except Exception as e:
        logger.error(f"Error in public_category_activity_distribution: {e}")
        return {"voice": {f"hour_{i}": 0 for i in range(24)}, "public": True}


@app.post("/api/public/channel/stats/messages")
async def public_channel_stats_messages(request: Request):
    """Public endpoint for channel message statistics with role, bot, and blacklist filtering - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')
        channel_id = body.get('channel_id')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')
        role_filter_ids = body.get('role_filter_ids')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(
                status_code=403, detail="Access denied. This endpoint is only for public StatsHQ statistics.")

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering
            user_ids = None
            if role_filter_ids:
                if isinstance(role_filter_ids, str):
                    role_filter_list = [
                        rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
                else:
                    role_filter_list = role_filter_ids
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return {
                        'total_messages': 0, 'total_chars': 0, 'avg_chars': 0,
                        'unique_users': 0, 'messages_per_user': 0,
                        'has_attachments': 0, 'has_embeds': 0
                    }

            query = """
                SELECT 
                    COALESCE(SUM(message_count), 0) as total_messages,
                    COALESCE(SUM(total_chars), 0) as total_chars,
                    COALESCE(SUM(total_chars) / NULLIF(SUM(message_count), 0), 0) as avg_chars,
                    COUNT(DISTINCT user_id) as unique_users,
                    COALESCE(SUM(attachment_count), 0) as has_attachments,
                    COALESCE(SUM(embed_count), 0) as has_embeds
                FROM message_tracking_hourly
                WHERE guild_id = $1 AND channel_id = $2
            """
            params = [int(guild_id), int(channel_id)]
            param_index = 3

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_index += len(user_ids)

            if start_time:
                params.append(start_time)
                query += f" AND hour >= ${param_index}"
                param_index += 1
            if end_time:
                params.append(end_time)
                query += f" AND hour <= ${param_index}"
                param_index += 1

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'message_tracking_hourly')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'message_tracking_hourly',
                include_users=True, include_channels=False,
                specific_channel_id=channel_id
            )

            row = await conn.fetchrow(query, *params)

            total_messages = row['total_messages'] or 0
            unique_users = row['unique_users'] or 0
            messages_per_user = total_messages / max(unique_users, 1)

            return {
                'total_messages': total_messages,
                'total_chars': row['total_chars'] or 0,
                'avg_chars': round(row['avg_chars'] or 0, 2),
                'unique_users': unique_users,
                'messages_per_user': round(messages_per_user, 2),
                'has_attachments': row['has_attachments'] or 0,
                'has_embeds': row['has_embeds'] or 0
            }

    except Exception as e:
        logger.error(f"Error in public_channel_stats_messages: {e}")
        return {
            'total_messages': 0, 'total_chars': 0, 'avg_chars': 0,
            'unique_users': 0, 'messages_per_user': 0,
            'has_attachments': 0, 'has_embeds': 0
        }


