@app.get("/api/user/permissions/{guild_id}")
async def get_user_permissions(
    guild_id: str,
    user: Optional[Dict] = Depends(get_current_user)
):
    """Get user's permissions for a specific guild"""
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Get user's servers from the database
        user_servers = await auth_db.get_user_servers(user['discord_id'])

        # Find the specific server
        server = None
        for s in user_servers:
            if s['guild_id'] == guild_id:
                server = s
                break

        if not server:
            # Try to fetch from Discord API directly
            access_token = await auth_db.get_user_access_token(user['discord_id'])
            if access_token:
                user_guilds = await discord_api.get_user_guilds(access_token)
                for guild in user_guilds:
                    if guild['id'] == guild_id:
                        server = {
                            'guild_id': guild['id'],
                            'permissions': guild.get('permissions', '0')
                        }
                        break

        if not server:
            return {"permissions": "0", "success": False, "message": "Guild not found"}

        return {
            "permissions": int(server.get('permissions', '0')),
            "success": True,
            "guild_id": guild_id
        }

    except Exception as e:
        logger.error(
            f"Error getting user permissions for guild {guild_id}: {e}")
        return {"permissions": 0, "success": False, "error": str(e)}


@app.get("/api/public/voice/users")
async def public_voice_users(
    guild_id: str = Query(..., description="Guild ID"),
    start_time: Optional[datetime] = Query(None),
    end_time: Optional[datetime] = Query(None),
    days_back: Optional[int] = Query(None)
):
    """Public endpoint to get users with voice activity with blacklist filtering - only works for StatsHQ"""
    if guild_id != STATSHQ_GUILD_ID:
        raise HTTPException(status_code=403, detail="Access denied.")

    try:
        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(int(guild_id))
        blacklisted_user_ids = set(int(uid)
                                   for uid in blacklists.get('users', []))

        async with db_stats.pool.acquire() as conn:
            query = """
                SELECT DISTINCT user_id
                FROM voice_session_history_hourly
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_index = 2

            # Apply user blacklist
            if blacklisted_user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_user_ids))]
                query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                params.extend(list(blacklisted_user_ids))
                param_index += len(blacklisted_user_ids)

            if start_time and end_time:
                query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                params.append(start_time)
                params.append(end_time)
                param_index += 2
            elif start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
                param_index += 1
            elif end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)
                param_index += 1
            elif days_back:
                query += f" AND hour >= NOW() - INTERVAL '1 day' * ${param_index}"
                params.append(days_back)
                param_index += 1

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')

            query += " ORDER BY user_id LIMIT 1000"

            rows = await conn.fetch(query, *params)
            user_ids = [str(row['user_id']) for row in rows]

            return {
                "user_ids": user_ids,
                "count": len(user_ids),
                "public": True,
                "guild_id": STATSHQ_GUILD_ID,
                "guild_name": STATSHQ_GUILD_NAME
            }

    except Exception as e:
        logger.error(f"Error in public_voice_users: {e}")
        return {"user_ids": [], "count": 0, "public": True, "error": str(e)}


@app.get("/api/public/voice/channels")
async def public_voice_channels(
    guild_id: str = Query(..., description="Guild ID"),
    start_time: Optional[datetime] = Query(None),
    end_time: Optional[datetime] = Query(None),
    days_back: Optional[int] = Query(None)
):
    """Public endpoint to get channels with voice data with blacklist filtering - uses discord_channels table"""
    if guild_id != STATSHQ_GUILD_ID:
        raise HTTPException(status_code=403, detail="Access denied.")

    try:
        guild_id_int = int(guild_id)

        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(guild_id_int)
        blacklisted_channel_ids = set(int(cid)
                                      for cid in blacklists.get('channels', []))
        blacklisted_user_ids = set(int(uid)
                                   for uid in blacklists.get('users', []))

        # STEP 1: Get channels that have voice data from the voice table
        async with db_stats.pool.acquire() as conn:
            voice_query = """
                SELECT DISTINCT channel_id
                FROM voice_session_history_hourly
                WHERE guild_id = $1
                AND channel_id IS NOT NULL
                AND channel_id != 0
            """
            voice_params = [guild_id_int]
            param_index = 2

            # Apply channel blacklist
            if blacklisted_channel_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_channel_ids))]
                voice_query += f" AND channel_id NOT IN ({', '.join(placeholders)})"
                voice_params.extend(list(blacklisted_channel_ids))
                param_index += len(blacklisted_channel_ids)

            # Apply user blacklist
            if blacklisted_user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_user_ids))]
                voice_query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                voice_params.extend(list(blacklisted_user_ids))
                param_index += len(blacklisted_user_ids)

            if start_time and end_time:
                voice_query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                voice_params.append(start_time)
                voice_params.append(end_time)
                param_index += 2
            elif start_time:
                voice_query += f" AND hour >= ${param_index}"
                voice_params.append(start_time)
                param_index += 1
            elif end_time:
                voice_query += f" AND hour <= ${param_index}"
                voice_params.append(end_time)
                param_index += 1
            elif days_back:
                voice_query += f" AND hour >= NOW() - INTERVAL '1 day' * ${param_index}"
                voice_params.append(days_back)
                param_index += 1

            rows = await conn.fetch(voice_query, *voice_params)
            channel_ids_with_data = [str(row['channel_id']) for row in rows]

            if not channel_ids_with_data:
                return {"channels": [], "count": 0, "public": True}

        # STEP 2: Get channel names from discord_channels table
        channels_with_names = []

        async with db_stats.pool.acquire() as conn:
            placeholders = ','.join(
                [f'${i+2}' for i in range(len(channel_ids_with_data))])
            rows = await conn.fetch(f"""
                SELECT channel_id, channel_name, channel_type, category_id, is_deleted
                FROM discord_channels
                WHERE guild_id = $1 
                AND channel_id IN ({placeholders})
                AND channel_type IN ('voice', 'stage')
                AND is_deleted = FALSE
            """, guild_id_int, *[int(cid) for cid in channel_ids_with_data])

            channel_map = {str(row['channel_id']): row for row in rows}

            for channel_id in channel_ids_with_data:
                if channel_id in channel_map:
                    row = channel_map[channel_id]
                    channels_with_names.append({
                        "id": str(row['channel_id']),
                        "name": row['channel_name'],
                        "type": row['channel_type'],
                        "category_id": str(row['category_id']) if row.get('category_id') else None
                    })
                else:
                    channels_with_names.append({
                        "id": channel_id,
                        "name": f"Voice Channel {channel_id}",
                        "type": "voice",
                        "category_id": None
                    })

        channels_with_names.sort(key=lambda x: x['name'])

        return {
            "channels": channels_with_names,
            "count": len(channels_with_names),
            "public": True,
            "guild_id": guild_id,
            "source": "discord_channels_table"
        }

    except Exception as e:
        logger.error(f"Error in public_voice_channels: {e}")
        return {"channels": [], "count": 0, "public": True, "error": str(e)}


