# Fix for public_category_timeseries_voice_daily - fix SQL syntax
@app.get("/api/public/category/timeseries/voice/daily")
async def public_category_timeseries_voice_daily(
    guild_id: str = Query(..., description="Guild ID"),
    category_id: str = Query(..., description="Category ID"),
    role_filter_ids: Optional[str] = Query(None),
    start_time: Optional[datetime] = Query(None),
    end_time: Optional[datetime] = Query(None),
    timezone_str: Optional[str] = Query(
        'UTC', description="Timezone for date grouping"),
    max_points: int = Query(90, ge=1, le=365)
):
    """Public endpoint for category's daily voice timeseries - only works for StatsHQ"""
    if guild_id != STATSHQ_GUILD_ID:
        raise HTTPException(
            status_code=403,
            detail="Access denied. This endpoint is only for public StatsHQ statistics."
        )

    try:
        role_filter_list = role_filter_ids.split(
            ',') if role_filter_ids else None

        if not end_time:
            end_time = datetime.utcnow()
        if not start_time:
            start_time = end_time - timedelta(days=max_points)

        days_in_range = (end_time - start_time).days
        if days_in_range > max_points:
            start_time = end_time - timedelta(days=max_points)

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering
            user_ids = None
            if role_filter_list:
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return []

            # Build query with proper date conversion
            query = f"""
                SELECT 
                    DATE(hour AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}') as date,
                    COALESCE(SUM(total_seconds), 0) as total_seconds
                FROM voice_session_history_hourly
                WHERE guild_id = $1 
                AND category_id = $2
                AND hour >= $3 
                AND hour <= $4
            """
            params = [int(guild_id), int(category_id), start_time, end_time]
            param_index = 5

            # Add role filter if needed
            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_index += len(user_ids)

            # Apply voice state filter
            query, params = await db_stats._apply_voice_state_filter(query, params, guild_id, 'state_flags')

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'voice_session_history_hourly')

            # Apply blacklist filters
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'voice_session_history_hourly',
                include_users=True, include_channels=False,
                specific_category_id=category_id
            )

            # Add GROUP BY and ORDER BY
            query += " GROUP BY date ORDER BY date ASC"

            rows = await conn.fetch(query, *params)

            data_by_date = {row['date'].isoformat(): row['total_seconds']
                            for row in rows}

            result = []
            current_date = start_time.date()
            end_date_obj = end_time.date()

            while current_date <= end_date_obj:
                date_str = current_date.isoformat()
                result.append({
                    'date': date_str,
                    'seconds': data_by_date.get(date_str, 0)
                })
                current_date += timedelta(days=1)

            return result

    except Exception as e:
        logger.error(f"Error in public_category_timeseries_voice_daily: {e}")
        return []


