# Fix for public_activity_server_timeseries
@app.post("/api/public/activity/server/timeseries")
async def public_activity_server_timeseries(request: Request):
    """Public endpoint for server activity timeseries with role, bot, and blacklist filtering - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(status_code=403, detail="Access denied.")

        days = body.get('days', 30)
        limit = body.get('limit', 10)
        role_filter_ids = body.get('role_filter_ids')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        async with db_stats.pool.acquire() as conn:
            user_ids = None
            if role_filter_ids:
                if isinstance(role_filter_ids, str):
                    role_filter_list = [
                        rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
                else:
                    role_filter_list = role_filter_ids
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return []

            # Get user blacklist only
            blacklists = await db_stats._get_cached_blacklists(int(guild_id))
            blacklisted_user_ids = set(int(uid) for uid in blacklists['users'])

            top_query = """
                SELECT
                    display_name,
                    activity_type,
                    SUM(total_duration_seconds) as total_duration
                FROM activity_sessions_hourly
                WHERE guild_id = $1
            """
            top_params = [int(guild_id)]
            param_index = 2

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                top_query += f" AND user_id IN ({', '.join(placeholders)})"
                top_params.extend(user_ids)
                param_index += len(user_ids)

            if blacklisted_user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_user_ids))]
                top_query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                top_params.extend(blacklisted_user_ids)
                param_index += len(blacklisted_user_ids)

            if start_time and end_time:
                top_query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                top_params.append(start_time)
                top_params.append(end_time)
                param_index += 2
            elif start_time:
                top_query += f" AND hour >= ${param_index}"
                top_params.append(start_time)
                param_index += 1
            elif end_time:
                top_query += f" AND hour <= ${param_index}"
                top_params.append(end_time)
                param_index += 1
            elif days:
                top_query += f" AND hour >= NOW() - INTERVAL '1 day' * ${param_index}"
                top_params.append(days)
                param_index += 1

            top_query, top_params = await db_stats._apply_bot_filter(top_query, top_params, guild_id, 'activity_sessions_hourly')

            top_query += " GROUP BY display_name, activity_type ORDER BY total_duration DESC LIMIT $"
            top_query += str(param_index)
            top_params.append(limit)

            top_activities = await conn.fetch(top_query, *top_params)
            if not top_activities:
                return []

            date_query = """
                SELECT MIN(DATE(hour)) as min_date, MAX(DATE(hour)) as max_date
                FROM activity_sessions_hourly
                WHERE guild_id = $1
            """
            date_params = [int(guild_id)]
            param_index = 2

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                date_query += f" AND user_id IN ({', '.join(placeholders)})"
                date_params.extend(user_ids)
                param_index += len(user_ids)

            if blacklisted_user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(blacklisted_user_ids))]
                date_query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                date_params.extend(blacklisted_user_ids)
                param_index += len(blacklisted_user_ids)

            if start_time and end_time:
                date_query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                date_params.append(start_time)
                date_params.append(end_time)
            elif start_time:
                date_query += f" AND hour >= ${param_index}"
                date_params.append(start_time)
            elif end_time:
                date_query += f" AND hour <= ${param_index}"
                date_params.append(end_time)
            elif days:
                date_query += f" AND hour >= NOW() - INTERVAL '1 day' * ${param_index}"
                date_params.append(days)

            date_row = await conn.fetchrow(date_query, *date_params)
            if not date_row or not date_row['min_date']:
                return []

            min_date = date_row['min_date']
            max_date = date_row['max_date']

            current_date = min_date
            all_dates = []
            while current_date <= max_date:
                all_dates.append(current_date)
                current_date += timedelta(days=1)

            result = []
            activity_names = [{'display_name': act['display_name'],
                               'activity_type': act['activity_type']} for act in top_activities]

            for date in all_dates:
                date_str = date.isoformat()
                next_date = date + timedelta(days=1)

                daily_query = """
                    SELECT
                        display_name,
                        activity_type,
                        COALESCE(SUM(total_duration_seconds), 0) as total_duration_seconds,
                        COALESCE(SUM(session_count), 0) as session_count,
                        COUNT(DISTINCT user_id) as user_count
                    FROM activity_sessions_hourly
                    WHERE guild_id = $1 AND hour >= $2 AND hour < $3
                """
                daily_params = [int(guild_id), date, next_date]
                param_index = 4

                if user_ids:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(user_ids))]
                    daily_query += f" AND user_id IN ({', '.join(placeholders)})"
                    daily_params.extend(user_ids)
                    param_index += len(user_ids)

                if blacklisted_user_ids:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(blacklisted_user_ids))]
                    daily_query += f" AND user_id NOT IN ({', '.join(placeholders)})"
                    daily_params.extend(blacklisted_user_ids)
                    param_index += len(blacklisted_user_ids)

                conditions = []
                for i, act in enumerate(activity_names):
                    display_param_idx = param_index + (i * 2)
                    type_param_idx = param_index + (i * 2) + 1
                    conditions.append(
                        f"(display_name = ${display_param_idx} AND activity_type = ${type_param_idx})")
                    daily_params.append(act['display_name'])
                    daily_params.append(act['activity_type'])

                daily_query += " AND (" + " OR ".join(conditions) + ")"
                daily_query += " GROUP BY display_name, activity_type"

                daily_query, daily_params = await db_stats._apply_bot_filter(daily_query, daily_params, guild_id, 'activity_sessions_hourly')

                daily_rows = await conn.fetch(daily_query, *daily_params)

                day_values = {}
                for row in daily_rows:
                    key = f"{row['display_name']}_{row['activity_type']}"
                    day_values[key] = {
                        'duration': row['total_duration_seconds'] or 0,
                        'sessions': row['session_count'] or 0,
                        'users': row['user_count'] or 0
                    }

                day_activities = []
                for act in activity_names:
                    key = f"{act['display_name']}_{act['activity_type']}"
                    if key in day_values:
                        day_activities.append({
                            'display_name': act['display_name'],
                            'activity_type': act['activity_type'],
                            'total_duration_seconds': day_values[key]['duration'],
                            'session_count': day_values[key]['sessions'],
                            'user_count': day_values[key]['users']
                        })
                    else:
                        day_activities.append({
                            'display_name': act['display_name'],
                            'activity_type': act['activity_type'],
                            'total_duration_seconds': 0,
                            'session_count': 0,
                            'user_count': 0
                        })

                result.append({'date': date_str, 'activities': day_activities})

            return result

    except Exception as e:
        logger.error(f"Error in public_activity_server_timeseries: {e}")
        return []


