@app.get("/api/public/emoji/users")
async def public_emoji_users(
    guild_id: str = Query(..., description="Guild ID"),
    start_time: Optional[datetime] = Query(None),
    end_time: Optional[datetime] = Query(None),
    days_back: Optional[int] = Query(None)
):
    """Public endpoint to get users with emoji usage - only works for StatsHQ"""
    if guild_id != STATSHQ_GUILD_ID:
        raise HTTPException(status_code=403, detail="Access denied.")

    try:
        async with db_stats.pool.acquire() as conn:
            query = """
                SELECT DISTINCT user_id
                FROM emoji_usage_hourly
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_index = 2

            if start_time and end_time:
                query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                params.append(start_time)
                params.append(end_time)
                param_index += 2
            elif start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
                param_index += 1
            elif end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)
                param_index += 1
            elif days_back:
                query += f" AND hour >= NOW() - INTERVAL '1 day' * ${param_index}"
                params.append(days_back)
                param_index += 1

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'emoji_usage_hourly')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'emoji_usage_hourly',
                include_users=True, include_channels=True
            )

            query += " ORDER BY user_id LIMIT 500"
            rows = await conn.fetch(query, *params)
            user_ids = [str(row['user_id']) for row in rows]

            return {"user_ids": user_ids, "count": len(user_ids), "public": True, "guild_id": STATSHQ_GUILD_ID, "guild_name": STATSHQ_GUILD_NAME}

    except Exception as e:
        logger.error(f"Error in public_emoji_users: {e}")
        return {"user_ids": [], "count": 0, "public": True, "error": str(e)}


