@app.post("/api/public/emoji/server/stats")
async def public_emoji_server_stats(request: Request):
    """Public endpoint for server emoji statistics - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(status_code=403, detail="Access denied.")
        usage_type = body.get('usage_type')
        role_filter_ids = body.get('role_filter_ids')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering if provided
            user_ids = None
            if role_filter_ids:
                if isinstance(role_filter_ids, str):
                    role_filter_list = [
                        rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
                else:
                    role_filter_list = role_filter_ids
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return {"total_usage": 0, "unique_users": 0}

            query = """
                SELECT 
                    COALESCE(SUM(usage_count), 0) as total_usage,
                    COUNT(DISTINCT user_id) as unique_users
                FROM emoji_usage_hourly
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_index = 2

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_index += len(user_ids)

            if usage_type and usage_type != 'all':
                query += f" AND usage_type = ${param_index}"
                params.append(usage_type)
                param_index += 1

            if start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
                param_index += 1
            if end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)
                param_index += 1

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'emoji_usage_hourly')

            row = await conn.fetchrow(query, *params)

            return {
                "total_usage": row['total_usage'] or 0,
                "unique_users": row['unique_users'] or 0
            }

    except Exception as e:
        logger.error(f"Error in public_emoji_server_stats: {e}")
        return {"total_usage": 0, "unique_users": 0}


@app.post("/api/public/emoji/server/top/emojis")
async def public_emoji_server_top_emojis(request: Request):
    """Public endpoint for server's top emojis - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(status_code=403, detail="Access denied.")

        limit = body.get('limit', 10)
        usage_type = body.get('usage_type')
        role_filter_ids = body.get('role_filter_ids')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering if provided
            user_ids = None
            if role_filter_ids:
                if isinstance(role_filter_ids, str):
                    role_filter_list = [
                        rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
                else:
                    role_filter_list = role_filter_ids
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return []

            # Get total usage for percentage
            total_query = """
                SELECT COALESCE(SUM(usage_count), 0) as total_usage
                FROM emoji_usage_hourly
                WHERE guild_id = $1
            """
            total_params = [int(guild_id)]
            param_index = 2

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                total_query += f" AND user_id IN ({', '.join(placeholders)})"
                total_params.extend(user_ids)
                param_index += len(user_ids)

            if usage_type and usage_type != 'all':
                total_query += f" AND usage_type = ${param_index}"
                total_params.append(usage_type)
                param_index += 1

            if start_time:
                total_query += f" AND hour >= ${param_index}"
                total_params.append(start_time)
                param_index += 1
            if end_time:
                total_query += f" AND hour <= ${param_index}"
                total_params.append(end_time)
                param_index += 1

            total_row = await conn.fetchrow(total_query, *total_params)
            total_usage = total_row['total_usage'] if total_row else 0

            # Main query
            query = """
                SELECT 
                    emoji_str,
                    is_custom,
                    SUM(usage_count) as usage_count,
                    COUNT(DISTINCT user_id) as unique_users
                FROM emoji_usage_hourly
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_index = 2

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_index += len(user_ids)

            if usage_type and usage_type != 'all':
                query += f" AND usage_type = ${param_index}"
                params.append(usage_type)
                param_index += 1

            if start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
                param_index += 1
            if end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)
                param_index += 1

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'emoji_usage_hourly')

            query += " GROUP BY emoji_str, is_custom ORDER BY usage_count DESC LIMIT $"
            query += str(param_index)
            params.append(limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                percentage = (row['usage_count'] /
                              total_usage * 100) if total_usage > 0 else 0
                result.append({
                    "emoji_str": row['emoji_str'],
                    "is_custom": row['is_custom'],
                    "usage_count": row['usage_count'] or 0,
                    "unique_users": row['unique_users'] or 0,
                    "percentage": round(percentage, 1)
                })

            return result

    except Exception as e:
        logger.error(f"Error in public_emoji_server_top_emojis: {e}")
        return []


