@app.post("/api/emoji/user/top/channels")
async def emoji_user_top_channels(request: EmojiUserRequest, user: Optional[Dict] = Depends(get_current_user)):
    """
    Get user's top channels by emoji usage with role, bot, and blacklist filtering.
    Can filter by usage_type: 'all', 'message', or 'reaction'
    Can filter by category_id
    """
    if not user:
        raise HTTPException(status_code=401, detail="Not authenticated")

    try:
        # Validate IDs
        try:
            guild_id_int = int(request.guild_id)
            user_id_int = int(request.user_id)
        except ValueError as e:
            raise HTTPException(
                status_code=400, detail=f"Invalid ID format: {e}")

        # Apply usage_type filter if specified
        usage_type = None
        if request.usage_type and request.usage_type != 'all':
            usage_type = request.usage_type

        # Get blacklists
        blacklists = await db_stats._get_cached_blacklists(guild_id_int)
        blacklisted_user_ids = set(int(uid)
                                   for uid in blacklists.get('users', []))
        blacklisted_channel_ids = set(int(cid)
                                      for cid in blacklists.get('channels', []))
        blacklisted_category_ids = set(
            int(cat_id) for cat_id in blacklists.get('categories', []))

        # Check if user is blacklisted
        if user_id_int in blacklisted_user_ids:
            return []

        async with db_stats.pool.acquire() as conn:
            # Apply role filtering if needed
            if request.role_filter_ids:
                user_ids = await db_stats._get_users_with_roles(request.guild_id, request.role_filter_ids)
                if not user_ids or user_id_int not in user_ids:
                    return []

            query = """
                SELECT 
                    channel_id,
                    SUM(usage_count) as total_usage,
                    SUM(CASE WHEN usage_type = 'message' THEN usage_count ELSE 0 END) as message_usage,
                    SUM(CASE WHEN usage_type = 'reaction' THEN usage_count ELSE 0 END) as reaction_usage,
                    COUNT(DISTINCT emoji_str) as unique_emojis
                FROM emoji_usage_hourly
                WHERE guild_id = $1 AND user_id = $2
            """
            params = [int(request.guild_id), int(request.user_id)]
            param_index = 3

            # Apply category filter if specified
            if request.category_id:
                params.append(int(request.category_id))
                query += f" AND category_id = ${len(params)}"

            # Apply usage_type filter
            if usage_type:
                params.append(usage_type)
                query += f" AND usage_type = ${len(params)}"

            # Apply time filters
            if request.start_time:
                params.append(request.start_time)
                query += f" AND hour >= ${len(params)}"
            if request.end_time:
                params.append(request.end_time)
                query += f" AND hour <= ${len(params)}"

            # Apply channel blacklist
            if blacklisted_channel_ids:
                placeholders = []
                for i, cid in enumerate(blacklisted_channel_ids):
                    placeholders.append(f"${len(params) + i + 1}")
                    params.append(cid)
                query += f" AND channel_id NOT IN ({', '.join(placeholders)})"

            # Apply category blacklist
            if blacklisted_category_ids and request.category_id:
                if int(request.category_id) in blacklisted_category_ids:
                    return []

            # Apply bot filter
            query, params = await db_stats._apply_bot_filter(
                query, params, request.guild_id, 'emoji_usage_hourly'
            )

            query += """
                GROUP BY channel_id
                HAVING SUM(usage_count) > 0
                ORDER BY total_usage DESC
                LIMIT $"""
            query += str(len(params) + 1)
            params.append(request.limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                result.append({
                    'channel_id': str(row['channel_id']),
                    'total_usage': row['total_usage'] or 0,
                    'message_usage': row['message_usage'] or 0,
                    'reaction_usage': row['reaction_usage'] or 0,
                    'unique_emojis': row['unique_emojis'] or 0
                })

            # Filter out deleted channels
            if result:
                channel_ids = [item['channel_id'] for item in result]
                existence_map = await discord_api.verify_entities_exist(
                    request.guild_id, 'channel', channel_ids
                )

                filtered_result = []
                for item in result:
                    if existence_map.get(item['channel_id'], True):
                        filtered_result.append(item)

                result = filtered_result

            return result

    except ValueError as e:
        logger.error(f"Invalid ID format in emoji_user_top_channels: {e}")
        raise HTTPException(status_code=400, detail=f"Invalid ID format: {e}")
    except Exception as e:
        logger.error(f"Unexpected error in emoji_user_top_channels: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/public/emoji/user/top/categories")
async def public_emoji_user_top_categories(request: Request):
    """Public endpoint for user's top categories by emoji usage with names - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')
        user_id = body.get('user_id')
        limit = body.get('limit', 20)
        usage_type = body.get('usage_type')
        channel_id = body.get('channel_id')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')
        role_filter_ids = body.get('role_filter_ids')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(status_code=403, detail="Access denied.")

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        async with db_stats.pool.acquire() as conn:
            allowed_user_ids = None
            if role_filter_ids:
                if isinstance(role_filter_ids, str):
                    role_filter_list = [
                        rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
                else:
                    role_filter_list = role_filter_ids
                allowed_user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not allowed_user_ids or int(user_id) not in allowed_user_ids:
                    return []

            query = """
                SELECT 
                    e.category_id,
                    COALESCE(c.channel_name, 'Unknown Category') as category_name,
                    SUM(e.usage_count) as total_usage,
                    COUNT(DISTINCT e.emoji_str) as unique_emojis,
                    COUNT(DISTINCT e.channel_id) as unique_channels
                FROM emoji_usage_hourly e
                LEFT JOIN discord_channels c ON e.category_id = c.channel_id AND c.guild_id = $1 AND c.channel_type = 'category' AND c.is_deleted = FALSE
                WHERE e.guild_id = $1 AND e.user_id = $2
                AND e.category_id IS NOT NULL
                AND e.category_id != 0
            """
            params = [int(guild_id), int(user_id)]
            param_index = 3

            if channel_id:
                params.append(int(channel_id))
                query += f" AND e.channel_id = ${len(params)}"

            if usage_type and usage_type != 'all':
                params.append(usage_type)
                query += f" AND e.usage_type = ${len(params)}"

            if start_time:
                params.append(start_time)
                query += f" AND e.hour >= ${len(params)}"
            if end_time:
                params.append(end_time)
                query += f" AND e.hour <= ${len(params)}"

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'emoji_usage_hourly')

            query += " GROUP BY e.category_id, c.channel_name ORDER BY total_usage DESC LIMIT $"
            query += str(len(params) + 1)
            params.append(limit)

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                result.append({
                    'category_id': str(row['category_id']),
                    'category_name': row['category_name'],
                    'total_usage': row['total_usage'] or 0,
                    'unique_emojis': row['unique_emojis'] or 0,
                    'unique_channels': row['unique_channels'] or 0
                })

            return result

    except Exception as e:
        logger.error(f"Error in public_emoji_user_top_categories: {e}")
        return []


