@app.get("/api/public/emoji/user/locations")
async def public_emoji_user_locations(
    guild_id: str = Query(..., description="Guild ID"),
    user_id: str = Query(..., description="User ID")
):
    """Public endpoint to get user's emoji locations - only works for StatsHQ"""
    if guild_id != STATSHQ_GUILD_ID:
        raise HTTPException(status_code=403, detail="Access denied.")

    try:
        async with db_stats.pool.acquire() as conn:
            channels_query = """
                SELECT DISTINCT channel_id
                FROM emoji_usage_hourly
                WHERE guild_id = $1 AND user_id = $2
            """
            channels_rows = await conn.fetch(channels_query, int(guild_id), int(user_id))
            channel_ids = [str(row['channel_id']) for row in channels_rows]

            categories_query = """
                SELECT DISTINCT category_id
                FROM emoji_usage_hourly
                WHERE guild_id = $1 AND user_id = $2
                AND category_id IS NOT NULL
                AND category_id != 0
            """
            categories_rows = await conn.fetch(categories_query, int(guild_id), int(user_id))
            category_ids = [str(row['category_id']) for row in categories_rows]

            return {
                "guild_id": guild_id,
                "user_id": user_id,
                "channels": {
                    "ids": channel_ids,
                    "count": len(channel_ids)
                },
                "categories": {
                    "ids": category_ids,
                    "count": len(category_ids)
                }
            }

    except Exception as e:
        logger.error(f"Error in public_emoji_user_locations: {e}")
        return {"channels": {"ids": [], "count": 0}, "categories": {"ids": [], "count": 0}}


