@app.post("/api/public/emoji/channel/timeseries")
async def public_emoji_channel_timeseries(request: Request):
    """Public endpoint for channel emoji usage over time - only works for StatsHQ"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')
        channel_id = body.get('channel_id')
        usage_type = body.get('usage_type')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')
        timezone_str = body.get('timezone_str', 'UTC')
        role_filter_ids = body.get('role_filter_ids')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(status_code=403, detail="Access denied.")

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        async with db_stats.pool.acquire() as conn:
            # Initialize user_ids as None
            user_ids = None

            # Apply role filtering if provided
            if role_filter_ids:
                if isinstance(role_filter_ids, str):
                    role_filter_list = [
                        rid.strip() for rid in role_filter_ids.split(',') if rid.strip()]
                else:
                    role_filter_list = role_filter_ids
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_list)
                if not user_ids:
                    return []

            query = f"""
                SELECT 
                    DATE(hour AT TIME ZONE 'UTC' AT TIME ZONE '{timezone_str}') as date,
                    COALESCE(SUM(usage_count), 0) as total_usage,
                    COALESCE(SUM(CASE WHEN usage_type = 'message' THEN usage_count ELSE 0 END), 0) as message_usage,
                    COALESCE(SUM(CASE WHEN usage_type = 'reaction' THEN usage_count ELSE 0 END), 0) as reaction_usage,
                    COUNT(DISTINCT user_id) as unique_users,
                    COUNT(DISTINCT emoji_str) as unique_emojis
                FROM emoji_usage_hourly
                WHERE guild_id = $1 AND channel_id = $2
            """
            params = [int(guild_id), int(channel_id)]
            param_index = 3

            if user_ids:
                placeholders = [
                    f"${param_index + i}" for i in range(len(user_ids))]
                query += f" AND user_id IN ({', '.join(placeholders)})"
                params.extend(user_ids)
                param_index += len(user_ids)

            if usage_type and usage_type != 'all':
                query += f" AND usage_type = ${param_index}"
                params.append(usage_type)
                param_index += 1

            if start_time and end_time:
                query += f" AND hour >= ${param_index} AND hour <= ${param_index + 1}"
                params.append(start_time)
                params.append(end_time)
            elif start_time:
                query += f" AND hour >= ${param_index}"
                params.append(start_time)
            elif end_time:
                query += f" AND hour <= ${param_index}"
                params.append(end_time)

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'emoji_usage_hourly')

            query += " GROUP BY date ORDER BY date ASC"

            rows = await conn.fetch(query, *params)

            result = []
            for row in rows:
                result.append({
                    "date": row['date'].isoformat(),
                    "total_usage": row['total_usage'],
                    "message_usage": row['message_usage'],
                    "reaction_usage": row['reaction_usage'],
                    "unique_users": row['unique_users'],
                    "unique_emojis": row['unique_emojis']
                })

            return result

    except Exception as e:
        logger.error(f"Error in public_emoji_channel_timeseries: {e}")
        return []


