@app.post("/api/public/invite/stats/total")
async def public_invite_total_stats(request: Request):
    """Public endpoint to get total invite statistics for StatsHQ guild with role, bot, and blacklist filtering"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(status_code=403, detail="Access denied.")

        filter_type = body.get('filter_type', 'all')
        days = body.get('days', 30)
        role_filter_ids = body.get('role_filter_ids')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        filter_value = str(filter_type).lower()
        if filter_value not in ["all", "valid", "suspicious", "left"]:
            filter_value = "all"

        async with db_stats.pool.acquire() as conn:
            query = """
                SELECT
                    COALESCE(COUNT(*), 0) as total_invites,
                    COALESCE(COUNT(*) FILTER (WHERE invite_type = 'valid'), 0) as valid_invites,
                    COALESCE(COUNT(*) FILTER (WHERE invite_type = 'suspicious'), 0) as suspicious_invites,
                    COALESCE(COUNT(*) FILTER (WHERE invite_type = 'left'), 0) as left_invites,
                    COALESCE(COUNT(DISTINCT inviter_id), 0) as unique_inviters,
                    COALESCE(COUNT(DISTINCT invitee_id), 0) as unique_invitees
                FROM invite_tracking
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_index = 2

            if filter_value != "all":
                query += f" AND invite_type = ${param_index}"
                params.append(filter_value)
                param_index += 1

            if role_filter_ids and len(role_filter_ids) > 0:
                inviter_ids = await db_stats._get_users_with_roles(guild_id, role_filter_ids)
                if inviter_ids and len(inviter_ids) > 0:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(inviter_ids))]
                    query += f" AND inviter_id IN ({', '.join(placeholders)})"
                    params.extend(inviter_ids)
                    param_index += len(inviter_ids)
                else:
                    return {"guild_id": guild_id, "total_invites": 0, "valid_invites": 0, "suspicious_invites": 0, "left_invites": 0, "unique_inviters": 0, "unique_invitees": 0, "filter_type": filter_value, "public": True}

            if start_time and end_time:
                query += f" AND created_at >= ${param_index} AND created_at <= ${param_index + 1}"
                params.append(start_time)
                params.append(end_time)
                param_index += 2
            elif start_time:
                query += f" AND created_at >= ${param_index}"
                params.append(start_time)
                param_index += 1
            elif end_time:
                query += f" AND created_at <= ${param_index}"
                params.append(end_time)
                param_index += 1
            elif days:
                query += f" AND created_at >= NOW() - INTERVAL '1 day' * ${param_index}"
                params.append(days)
                param_index += 1

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'invite_tracking')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'invite_tracking',
                include_users=True, include_channels=False
            )

            row = await conn.fetchrow(query, *params)

            return {
                "guild_id": guild_id,
                "total_invites": row['total_invites'] or 0,
                "valid_invites": row['valid_invites'] or 0,
                "suspicious_invites": row['suspicious_invites'] or 0,
                "left_invites": row['left_invites'] or 0,
                "unique_inviters": row['unique_inviters'] or 0,
                "unique_invitees": row['unique_invitees'] or 0,
                "filter_type": filter_value,
                "public": True
            }

    except Exception as e:
        logger.error(f"Error in public_invite_total_stats: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/public/invite/leaderboard/users")
async def public_invite_user_leaderboard(request: Request):
    """Public endpoint to get user invite leaderboard for StatsHQ guild with role, bot, and blacklist filtering"""
    try:
        body = await request.json()
        guild_id = body.get('guild_id')

        if guild_id != STATSHQ_GUILD_ID:
            raise HTTPException(status_code=403, detail="Access denied.")

        limit = body.get('limit', 10)
        filter_type = body.get('filter_type', 'all')
        days = body.get('days', 30)
        role_filter_ids = body.get('role_filter_ids')
        start_time_str = body.get('start_time')
        end_time_str = body.get('end_time')

        start_time = datetime.fromisoformat(start_time_str.replace(
            'Z', '+00:00')) if start_time_str else None
        end_time = datetime.fromisoformat(end_time_str.replace(
            'Z', '+00:00')) if end_time_str else None

        filter_value = str(filter_type).lower()
        if filter_value not in ["all", "valid", "suspicious", "left"]:
            filter_value = "all"

        async with db_stats.pool.acquire() as conn:
            query = """
                SELECT
                    inviter_id,
                    COUNT(*) as total_invites,
                    COUNT(*) FILTER (WHERE invite_type = 'valid') as valid_invites,
                    COUNT(*) FILTER (WHERE invite_type = 'suspicious') as suspicious_invites,
                    COUNT(*) FILTER (WHERE invite_type = 'left') as left_invites
                FROM invite_tracking
                WHERE guild_id = $1
            """
            params = [int(guild_id)]
            param_index = 2

            if filter_value != "all":
                query += f" AND invite_type = ${param_index}"
                params.append(filter_value)
                param_index += 1

            if role_filter_ids and len(role_filter_ids) > 0:
                user_ids = await db_stats._get_users_with_roles(guild_id, role_filter_ids)
                if user_ids and len(user_ids) > 0:
                    placeholders = [
                        f"${param_index + i}" for i in range(len(user_ids))]
                    query += f" AND inviter_id IN ({', '.join(placeholders)})"
                    params.extend(user_ids)
                    param_index += len(user_ids)
                else:
                    return []

            if start_time and end_time:
                query += f" AND created_at >= ${param_index} AND created_at <= ${param_index + 1}"
                params.append(start_time)
                params.append(end_time)
                param_index += 2
            elif start_time:
                query += f" AND created_at >= ${param_index}"
                params.append(start_time)
                param_index += 1
            elif end_time:
                query += f" AND created_at <= ${param_index}"
                params.append(end_time)
                param_index += 1
            elif days:
                query += f" AND created_at >= NOW() - INTERVAL '1 day' * ${param_index}"
                params.append(days)
                param_index += 1

            query, params = await db_stats._apply_bot_filter(query, params, guild_id, 'invite_tracking')
            query, params = await db_stats._apply_comprehensive_blacklist_filters(
                guild_id, query, params, 'invite_tracking',
                include_users=True, include_channels=False
            )

            query += " GROUP BY inviter_id"

            if filter_value == "valid":
                sort_column = "valid_invites"
            elif filter_value == "suspicious":
                sort_column = "suspicious_invites"
            elif filter_value == "left":
                sort_column = "left_invites"
            else:
                sort_column = "total_invites"

            query += f" HAVING COUNT(*) > 0 ORDER BY {sort_column} DESC, inviter_id DESC LIMIT ${param_index}"
            params.append(limit)

            rows = await conn.fetch(query, *params)

            result = []
            for idx, row in enumerate(rows):
                inviter_id = str(row['inviter_id'])
                if inviter_id == "0":
                    continue

                user_info = await get_user_display_info(None, guild_id, int(inviter_id))

                total = row['total_invites'] or 0
                valid = row['valid_invites'] or 0
                percentage = (valid / total * 100) if total > 0 else 0

                result.append({
                    "user_id": inviter_id,
                    "username": user_info.get('name', f"User {inviter_id}"),
                    "global_name": user_info.get('global_name'),
                    "avatar": user_info.get('avatar_url'),
                    "total_invites": total,
                    "valid_invites": valid,
                    "suspicious_invites": row['suspicious_invites'] or 0,
                    "left_invites": row['left_invites'] or 0,
                    "percentage_valid": round(percentage, 1),
                    "rank": idx + 1
                })

            return result

    except Exception as e:
        logger.error(f"Error in public_invite_user_leaderboard: {e}")
        raise HTTPException(status_code=500, detail=str(e))


