@app.get("/api/public/growth/roles")
async def public_growth_roles(guild_id: str = Query(..., description="Guild ID")):
    """Public endpoint to get roles with growth data using current_role_members table."""

    # Only allow access to the public StatsHQ guild
    if guild_id != STATSHQ_GUILD_ID:
        raise HTTPException(status_code=403, detail="Access denied.")

    try:
        async with db_stats.pool.acquire() as conn:
            # Get distinct role IDs from role_growth_hourly table
            role_query = """
                SELECT DISTINCT role_id
                FROM role_growth_hourly
                WHERE guild_id = $1
                ORDER BY role_id
            """
            role_rows = await conn.fetch(role_query, int(guild_id))
            role_ids = [row['role_id'] for row in role_rows]

            if not role_ids:
                return {"success": True, "guild_id": guild_id, "roles": [], "public": True}

            # Get role names and colors from current_role_members table (NOT Discord API)
            role_ids_list = list(role_ids)
            placeholders = ','.join(
                [f'${i+2}' for i in range(len(role_ids_list))])
            details_query = f"""
                SELECT DISTINCT ON (role_id)
                    role_id,
                    role_name,
                    role_color
                FROM current_role_members
                WHERE guild_id = $1
                AND role_id IN ({placeholders})
                ORDER BY role_id
            """
            details_rows = await conn.fetch(details_query, int(guild_id), *role_ids_list)

            # Create a map of role_id -> details
            role_details_map = {}
            for row in details_rows:
                role_id = str(row['role_id'])
                role_details_map[role_id] = {
                    "name": row['role_name'] or f"Role {role_id}",
                    "color": row['role_color'] or "#99aab5"
                }

            # Build the response
            roles_with_details = []
            for role_id in role_ids:
                role_id_str = str(role_id)
                role_info = role_details_map.get(role_id_str, {})

                # Skip @everyone role if it appears
                if role_info.get('name') == '@everyone':
                    continue

                roles_with_details.append({
                    "role_id": role_id_str,
                    "name": role_info.get('name', f"Role {role_id_str}"),
                    "color": role_info.get('color', "#99aab5")
                })

            return {
                "success": True,
                "guild_id": guild_id,
                "roles": roles_with_details,
                "public": True,
                "source": "current_role_members_table"
            }

    except Exception as e:
        logger.error(f"Error in public_growth_roles: {e}")
        return {"success": True, "roles": [], "public": True, "error": str(e)}


