@app.get("/api/public/server/real-roles")
async def public_server_real_roles(
    guild_id: str = Query(..., description="Guild ID")
):
    """
    Public endpoint to get real roles - only works for StatsHQ guild.
    Uses current_role_members table with role_name and role_color.
    """
    # Only allow access to the public StatsHQ guild
    if guild_id != STATSHQ_GUILD_ID:
        raise HTTPException(
            status_code=403,
            detail="Access denied. This endpoint is only for public StatsHQ statistics."
        )

    try:
        # Validate guild_id
        try:
            guild_id_int = int(guild_id)
        except ValueError:
            raise HTTPException(
                status_code=400,
                detail=f"Invalid guild_id format: {guild_id}"
            )

        # Helper function to format role color
        def format_role_color(color):
            """Convert role color to hex string format"""
            if not color:
                return "#99aab5"  # Default Discord gray
            if isinstance(color, int):
                return f"#{color:06x}"
            if isinstance(color, str):
                return color if color.startswith('#') else f"#{color}"
            return "#99aab5"

        # Get roles from current_role_members table
        try:
            async with db_stats.pool.acquire() as conn:
                role_rows = await conn.fetch("""
                    SELECT DISTINCT 
                        role_id, 
                        role_name, 
                        role_color,
                        MAX(updated_at) as last_updated
                    FROM current_role_members
                    WHERE guild_id = $1
                    AND role_id IS NOT NULL
                    AND role_name IS NOT NULL  -- Only return roles with names
                    GROUP BY role_id, role_name, role_color
                    ORDER BY role_id
                    LIMIT 100  -- Limit for public endpoint
                """, guild_id_int)

                if not role_rows:
                    logger.warning(
                        f"No roles found in current_role_members for guild {guild_id}")
                    return []

                # Format the response
                roles = []
                for row in role_rows:
                    role_id = str(row['role_id'])
                    role_name = row.get('role_name', f"Role {role_id}")
                    role_color = row.get('role_color', "#99aab5")

                    # Format color safely
                    role_color = format_role_color(role_color)

                    roles.append({
                        "id": role_id,
                        "name": role_name,
                        "color": role_color,
                        "public": True
                    })

                # Sort by role_id
                roles.sort(key=lambda x: x['id'])

                return roles

        except asyncpg.PostgresError as e:
            logger.error(f"Database error fetching public roles: {e}")
            return []

    except Exception as e:
        logger.error(f"Error in public_server_real_roles: {e}", exc_info=True)
        return []

