@app.get("/api/auth/discord")
async def auth_discord(returnTo: Optional[str] = None):
    """Redirect to Discord OAuth"""
    params = {
        'client_id': CLIENT_ID,
        'redirect_uri': DISCORD_REDIRECT_URI,
        'response_type': 'code',
        'scope': 'identify guilds guilds.members.read',
        'prompt': 'consent'
    }

    if returnTo:
        params['state'] = returnTo

    url = f"{DISCORD_AUTH_URL}?{'&'.join(f'{k}={v}' for k,
                                         v in params.items())}"
    return RedirectResponse(url)


# Remove the decorator - we'll handle rate limiting internally
async def sync_guilds_background(user_info: dict, access_token: str, is_new_user: bool):
    """Background task to sync guilds and permissions for new users"""
    try:
        if not is_new_user:
            return

        rate_limiter = get_rate_limiter()

        # =========================
        # GUILD SCAN
        # =========================
        guild_scan_start = time.time()

        # ✅ Rate limit before calling Discord API
        if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
            print(
                f"⚠️ Rate limited for user {user_info['id']} guild scan, waiting...")
            await asyncio.sleep(5)
            # Try one more time
            if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                print(
                    f"❌ Still rate limited, skipping guild scan for user {user_info['id']}")
                return

        user_guilds = await discord_api.get_user_guilds(access_token)
        guild_scan_time = time.time() - guild_scan_start

        # =========================
        # PERMISSION SCAN (bot guild check)
        # =========================
        permission_scan_start = time.time()
        guild_ids = [g['id'] for g in user_guilds]

        # ✅ Rate limit before bulk check (this might make multiple API calls)
        if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
            print(
                f"⚠️ Rate limited for user {user_info['id']} permission scan, waiting...")
            await asyncio.sleep(5)
            if not await rate_limiter.acquire(RateLimitType.API, timeout=30.0):
                print(
                    f"❌ Still rate limited, skipping permission scan for user {user_info['id']}")
                return

        bot_guilds_map = await discord_api.check_bot_in_guild_bulk(guild_ids)
        permission_scan_time = time.time() - permission_scan_start

        servers_to_store = []
        async with auth_db.pool.acquire() as conn:
            for guild in user_guilds:
                guild_id = str(guild['id'])
                member_count = bot_guilds_map.get(guild_id)

                if member_count is None:
                    continue  # bot not in guild

                permissions = guild.get('permissions', '0')
                if not isinstance(permissions, str):
                    permissions = str(permissions)

                # Update global guild table
                await conn.execute("""
                    INSERT INTO guilds (guild_id, guild_name, guild_icon, member_count)
                    VALUES ($1, $2, $3, $4)
                    ON CONFLICT (guild_id) DO UPDATE SET
                        guild_name = EXCLUDED.guild_name,
                        guild_icon = EXCLUDED.guild_icon,
                        member_count = EXCLUDED.member_count,
                        last_updated = CURRENT_TIMESTAMP
                """, guild_id, guild['name'], guild.get('icon'), member_count)

                # Insert into user_servers
                await conn.execute("""
                    INSERT INTO user_servers 
                    (discord_id, guild_id, guild_name, guild_icon, member_count, permissions)
                    VALUES ($1, $2, $3, $4, $5, $6)
                """, user_info['id'], guild_id, guild['name'],
                    guild.get('icon'), member_count, permissions)

                servers_to_store.append(guild_id)

        # Set default selected server
        if servers_to_store:
            user = await auth_db.get_user_by_discord_id(user_info['id'])
            if user and not user.get('selected_server'):
                if STATSHQ_GUILD_ID in servers_to_store:
                    await auth_db.update_user_selected_server(user_info['id'], STATSHQ_GUILD_ID)
                else:
                    await auth_db.update_user_selected_server(user_info['id'], servers_to_store[0])

        total_time = guild_scan_time + permission_scan_time
        print(
            f"✅ Complete background sync finished in {total_time:.2f} seconds total")

    except Exception as e:
        logger.error(
            f"Background guild sync failed for user {user_info['id']}: {e}", exc_info=True)


@app.get("/api/auth/discord/callback")
@fastapi_rate_limited(RateLimitType.API, timeout=30.0)
async def auth_callback(
    request: Request,
    code: str,
    state: Optional[str] = None,
    background_tasks: BackgroundTasks = None
):
    """Handle Discord OAuth callback"""
    is_production = os.getenv('NODE_ENV') == 'production'

    try:
        token_data = await discord_api.exchange_code(code)
        user_info = await discord_api.get_user_info(token_data['access_token'])
        token_expiry = datetime.utcnow(
        ) + timedelta(seconds=token_data['expires_in'])
        user_data = {
            'discord_id': user_info['id'],
            'username': user_info['username'],
            'global_name': user_info.get('global_name'),
            'discriminator': user_info.get('discriminator'),
            'avatar': user_info.get('avatar'),
            'email': user_info.get('email'),
            'access_token': token_data['access_token'],
            'refresh_token': token_data.get('refresh_token'),
            'token_expiry': token_expiry
        }
        existing_user = await auth_db.get_user_by_discord_id(user_info['id'])
        is_new_user = existing_user is None
        # Save/update user immediately
        user = await auth_db.create_or_update_user(user_data)
        # Queue background guild sync for new users
        if is_new_user and background_tasks:
            background_tasks.add_task(
                sync_guilds_background,
                user_info,
                token_data['access_token'],
                is_new_user
            )
        # Create session
        client_ip = request.client.host if request.client else None
        user_agent = request.headers.get('user-agent')
        session_id = await auth_db.create_session(user_info['id'], client_ip, user_agent)
        # Ensure state is a valid URL and not empty
        redirect_url = str(state) if state and state.startswith(
            ('http://', 'https://')) else BASE_URL
        # If state looks like a path only (starts with /), join it with BASE_URL
        if state and not state.startswith(('http://', 'https://', '/api')):
            redirect_url = BASE_URL.rstrip('/')
        elif state and state.startswith('/'):
            redirect_url = BASE_URL.rstrip('/') + state
        else:
            redirect_url = BASE_URL or 'https://statshq.xyz'
        logger.info(f"Redirecting to: {redirect_url}")
        response = RedirectResponse(url=redirect_url)
        response.set_cookie(
            key="session",
            value=session_id,
            httponly=True,
            secure=is_production,
            samesite="lax",
            max_age=30 * 24 * 60 * 60,
            path="/"
        )
        return response
    except (DatabaseError, ExternalAPIError) as e:
        logger.error(f"Auth callback error: {e}", exc_info=True)
        return RedirectResponse(url=f"{BASE_URL}?error=auth_failed")
    except Exception as e:
        logger.error(f"Unexpected auth callback error: {e}", exc_info=True)
        return RedirectResponse(url=f"{BASE_URL}?error=auth_failed")


@app.get("/api/auth/status", response_model=AuthStatusResponse)
async def auth_status(user: Optional[Dict] = Depends(get_current_user)):
    """Check if user is authenticated"""
    if not user:
        return AuthStatusResponse(authenticated=False)

    return AuthStatusResponse(
        authenticated=True,
        user={
            'id': user['discord_id'],
            'username': user['username'],
            'global_name': user['global_name'],
            'avatar': user['avatar'],
            'selected_server': user.get('selected_server')
        }
    )


@app.post("/api/auth/logout")
async def auth_logout(
    response: Response,
    session_id: Optional[str] = Cookie(None, alias="session")
):
    """Log out user"""
    if session_id:
        try:
            await auth_db.delete_session(session_id)
            # Also invalidate server cache on logout
            if user := await get_current_user(session_id):
                await db_stats.invalidate_user_server_cache(user['discord_id'])
        except DatabaseError as e:
            logger.error(f"Error deleting session: {e}")

    response.delete_cookie("session", path="/")
    return {"success": True, "message": "Logged out successfully"}


