@app.get("/api/health")
async def health_check():
    """Health check endpoint"""
    try:
        return {
            "status": "healthy",
            "database": "connected" if db_stats.db_connected else "disconnected",
            "timestamp": datetime.utcnow().isoformat()
        }
    except Exception as e:
        logger.error(f"Health check error: {e}")
        return {
            "status": "unhealthy",
            "error": str(e),
            "timestamp": datetime.utcnow().isoformat()
        }


@app.get("/api/activity/health")
async def activity_health_check():
    """Activity-specific health check"""
    try:
        conn = await db_stats.get_connection()
        await db_stats.release_connection(conn)

        return {
            "status": "healthy",
            "database": "connected",
            "activity_tables": "present",
            "timestamp": datetime.utcnow().isoformat()
        }
    except DatabaseError as e:
        return {
            "status": "unhealthy",
            "database": "disconnected",
            "error": str(e),
            "timestamp": datetime.utcnow().isoformat()
        }
    except Exception as e:
        return {
            "status": "unhealthy",
            "database": "disconnected",
            "error": str(e),
            "timestamp": datetime.utcnow().isoformat()
        }

