@app.get("/api/debug/pool-status")
async def debug_pool_status():
    """Check if the database pool is actually working"""
    status = {
        "pool_exists": db_stats.pool is not None,
        "db_connected_flag": db_stats.db_connected,
        "test_query": None
    }

    if db_stats.pool:
        try:
            async with db_stats.pool.acquire() as conn:
                result = await conn.fetchval("SELECT 1")
                status["test_query"] = result == 1
                status["test_query_result"] = result
        except Exception as e:
            status["test_query_error"] = str(e)
    else:
        status["error"] = "Pool is None"

    return status


